-- Seed translated instructions from Gemini
UPDATE public.exercises SET instructions_es = 'Acuéstate en el suelo y asegura tus pies. Las piernas deben estar dobladas por las rodillas.
Coloca las manos detrás o a los lados de la cabeza. Comenzarás con la espalda en el suelo. Esta será tu posición inicial.
Flexiona las caderas y la columna para elevar el torso hacia las rodillas.
En la parte superior de la contracción, el torso debe quedar perpendicular al suelo. Invierte el movimiento, bajando solo ¾ del recorrido.
Repite la cantidad de repeticiones recomendada.' WHERE name_en = '3/4 Sit-Up';
UPDATE public.exercises SET instructions_es = 'Acuéstate boca arriba, con una pierna extendida hacia adelante.
Con la otra pierna, flexiona la cadera y la rodilla a 90 grados. Puedes sujetar la pierna con las manos si es necesario. Esta será tu posición inicial.
Extiende la pierna hacia arriba en el aire, haciendo una breve pausa en la parte superior. Regresa la pierna a la posición inicial.
Repite de 10 a 20 repeticiones y luego cambia a la otra pierna.' WHERE name_en = '90/90 Hamstring';
UPDATE public.exercises SET instructions_es = 'Selecciona una resistencia ligera y siéntate en la máquina de abdominales colocando los pies debajo de los cojines provistos y sujetando los agarres superiores. Los brazos deben estar doblados en un ángulo de 90 grados mientras apoyas los tríceps en los cojines provistos. Esta será tu posición inicial.
Al mismo tiempo, comienza a levantar las piernas mientras flexionas el torso hacia adelante. Exhala mientras realizas este movimiento. Consejo: Asegúrate de realizar un movimiento lento y controlado. Concéntrate en usar tus abdominales para mover el peso mientras relajas las piernas y los pies.
Tras una pausa de un segundo, regresa lentamente a la posición inicial mientras inhalas.
Repite el movimiento la cantidad de repeticiones prescrita.' WHERE name_en = 'Ab Crunch Machine';
UPDATE public.exercises SET instructions_es = 'Sujeta la rueda abdominal con ambas manos y arrodíllate en el suelo.
Ahora coloca la rueda abdominal en el suelo frente a ti, de modo que quedes apoyado sobre las manos y las rodillas (como en una posición de flexión con rodillas apoyadas). Esta será tu posición inicial.
Haz rodar lentamente la rueda abdominal hacia adelante, estirando tu cuerpo en una posición recta. Consejo: Baja todo lo que puedas sin tocar el suelo con el cuerpo. Inhala durante esta fase del movimiento.
Tras una pausa en la posición estirada, comienza a tirar de ti mismo de regreso a la posición inicial mientras exhalas. Consejo: Ve despacio y mantén los abdominales contraídos en todo momento.' WHERE name_en = 'Ab Roller';
UPDATE public.exercises SET instructions_es = 'Acuéstate boca abajo con una pierna sobre un rodillo de espuma.
Gira la pierna para que el rodillo de espuma haga contacto con la cara interna del muslo. Transfiere al rodillo de espuma todo el peso que puedas tolerar.
Mientras intentas relajar los músculos del muslo interno, rueda sobre la espuma entre la cadera y la rodilla, manteniendo los puntos de tensión durante 10-30 segundos. Repite con la otra pierna.' WHERE name_en = 'Adductor';
UPDATE public.exercises SET instructions_es = 'Acuéstate boca arriba con los pies elevados hacia el techo.
Haz que tu compañero sostenga tus pies o tobillos. Separa las piernas lo más que puedas. Esta será tu posición inicial.
Intenta juntar las piernas durante 10 segundos o más, mientras tu compañero te lo impide.
Ahora, relaja los músculos de las piernas mientras tu compañero separa tus pies, estirando hasta donde te resulte cómodo. Asegúrate de avisar a tu compañero cuando el estiramiento sea adecuado para evitar un estiramiento excesivo o lesiones.' WHERE name_en = 'Adductor/Groin';
UPDATE public.exercises SET instructions_es = 'Haz una cargada y press de una pesa rusa por encima de la cabeza con un brazo.
Manteniendo la pesa rusa bloqueada arriba en todo momento, empuja los glúteos hacia afuera en la dirección de la pesa rusa bloqueada. Mantén el brazo que no trabaja detrás de la espalda y gira los pies hacia afuera en un ángulo de cuarenta y cinco grados con respecto al brazo con la pesa rusa.
Baja lo más posible.
Haz una pausa de un segundo e invierte el movimiento para volver a la posición inicial.' WHERE name_en = 'Advanced Kettlebell Windmill';
UPDATE public.exercises SET instructions_es = 'Acuéstate boca arriba en el suelo con la zona lumbar presionada contra el suelo. Para este ejercicio, deberás poner las manos al lado de la cabeza. Sin embargo, ten cuidado de no forzar el cuello al realizarlo. Ahora levanta los hombros en posición de encogimiento.
Lleva las rodillas hacia arriba hasta que queden perpendiculares al suelo, con la parte inferior de las piernas paralelas al suelo. Esta será tu posición inicial.
Ahora, de forma simultánea, realiza lentamente un movimiento de pedaleo de bicicleta pateando hacia adelante con la pierna derecha y acercando la rodilla de la pierna izquierda. Lleva el codo derecho cerca de la rodilla izquierda flexionando hacia el lado, mientras exhalas.
Regresa a la posición inicial mientras inhalas.
Flexiona hacia el lado opuesto mientras pedaleas con las piernas y acerques el codo izquierdo a la rodilla derecha y exhala.
Continúa alternando de esta manera hasta completar todas las repeticiones recomendadas para cada lado.' WHERE name_en = 'Air Bike';
UPDATE public.exercises SET instructions_es = 'Comienza a cuatro patas, luego levanta una pierna del suelo y sujeta el pie con la mano.
Usa la mano para sujetar el pie o el tobillo, manteniendo la rodilla completamente flexionada, estirando los cuádriceps y los flexores de la cadera.
Concéntrate en extender las caderas, empujándolas hacia el suelo. Mantén la posición durante 10-20 segundos y luego cambia de lado.' WHERE name_en = 'All Fours Quad Stretch';
UPDATE public.exercises SET instructions_es = 'Ponte de pie con el torso erguido y una mancuerna en cada mano sostenida a la longitud de los brazos. Los codos deben estar cerca del torso.
Las palmas de las manos deben estar mirando hacia tu torso. Esta será tu posición inicial.
Manteniendo la parte superior del brazo inmóvil, flexiona el peso derecho hacia adelante mientras contraes el bíceps al exhalar. Continúa el movimiento hasta que el bíceps esté completamente contraído y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante un segundo mientras aprietas el bíceps. Consejo: Solo deben moverse los antebrazos.
Comienza a bajar lentamente las mancuernas a la posición inicial mientras inhalas.
Repite el movimiento con la mano izquierda. Esto equivale a una repetición.
Continúa alternando de esta manera durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Alternate Hammer Curl';
UPDATE public.exercises SET instructions_es = 'Acuéstate en el suelo con las rodillas dobladas y los pies en el suelo separados unos 45-60 cm (18-24 pulgadas). Los brazos deben estar extendidos a los lados. Esta será tu posición inicial.
Eleva el torso hacia adelante y arriba unos 7-10 cm (3-4 pulgadas) hacia el lado derecho y toca el talón derecho mientras mantienes la contracción durante un segundo. Exhala mientras realizas este movimiento.
Ahora regresa lentamente a la posición inicial mientras inhalas.
Ahora eleva el torso hacia adelante y arriba unos 7-10 cm (3-4 pulgadas) hacia el lado izquierdo y toca el talón izquierdo mientras mantienes la contracción durante un segundo. Exhala mientras realizas este movimiento y luego regresa a la posición inicial mientras inhalas. Una vez tocados ambos talones, se considera 1 repetición.
Continúa alternando lados de esta manera hasta realizar todas las repeticiones prescritas.' WHERE name_en = 'Alternate Heel Touchers';
UPDATE public.exercises SET instructions_es = 'Siéntate en un banco inclinado con una mancuerna en cada mano sostenida a la longitud de los brazos. Consejo: Mantén los codos cerca del torso. Esta será tu posición inicial.
Manteniendo la parte superior del brazo inmóvil, flexiona el peso derecho hacia adelante mientras contraes el bíceps al exhalar. Al hacerlo, gira la mano de modo que la palma quede mirando hacia arriba. Continúa el movimiento hasta que el bíceps esté completamente contraído y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante un segundo mientras aprietas el bíceps. Consejo: Solo deben moverse los antebrazos.
Comienza a bajar lentamente la mancuerna a la posición inicial mientras inhalas.
Repite el movimiento con la mano izquierda. Esto equivale a una repetición.
Continúa alternando de esta manera durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Alternate Incline Dumbbell Curl';
UPDATE public.exercises SET instructions_es = 'Adopta una postura cómoda con un pie ligeramente delante del otro.
Comienza impulsándote con la pierna delantera, llevando la rodilla opuesta hacia adelante y lo más alto posible antes de aterrizar. Intenta cubrir la mayor distancia posible hacia cada lado con cada salto.
Puede ser útil usar una línea en el suelo para medir la distancia de un lado a otro.
Repite la secuencia con la otra pierna.' WHERE name_en = 'Alternate Leg Diagonal Bound';
UPDATE public.exercises SET instructions_es = 'Mueve los cables a la parte inferior de la torre y selecciona un peso adecuado.
Sujeta los cables y mantenlos a la altura de los hombros, con las palmas mirando hacia adelante. Esta será tu posición inicial.
Manteniendo la cabeza y el pecho erguidos, extiende el codo para empujar un lado directamente por encima de la cabeza.
Tras hacer una pausa en la parte superior, regresa a la posición inicial y repite en el lado opuesto.' WHERE name_en = 'Alternating Cable Shoulder Press';
UPDATE public.exercises SET instructions_es = 'De pie, sostén un par de mancuernas a los lados.
Manteniendo los codos ligeramente doblados, eleva los pesos directamente frente a ti hasta la altura de los hombros, evitando balanceos o trampas.
Regresa las mancuernas a los lados.
En la siguiente repetición, eleva los pesos lateralmente, llevándolos hacia los lados hasta aproximadamente la altura de los hombros.
Regresa las mancuernas a la posición inicial y continúa alternando hacia adelante y hacia los lados.' WHERE name_en = 'Alternating Deltoid Raise';
UPDATE public.exercises SET instructions_es = 'Acuéstate en el suelo con dos pesas rusas junto a tus hombros.
Coloca una en su lugar sobre tu pecho y luego la otra, agarrando las pesas rusas por el asa con las palmas mirando hacia adelante.
Extiende ambos brazos, de modo que sostengas las pesas rusas por encima del pecho. Baja una pesa rusa llevándola hacia el pecho y gira la muñeca en la dirección de la pesa rusa bloqueada arriba.
Eleva la pesa rusa y repite en el lado opuesto.' WHERE name_en = 'Alternating Floor Press';
UPDATE public.exercises SET instructions_es = 'Coloca dos pesas rusas entre tus pies. Para ponerte en la posición inicial, empuja los glúteos hacia atrás y mira hacia adelante.
Haz una cargada con una pesa rusa hasta el hombro y mantén la otra pesa rusa colgada. Lleva la pesa rusa al hombro extendiendo las piernas y las caderas mientras tiras de ella hacia los hombros. Gira la muñeca al hacerlo.
Baja la pesa rusa cargada a la posición colgada e inicia la cargada con la pesa rusa contraria. Repite.' WHERE name_en = 'Alternating Hang Clean';
UPDATE public.exercises SET instructions_es = 'Haz una cargada con dos pesas rusas hasta tus hombros. Lleva las pesas rusas a los hombros extendiendo las piernas y las caderas mientras tiras de ellas hacia los hombros. Gira las muñecas al hacerlo.
Empuja una directamente por encima de la cabeza extendiendo el codo, girándola para que la palma mire hacia adelante mientras mantienes la otra pesa rusa inmóvil.
Baja la pesa rusa presionada a la posición inicial y presiona inmediatamente con el otro brazo.' WHERE name_en = 'Alternating Kettlebell Press';
UPDATE public.exercises SET instructions_es = 'Coloca dos pesas rusas frente a tus pies. Dobla ligeramente las rodillas y empuja los glúteos hacia atrás tanto como sea posible. Al inclinarte para colocarte en la posición inicial, agarra ambas pesas rusas por las asas.
Levanta una pesa rusa del suelo mientras sostienes la otra pesa rusa. Retrae la escápula del lado que trabaja mientras flexionas el codo, llevando la pesa rusa hacia tu estómago o caja torácica.
Baja la pesa rusa del brazo activo y repite con el otro brazo.' WHERE name_en = 'Alternating Kettlebell Row';
UPDATE public.exercises SET instructions_es = 'Coloca dos pesas rusas en el suelo separadas aproximadamente al ancho de los hombros. Colócate sobre la punta de los pies y las manos como si fueras a hacer una flexión, con el cuerpo recto y extendido. Usa las asas de las pesas rusas para apoyar la parte superior del cuerpo. Es posible que necesites abrir los pies para obtener más estabilidad.
Empuja una pesa rusa contra el suelo y rema la otra pesa rusa, retrayendo la escápula del lado que trabaja mientras flexionas el codo, llevándola hacia tu costado.
Luego baja la pesa rusa al suelo y comienza con la pesa rusa de la mano opuesta. Repite durante varias repeticiones.' WHERE name_en = 'Alternating Renegade Row';
UPDATE public.exercises SET instructions_es = 'Usa un objeto firme como un rack de sentadillas para sujetarte.
Levanta la pierna derecha en el aire (a unos 5 cm / 2 pulgadas del suelo) y realiza un movimiento circular con el dedo gordo del pie. Imagina que estás dibujando un gran círculo con él. Consejo: Un círculo equivale a 1 repetición. Respira con normalidad mientras realizas el movimiento.
Cuando termines con el pie derecho, repite con la pierna izquierda.' WHERE name_en = 'Ankle Circles';
UPDATE public.exercises SET instructions_es = 'Desde una posición acostada, dobla las rodillas y mantén los pies en el suelo.
Coloca el tobillo de un pie sobre la rodilla opuesta.
Sujeta el muslo o la rodilla de la pierna de abajo y tira de ambas piernas hacia el pecho. Relaja el cuello y los hombros. Mantén la posición durante 10-20 segundos y luego cambia de lado.' WHERE name_en = 'Ankle On The Knee';
UPDATE public.exercises SET instructions_es = 'Comienza sentado en el suelo con las piernas dobladas y los pies en el suelo.
Usando un rodillo muscular o un rodillo de cocina, aplica presión en los músculos de la parte externa de las espinillas. Trabaja desde justo debajo de la rodilla hasta por encima del tobillo, haciendo pausas en los puntos de tensión durante 10-30 segundos. Repite en la otra pierna.' WHERE name_en = 'Anterior Tibialis-SMR';
UPDATE public.exercises SET instructions_es = 'Coloca una barra en el suelo detrás de la cabeza de un banco inclinado.
Acuéstate boca abajo en el banco. Con un agarre prono, levanta la barra del suelo. Flexiona los codos realizando un curl inverso para llevar la barra cerca del pecho. Esta será tu posición inicial.
Para comenzar, empuja la barra hacia adelante enfrente de tu cabeza extendiendo los codos. Mantén los brazos paralelos al suelo durante todo el movimiento.
Regresa a la posición inicial y repite para completar la serie.' WHERE name_en = 'Anti-Gravity Press';
UPDATE public.exercises SET instructions_es = 'Ponte de pie y extiende los brazos hacia los lados. Los brazos deben estar paralelos al suelo y perpendiculares (ángulo de 90 grados) a tu torso. Esta será tu posición inicial.
Comienza a hacer círculos lentamente de unos 30 cm (1 pie) de diámetro con cada brazo extendido. Respira normalmente mientras realizas el movimiento.
Continúa el movimiento circular de los brazos extendidos durante unos diez segundos. Luego invierte el movimiento, yendo en la dirección opuesta.' WHERE name_en = 'Arm Circles';
UPDATE public.exercises SET instructions_es = 'Siéntate en un banco de ejercicios con respaldo y sostén dos mancuernas frente a ti a la altura de la parte superior del pecho, con las palmas mirando hacia tu cuerpo y los codos doblados. Consejo: tus brazos deben estar junto al torso. La posición inicial debe parecerse a la parte contraída de un curl con mancuernas.
Ahora, para realizar el movimiento, levanta las mancuernas a medida que giras las palmas de las manos hasta que queden mirando hacia adelante.
Continúa levantando las mancuernas hasta que tus brazos queden extendidos por encima de ti en una posición de brazos estirados. Exhala mientras realizas esta parte del movimiento.
Tras una pausa de un segundo en la parte superior, comienza a bajar las mancuernas a la posición original girando las palmas de las manos hacia ti. Consejo: el brazo izquierdo se girará en sentido contrario a las agujas del reloj, mientras que el derecho se girará en el sentido de las agujas del reloj. Inhala mientras realizas esta parte del movimiento.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Arnold Dumbbell Press';
UPDATE public.exercises SET instructions_es = 'Acuéstate en un banco plano sosteniendo una mancuerna en cada mano con las palmas mirando hacia el techo. Consejo: tus brazos deben estar paralelos al suelo y junto a tus muslos. Para evitar lesiones, asegúrate de mantener los codos ligeramente doblados. Esta será tu posición inicial.
Ahora mueve las mancuernas creando un semicírculo a medida que las desplazas desde la posición inicial hasta por encima de la cabeza. Todo el movimiento debe realizarse con los brazos paralelos al suelo en todo momento. Inhala mientras realizas esta parte del movimiento.
Invierte el movimiento para regresar el peso a la posición inicial mientras exhalas.' WHERE name_en = 'Around The Worlds';
UPDATE public.exercises SET instructions_es = 'Este ejercitador es efectivo para desarrollar fuerza para las Piedras de Atlas en personas que no tienen acceso a piedras, y generalmente se fabrica con extremos de barra o tubos pesados.
Comienza cargando el peso deseado en la barra. Colócate a horcajadas sobre el peso, envolviendo tus brazos alrededor del implemento y doblando la cadera.
Comienza levantando el peso por encima de las rodillas, extendiendo la cadera. Una vez que el peso supere las rodillas, puedes apoyarlo en el regazo e inclinarte hacia atrás, abrazándolo fuertemente contra el pecho.
Finaliza el movimiento extendiendo la cadera y las rodillas para elevar el peso lo más alto posible. El peso se puede regresar al regazo o al suelo para las repeticiones sucesivas.' WHERE name_en = 'Atlas Stone Trainer';
UPDATE public.exercises SET instructions_es = 'Comienza con la piedra de Atlas entre tus pies. Dóblate por la cadera para envolver verticalmente tus brazos alrededor de la piedra de Atlas, intentando colocar los dedos por debajo de ella. Muchas piedras tienen una pequeña parte plana en la base, lo que facilitará su agarre.
Tirando de la piedra hacia tu torso, empuja con la parte trasera de los pies para levantar la piedra del suelo.
A medida que la piedra supere las rodillas, apóyala en el regazo sentándote hacia atrás y llevándola sobre tus muslos.
Siéntate profundo, subiendo la piedra a la parte alta del pecho mientras cambias el agarre para alcanzar por encima de la piedra. Ponte de pie empujando con la cadera. Acércate a la plataforma de carga e inclínate hacia atrás, extendiendo la cadera para elevar la piedra lo más alto posible.' WHERE name_en = 'Atlas Stones';
UPDATE public.exercises SET instructions_es = 'Acércate a la barra de modo que quede centrada sobre tus pies. Tus pies deben estar separados aproximadamente al ancho de las caderas. Dóblate por la cadera para agarrar la barra a la anchura de los hombros, permitiendo que las escápulas se proyecten hacia adelante. Por lo general, se utiliza un agarre mixto (prono/supino).
Con los pies y el agarre en su lugar, toma una inhalación profunda, luego baja las caderas y flexiona las rodillas hasta que las espinillas entren en contacto con la barra. Mira hacia adelante con la cabeza, mantén el pecho erguido y la espalda arqueada, y comienza a empujar a través de los talones para mover el peso hacia arriba.
Una vez que la barra supere las rodillas, tira agresivamente de la barra hacia atrás, juntando las escápulas mientras empujas las caderas hacia adelante contra la barra.
Baja la barra doblándote por la cadera y guiándola hacia el suelo.' WHERE name_en = 'Axle Deadlift';
UPDATE public.exercises SET instructions_es = 'Pasa una banda elástica alrededor de un poste fijo, como el de un rack de sentadillas.
Sujeta la banda por los agarres y da unos pasos hacia atrás para aumentar la tensión de la banda.
Extiende y eleva los brazos rectos frente a ti. Consejo: tus brazos deben estar rectos y paralelos al suelo a la vez que perpendiculares a tu torso. Tus pies deben estar firmemente apoyados en el suelo, separados a la anchura de los hombros. Esta será tu posición inicial.
Mientras exhalas, mueve los brazos hacia los lados y hacia atrás. Mantén los brazos extendidos y paralelos al suelo. Continúa el movimiento hasta que los brazos queden extendidos hacia tus lados.
Tras una pausa, regresa a la posición original mientras inhalas.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Back Flyes - With Bands';
UPDATE public.exercises SET instructions_es = 'Carga un trineo con el peso deseado y engancha una cuerda o correas al trineo para sostenerlas.
Comienza el ejercicio desplazándote hacia atrás durante una distancia determinada. Inclinándote hacia atrás, da pasos cortos extendiendo las piernas para moverte lo más rápido posible.' WHERE name_en = 'Backward Drag';
UPDATE public.exercises SET instructions_es = 'Este ejercicio se realiza mejor con un compañero. Si no tienes compañero, la pelota se puede lanzar y recoger, o lanzar contra una pared.
Comienza de pie a unos metros delante de tu compañero, ambos mirando en la misma dirección. Empieza sosteniendo la pelota entre tus piernas.
Haz una sentadilla y luego invierte la dirección con fuerza, llegando a la extensión completa mientras lanzas la pelota por encima de tu cabeza a tu compañero.
Tu compañero puede entonces devolverte la pelota rodando. Repite durante el número deseado de repeticiones.' WHERE name_en = 'Backward Medicine Ball Throw';
UPDATE public.exercises SET instructions_es = 'Coloca una tabla de equilibrio frente a ti.
Ponte de pie sobre ella e intenta mantener el equilibrio.
Mantén el equilibrio durante el tiempo deseado.' WHERE name_en = 'Balance Board';
UPDATE public.exercises SET instructions_es = 'Comienza en el suelo acostado boca arriba con los pies encima de la pelota.
Coloca la pelota de modo que, cuando las piernas estén extendidas, tus tobillos queden sobre la pelota. Esta será tu posición inicial.
Eleva las caderas del suelo, manteniendo tu peso sobre las escápulas y los pies.
Flexiona las rodillas, arrastrando la pelota lo más cerca de ti que puedas, contrayendo los isquiotibiales.
Tras una breve pausa, regresa a la posición inicial.' WHERE name_en = 'Ball Leg Curl';
UPDATE public.exercises SET instructions_es = 'Pasa la banda formando un nudo alrededor del centro de la barra de dominadas. Puedes utilizar diferentes bandas para proporcionar distintos niveles de asistencia.
Tira del extremo de la banda hacia abajo y coloca una rodilla flexionada dentro del bucle, asegurándote de que no se resbale. Toma la barra con un agarre de medio a ancho. Esta será tu posición inicial.
Lévantate hacia arriba contrayendo los dorsales a medida que flexionas el codo. El codo debe dirigirse hacia tu costado. Tira hacia el frente, intentando pasar la barbilla por encima de la barra. Evita balanceos o tirones bruscos.
Tras una breve pausa, regresa a la posición inicial.' WHERE name_en = 'Band Assisted Pull-Up';
UPDATE public.exercises SET instructions_es = 'Con una banda de 41 pulgadas, písala por un extremo separando un poco los pies. Dóblate por la cadera para colocar el otro extremo de la banda detrás de tu cuello. Esta será tu posición inicial.
Manteniendo las piernas rectas, extiende la cadera para llegar a una posición casi vertical.
Asegúrate de no redondear la espalda mientras bajas de nuevo a la posición inicial.' WHERE name_en = 'Band Good Morning';
UPDATE public.exercises SET instructions_es = 'Pasa la banda alrededor de un poste. A cierta distancia de pie, coloca el extremo opuesto alrededor del cuello. Tus manos pueden ayudar a sujetar la banda en su posición.
Comienza doblándote por la cadera, llevando los glúteos lo más atrás posible. Mantén la espalda plana e inclínate hacia adelante hasta alcanzar unos 90 grados. Las rodillas solo deben estar ligeramente dobladas.
Regresa a la posición inicial empujando con la cadera para volver a quedar de pie.' WHERE name_en = 'Band Good Morning (Pull Through)';
UPDATE public.exercises SET instructions_es = 'Ancla una banda elástica alrededor de un poste sólido u otro objeto.
Ponte de pie con tu lado izquierdo mirando hacia el poste y pasa el pie derecho a través de la banda, colocándola alrededor del tobillo.
Ponte recto y sujétate al poste si es necesario. Esta será tu posición inicial.
Manteniendo la rodilla recta, eleva la pierna derecha hacia un lado lo más lejos que puedas.
Regresa a la posición inicial y repite durante el número deseado de repeticiones.
Cambia de lado.' WHERE name_en = 'Band Hip Adductions';
UPDATE public.exercises SET instructions_es = 'Comienza con los brazos extendidos directamente frente a ti, sosteniendo la banda con ambas manos.
Inicia el movimiento realizando un movimiento de apertura invertida, moviendo las manos lateralmente hacia los lados.
Mantén los codos extendidos mientras realizas el movimiento, llevando la banda hacia el pecho. Asegúrate de mantener los hombros hacia atrás durante el ejercicio.
Haz una pausa al completar el movimiento y regresa a la posición inicial de forma controlada.' WHERE name_en = 'Band Pull Apart';
UPDATE public.exercises SET instructions_es = 'Fija una banda a la base de un rack o del banco. Acuéstate en el banco de modo que la banda quede alineada con tu cabeza.
Toma la banda y eleva los codos de forma que la parte superior del brazo quede perpendicular al suelo. Con el codo flexionado, la banda debe quedar por encima de tu cabeza. Esta será tu posición inicial.
Extiende el codo para estirar el brazo, manteniendo la parte superior del brazo en su sitio. Haz una pausa en la parte superior del movimiento y regresa a la posición inicial.' WHERE name_en = 'Band Skull Crusher';
UPDATE public.exercises SET instructions_es = 'Para este ejercicio necesitarás ponerte en posición de flexión, pero en lugar de tener las manos en el suelo, estarás sujetando una barra olímpica (cargada con 5-10 lb a cada lado). Esta será tu posición inicial.
Manteniendo un ligero arco en la espalda, eleva las caderas y rueda la barra hacia tus pies mientras exhalas. Consejo: a medida que realizas el movimiento, tus glúteos deben subir, debes mantener los abdominales contraídos y mantener la postura de la espalda en todo momento. Asimismo, tus brazos deben permanecer perpendiculares al suelo durante todo el movimiento. De lo contrario, trabajarás los hombros y la espalda más que los abdominales.
Tras una segunda contracción en la parte superior, comienza a rodar la barra lentamente hacia adelante de vuelta a la posición inicial mientras inhalas.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Barbell Ab Rollout';
UPDATE public.exercises SET instructions_es = 'Sostén una barra olímpica cargada con 5-10 lb a cada lado y ponte de rodillas en el suelo.
Ahora coloca la barra en el suelo frente a ti, de modo que quedes a cuatro patas (como en una posición de flexión con rodillas apoyadas). Esta será tu posición inicial.
Rueda lentamente la barra recto hacia adelante, estirando tu cuerpo hasta una posición recta. Consejo: baja lo más lejos que puedas sin llegar a tocar el suelo con el cuerpo. Inhala durante esta parte del movimiento.
Tras una pausa de un segundo en la posición estirada, comienza a tirar de ti mismo hacia atrás a la posición inicial mientras exhalas. Consejo: ve despacio y mantén los abdominales contraídos en todo momento.' WHERE name_en = 'Barbell Ab Rollout - On Knees';
UPDATE public.exercises SET instructions_es = 'Acuéstate boca arriba en un banco plano. Utilizando un agarre de anchura media (un agarre que cree un ángulo de 90 grados a mitad del movimiento entre los antebrazos y la parte superior de los brazos), levanta la barra del soporte y sosténla directamente sobre ti con los brazos bloqueados. Esta será tu posición inicial.
Desde la posición inicial, inhala y comienza a bajar lentamente hasta que la barra toque la parte media de tu pecho.
Tras una breve pausa, empuja la barra de vuelta a la posición inicial mientras exhalas. Enfócate en empujar la barra usando los músculos pectorales. Bloquea los brazos y aprieta el pecho en la posición contraída en la parte superior del movimiento, mantén durante un segundo y luego comienza a bajar lentamente de nuevo. Consejo: idealmente, bajar el peso debería llevar aproximadamente el doble de tiempo que subirlo.
Repite el movimiento durante la cantidad de repeticiones prescrita.
Cuando hayas terminado, vuelve a colocar la barra en el soporte.' WHERE name_en = 'Barbell Bench Press - Medium Grip';
UPDATE public.exercises SET instructions_es = 'Ponte de pie con el torso erguido mientras sostienes una barra con un agarre del ancho de los hombros. Las palmas de las manos deben mirar hacia adelante y los codos deben estar cerca del torso. Esta será tu posición inicial.
Manteniendo inmóvil la parte superior de los brazos, flexiona los pesos hacia adelante mientras contraes los bíceps a medida que exhalas. Consejo: solo deben moverse los antebrazos.
Continúa el movimiento hasta que tus bíceps estén completamente contraídos y la barra esté al nivel de los hombros. Mantén la posición contraída durante un segundo y aprieta los bíceps con fuerza.
Comienza a bajar lentamente la barra de vuelta a la posición inicial mientras inhalas.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Barbell Curl';
UPDATE public.exercises SET instructions_es = 'Acuéstate sobre un banco inclinado, con los brazos sosteniendo una barra y colgando hacia abajo en línea vertical. Esta será tu posición inicial.
Manteniendo inmóvil la parte superior de los brazos, flexiona el peso hacia arriba lo más alto posible mientras aprietas los bíceps. Exhala mientras realizas esta parte del movimiento. Consejo: solo deben moverse los antebrazos. No balancees los brazos.
Tras una contracción de un segundo, regresa lentamente a la posición inicial mientras inhalas. Consejo: asegúrate de bajar por completo.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Barbell Curls Lying Against An Incline';
UPDATE public.exercises SET instructions_es = 'Ponte de pie frente a una barra cargada.
Manteniendo la espalda lo más recta posible, dobla las rodillas, inclínate hacia adelante y agarra la barra utilizando un agarre prono de anchura media (ancho de hombros). Esta será la posición inicial del ejercicio. Consejo: si resulta difícil sujetar la barra con este agarre, alterna el agarre o utiliza correas para muñecas.
Mientras sostienes la barra, inicia el levantamiento empujando con las piernas y simultáneamente llevando el torso a la posición erguida a medida que exhalas. En la posición erguida, saca el pecho y contrae la espalda llevando las escápulas hacia atrás. Piensa en cómo se ven los soldados cuando están en posición de firme.
Regresa a la posición inicial doblando las rodillas y al mismo tiempo inclinando el torso hacia adelante por la cintura, manteniendo la espalda recta. Cuando los discos de la barra toquen el suelo, estarás de vuelta en la posición inicial y listo para realizar otra repetición.
Realiza la cantidad de repeticiones prescrita en el programa.' WHERE name_en = 'Barbell Deadlift';
UPDATE public.exercises SET instructions_es = 'Por razones de seguridad, es mejor realizar este ejercicio dentro de un rack de sentadillas. Para comenzar, primero coloca la barra en el soporte justo por encima del nivel de los hombros. Una vez elegida la altura correcta y cargada la barra, ponte debajo de ella y apoya la parte posterior de tus hombros (ligeramente por debajo del cuello) a lo largo de la barra.
Sujeta la barra usando ambos brazos a cada lado y levántala del soporte empujando primero con las piernas y al mismo tiempo enderezando el torso.
Da un paso hacia atrás saliendo del rack y posiciona las piernas con una apertura media a la anchura de los hombros, con las puntas de los pies ligeramente apuntando hacia afuera. Mantén la cabeza erguida en todo momento y conserva la espalda recta. Esta será tu posición inicial.
Comienza a bajar lentamente la barra doblando las rodillas y llevando las caderas hacia atrás mientras mantienes una postura erguida con la cabeza levantada. Continúa bajando hasta que los isquiotibiales toquen las pantorrillas. Inhala mientras realizas esta parte del movimiento.
Comienza a elevar la barra mientras exhalas empujando el suelo con el talón o la parte media del pie a medida que enderezas las piernas y extiendes las caderas para volver a la posición inicial.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Barbell Full Squat';
UPDATE public.exercises SET instructions_es = 'Comienza sentado en el suelo con una barra cargada sobre tus piernas. Utilizar una barra gruesa o colocar una almohadilla en la barra puede reducir en gran medida la incomodidad causada por este ejercicio. Rueda la barra para que quede directamente sobre tus caderas y acuéstate boca arriba en el suelo.
Inicia el movimiento empujando con los talones, extendiendo las caderas verticalmente contra la barra. Tu peso debe estar apoyado en la parte superior de la espalda y en los talones.
Extiéndete lo más posible, luego invierte el movimiento para regresar a la posición inicial.' WHERE name_en = 'Barbell Glute Bridge';
UPDATE public.exercises SET instructions_es = 'Utilizando un agarre de anchura media (un agarre que cree un ángulo de 90 grados a mitad del movimiento entre los antebrazos y la parte superior de los brazos), levanta la barra del soporte y sosténla directamente sobre tu cuello con los brazos bloqueados. Esta será tu posición inicial.
Mientras inhalas, baja la barra lentamente hasta que quede a aproximadamente 1 pulgada de tu cuello.
Tras una pausa de un segundo, lleva la barra de vuelta a la posición inicial mientras exhalas y empujas la barra usando los músculos pectorales. Bloquea los brazos y aprieta el pecho en la posición contraída, mantén durante un segundo y luego comienza a bajar lentamente de nuevo. Debería tomar al menos el doble de tiempo bajar que subir.
Repite el movimiento durante la cantidad prescrita de repeticiones.
Cuando hayas terminado, vuelve a colocar la barra en el soporte.' WHERE name_en = 'Barbell Guillotine Bench Press';
UPDATE public.exercises SET instructions_es = 'Ponte de pie en el suelo con un pie apoyado en un banco o caja, con el talón cerca del borde.
Impúlsate con el pie que está sobre el banco, extendiendo la cadera y la rodilla.
Aterriza con el pie opuesto sobre la caja, regresando el otro pie a la posición inicial.
Continúa alternando de un pie a otro para completar la serie.' WHERE name_en = 'Bench Sprint';
UPDATE public.exercises SET instructions_es = 'Acuéstate en un banco plano sosteniendo una barra con un agarre del ancho de los hombros.
Mantén la barra recta sobre tu pecho con los brazos ligeramente doblados. Esta será tu posición inicial.
Mientras mantienes los brazos doblados, baja el peso lentamente en forma de arco detrás de tu cabeza mientras inhalas hasta sentir un estiramiento en el pecho.
En ese punto, vuelve a llevar la barra a la posición inicial siguiendo el mismo arco por el que bajaste el peso y exhala mientras realizas este movimiento.
Mantén el peso en la posición inicial durante un segundo y repite el movimiento la cantidad de repeticiones indicadas.' WHERE name_en = 'Bent-Arm Barbell Pullover';
UPDATE public.exercises SET instructions_es = 'Coloca una mancuerna de pie sobre un banco plano.
Asegurándote de que la mancuerna permanezca colocada de forma segura en la parte superior del banco, acuéstate de forma perpendicular al banco (con el torso cruzado sobre él, formando una cruz) apoyando únicamente los hombros sobre la superficie. Las caderas deben quedar por debajo del banco y las piernas dobladas con los pies firmes en el suelo. La cabeza también quedará fuera del banco.
Toma la mancuerna con ambas manos y mantenla recta sobre tu pecho con los brazos ligeramente doblados. Ambas palmas deben hacer presión contra la parte inferior de uno de los extremos de la mancuerna. Esta será tu posición inicial. Precaución: Asegúrate siempre de que la mancuerna utilizada para este ejercicio sea segura. Usar una mancuerna con discos sueltos puede hacer que se desmonte y caiga sobre tu cara.
Mientras mantienes los brazos fijos en posición doblada, baja el peso lentamente en forma de arco detrás de tu cabeza mientras inhalas hasta sentir un estiramiento en el pecho.
En ese punto, vuelve a llevar la mancuerna a la posición inicial siguiendo el mismo arco por el que bajaste el peso y exhala mientras realizas este movimiento.
Mantén el peso en la posición inicial durante un segundo y repite el movimiento la cantidad de repeticiones indicadas.' WHERE name_en = 'Bent-Arm Dumbbell Pullover';
UPDATE public.exercises SET instructions_es = 'Acuéstate boca arriba en el suelo con los brazos a los lados del cuerpo.
Ahora dobla las rodillas en un ángulo de aproximadamente 75 grados y levanta los pies del suelo unos 5 cm.
Utilizando los abdominales inferiores, lleva las rodillas hacia ti manteniendo el ángulo de 75 grados en las piernas. Continúa este movimiento hasta levantar las caderas del suelo rodando la pelvis hacia atrás. Exhala mientras realizas esta parte del movimiento. Consejo: Al final del movimiento, tus rodillas estarán sobre tu pecho.
Contrae los abdominales en la parte superior del movimiento durante un segundo y luego regresa lentamente a la posición inicial mientras inhalas. Consejo: Mantén un movimiento controlado en todo momento.
Repite la cantidad de repeticiones recomendada.' WHERE name_en = 'Bent-Knee Hip Raise';
UPDATE public.exercises SET instructions_es = 'Sosteniendo una barra con agarre prono (las palmas mirando hacia abajo), dobla ligeramente las rodillas y lleva el torso hacia adelante, doblándote por la cintura, mientras mantienes la espalda recta hasta que esté casi paralela al suelo. Consejo: Asegúrate de mantener la cabeza erguida. La barra debe colgar directamente frente a ti con los brazos colgando de forma perpendicular al suelo y a tu torso. Esta es tu posición inicial.
Ahora, manteniendo el torso inmóvil, exhala y levanta la barra hacia ti. Mantén los codos cerca del cuerpo y utiliza solo los antebrazos para sostener el peso. En la posición de máxima contracción arriba, aprieta los músculos de la espalda y haz una breve pausa.
Luego inhala y baja lentamente la barra de regreso a la posición inicial.
Repite la cantidad recomendada de repeticiones.' WHERE name_en = 'Bent Over Barbell Row';
UPDATE public.exercises SET instructions_es = 'Ponte de pie con el cuerpo recto sosteniendo una mancuerna en cada mano y con un banco inclinado frente a ti.
Mientras mantienes la espalda recta y conservas el arco natural de la espalda, inclínate hacia adelante hasta que tu frente toque el banco frente a ti. Deja que los brazos cuelguen frente a ti de forma perpendicular al suelo. Las palmas de las manos deben quedar mirándose entre sí y el torso debe estar paralelo al suelo. Esta será tu posición inicial.
Mantenimiento el torso inclinado e inmóvil, y los brazos rectos con una ligera flexión en los codos, levanta las mancuernas directamente hacia los lados hasta que ambos brazos queden paralelos al suelo. Exhala mientras levantas los pesos. Precaución: evita balancear el torso o llevar los brazos hacia atrás en lugar de hacia los lados.
Tras un segundo de contracción en la parte superior, baja lentamente las mancuernas de regreso a la posición inicial.
Repite la cantidad recomendada de repeticiones.' WHERE name_en = 'Bent Over Dumbbell Rear Delt Raise With Head On Bench';
UPDATE public.exercises SET instructions_es = 'Selecciona un peso y sujeta el agarre de la polea baja con la mano derecha.
Dóblate por la cintura hasta que el torso esté casi paralelo al suelo. Las piernas deben estar ligeramente dobladas y la mano izquierda apoyada en la parte inferior del muslo izquierdo. El brazo derecho debe colgar desde el hombro frente a ti, con una ligera flexión en el codo. Esta será tu posición inicial.
Levanta el brazo derecho, con el codo ligeramente doblado, hacia el lado hasta que el brazo esté paralelo al suelo y alineado con tu oreja derecha. Exhala mientras realizas este paso.
Baja lentamente el peso de regreso a la posición inicial mientras inhalas.
Repite la cantidad recomendada de repeticiones y repite el movimiento con el otro brazo.' WHERE name_en = 'Bent Over Low-Pulley Side Lateral';
UPDATE public.exercises SET instructions_es = 'Coloca peso en uno de los extremos de una barra olímpica. Asegúrate de colocar el otro extremo de la barra en la esquina de dos paredes o de poner un objeto pesado en el suelo para que la barra no se deslice hacia atrás.
Inclínate hacia adelante hasta que el torso esté lo más paralelo posible al suelo y mantén las rodillas ligeramente dobladas.
Ahora agarra la barra con un brazo justo detrás de los discos en el lado donde pusiste el peso y apoya la otra mano en la rodilla. Esta será tu posición inicial.
Tira de la barra directamente hacia arriba con el codo pegado al cuerpo (para maximizar la estimulación de la espalda) hasta que los discos toquen la parte inferior del pecho. Aprieta los músculos de la espalda mientras levantas el peso y mantén la posición durante un segundo en la parte superior del movimiento. Exhala al levantar el peso. Consejo: No permitas ningún balanceo del torso. Solo debe moverse el brazo.
Baja lentamente la barra a la posición inicial sintiendo un buen estiramiento en los dorsales. Consejo: No dejes que los discos toquen el suelo. Para garantizar el mejor rango de movimiento, recomiendo usar discos pequeños (de 25 lb / 11 kg) en lugar de discos más grandes (como los de 35-45 lb / 15-20 kg).
Repite la cantidad recomendada de repeticiones y cambia de brazo.' WHERE name_en = 'Bent Over One-Arm Long Bar Row';
UPDATE public.exercises SET instructions_es = 'Coloca peso en uno de los extremos de una barra olímpica. Asegúrate de colocar el otro extremo de la barra en la esquina de dos paredes o de poner un objeto pesado en el suelo para que la barra no se deslice hacia atrás.
Inclínate hacia adelante hasta que el torso esté lo más paralelo posible al suelo y mantén las rodillas ligeramente dobladas.
Ahora agarra la barra con ambos brazos justo detrás de los discos en el lado donde pusiste el peso y apoya la otra mano en la rodilla. Esta será tu posición inicial.
Tira de la barra directamente hacia arriba con los codos pegados al cuerpo (para maximizar la estimulación de la espalda) hasta que los discos toquen la parte inferior del pecho. Aprieta los músculos de la espalda mientras levantas el peso y mantén la posición durante un segundo en la parte superior del movimiento. Exhala al levantar el peso. Consejo: Utiliza un agarre de estribo o un agarre doble de polea enganchándolo debajo del extremo de la barra.
Baja lentamente la barra a la posición inicial sintiendo un buen estiramiento en los dorsales. Consejo: No dejes que los discos toquen el suelo. Para garantizar el mejor rango de movimiento, recomiendo usar discos pequeños (de 25 lb / 11 kg) en lugar de discos más grandes (como los de 35-45 lb / 15-20 kg).
Repite la cantidad recomendada de repeticiones.' WHERE name_en = 'Bent Over Two-Arm Long Bar Row';
UPDATE public.exercises SET instructions_es = 'Con una mancuerna en cada mano (las palmas mirando hacia tu torso), dobla ligeramente las rodillas y lleva el torso hacia adelante doblándote por la cintura; al doblarte, asegúrate de mantener la espalda recta hasta que esté casi paralela al suelo. Consejo: Asegúrate de mantener la cabeza erguida. Las mancuernas deben colgar directamente frente a ti con los brazos colgando de forma perpendicular al suelo y a tu torso. Esta es tu posición inicial.
Mientras mantienes el torso inmóvil, levanta las mancuernas hacia tu costado (mientras exhalas), manteniendo los codos pegados al cuerpo (no ejerzas fuerza con el antebrazo más allá de sostener las mancuernas). En la posición de máxima contracción arriba, aprieta los músculos de la espalda y sostén durante un segundo.
Baja lentamente el peso de nuevo a la posición inicial mientras inhalas.
Repite la cantidad recomendada de repeticiones.' WHERE name_en = 'Bent Over Two-Dumbbell Row';
UPDATE public.exercises SET instructions_es = 'Con una mancuerna en cada mano (las palmas mirándose entre sí), dobla ligeramente las rodillas y lleva el torso hacia adelante, doblándote por la cintura, mientras mantienes la espalda recta hasta que esté casi paralela al suelo. Consejo: Asegúrate de mantener la cabeza erguida. Las mancuernas deben colgar directamente frente a ti con los brazos colgando de forma perpendicular al suelo y a tu torso. Esta es tu posición inicial.
Mientras mantienes el torso inmóvil, levanta las mancuernas hacia los lados mientras exhalas, juntando las escápulas. En la posición de máxima contracción arriba, aprieta los músculos de la espalda y sostén durante un segundo.
Baja lentamente el peso de nuevo a la posición inicial mientras inhalas.
Repite la cantidad recomendada de repeticiones.' WHERE name_en = 'Bent Over Two-Dumbbell Row With Palms In';
UPDATE public.exercises SET instructions_es = 'Lleva una pesa rusa (kettlebell) al hombro mediante una cargada (clean). Carga la pesa rusa hacia tus hombros extendiendo las piernas y las caderas mientras la elevas hacia el hombro. La muñeca debe rotar a medida que realizas el movimiento. Esta será tu posición inicial.
Comienza inclinándote hacia el lado opuesto a la pesa rusa, continuando hasta tocar el suelo con la mano libre, manteniendo la mirada fija en la pesa rusa. Al hacerlo, empuja el peso verticalmente extendiendo el codo, manteniendo el brazo perpendicular al suelo.
Vuelve a la posición erguida con la pesa rusa por encima de la cabeza. Regresa la pesa rusa al hombro y repite el número deseado de repeticiones.' WHERE name_en = 'Bent Press';
UPDATE public.exercises SET instructions_es = 'Para comenzar, siéntate en la bicicleta y ajusta el sillín a tu altura.' WHERE name_en = 'Bicycling';
UPDATE public.exercises SET instructions_es = 'Para comenzar, siéntate en la bicicleta y ajusta el sillín a tu altura.
Selecciona la opción deseada del menú. Es posible que tengas que empezar a pedalear para encenderla. Puedes usar la configuración manual o seleccionar un programa. Por lo general, puedes ingresar tu edad y peso para calcular las calorías quemadas durante el ejercicio. El nivel de resistencia se puede cambiar durante todo el entrenamiento. Los agarres se pueden usar para monitorear tu frecuencia cardíaca y ayudarte a mantener una intensidad adecuada.' WHERE name_en = 'Bicycling, Stationary';
UPDATE public.exercises SET instructions_es = 'Comienza acostándote en el banco, posicionando la cabeza más allá de la barra si es posible. Se pueden atornillar entre sí de una a cinco tablas (de 2x6 pulgadas) y sujetarlas mediante un compañero de entrenamiento, bandas o simplemente metiéndolas debajo de la camiseta.
Recoge los pies debajo de ti y arquea la espalda. Usando la barra como apoyo para sostener tu peso, levanta los hombros del banco y retráelos, juntando las escápulas. Usa los pies para empujar los trapecios contra el banco. Mantén esta posición corporal firme durante todo el movimiento.
Puedes tomar un agarre estándar de banco o del ancho de los hombros para concentrarte en los tríceps. Saca la barra del soporte sin protraer los hombros. La barra, la muñeca y el codo deben mantenerse alineados en todo momento. Concéntrate en apretar la barra e intentar «separarla» con las manos.
Baja la barra hasta las tablas y luego empújala hacia arriba con la mayor fuerza posible. Los codos deben permanecer pegados hacia adentro hasta el bloqueo.' WHERE name_en = 'Board Press';
UPDATE public.exercises SET instructions_es = 'Adopta una posición de plancha en el suelo. Debes sostener tu peso corporal sobre la punta de los pies y los antebrazos, manteniendo el torso recto. Los antebrazos deben estar separados a la anchura de los hombros. Esta será tu posición inicial.
Presionando las palmas firmemente contra el suelo, extiende los codos para elevar el cuerpo del suelo. Mantén el torso rígido mientras realizas el movimiento.
Baja lentamente los antebrazos de regreso al suelo flexionando los codos.
Repite.' WHERE name_en = 'Body-Up';
UPDATE public.exercises SET instructions_es = 'Coloca una barra en un soporte a la altura del pecho.
De pie, toma la barra con un agarre del ancho de los hombros y da uno o dos pasos hacia atrás, con los pies juntos y los brazos extendidos de modo que quedes inclinado sobre la barra. Esta será tu posición inicial.
Comienza flexionando los codos, bajando tu cuerpo hacia la barra.
Haz una pausa y luego invierte el movimiento extendiendo los codos.
Aumenta la dificultad respecto al peso corporal añadiendo cadenas sobre los hombros.' WHERE name_en = 'Body Tricep Press';
UPDATE public.exercises SET instructions_es = 'Coloca dos barras Z con el mismo peso en el suelo, una al lado de la otra. Asegúrate de que puedan rodar.
Adopta una posición de flexión de brazos sobre las barras, sosteniendo tu peso sobre la punta de los pies y las manos, con los brazos extendidos y el cuerpo recto.
Coloca las manos sobre las barras. Esta será tu posición inicial.
Con un movimiento lento y controlado, aleja las manos de la línea media del cuerpo, haciendo rodar las barras para separarlas. Inhala durante esta parte del movimiento.
Después de separar las barras lo máximo posible, regresa a la posición inicial juntándolas de nuevo. Exhala mientras realizas este movimiento.' WHERE name_en = 'Bodyweight Flyes';
UPDATE public.exercises SET instructions_es = 'Comienza tomando un agarre de medio a ancho en una barra o aparato de dominadas con las palmas mirando hacia afuera. Desde una posición colgada, lleva las rodillas hacia el pecho, inclinándote hacia atrás y pasando las piernas por encima de tu lado del aparato de dominadas. Esta será tu posición inicial.
Comenzando con los brazos rectos, flexiona los codos y retrae las escápulas para elevar el cuerpo hasta que las piernas entren en contacto con el aparato de dominadas.
Tras una breve pausa, regresa a la posición inicial.' WHERE name_en = 'Bodyweight Mid Row';
UPDATE public.exercises SET instructions_es = 'Ponte de pie con los pies separados al ancho de los hombros. Puedes colocar las manos detrás de la cabeza. Esta será tu posición inicial.
Comienza el movimiento flexionando las rodillas y las caderas, llevando la cadera hacia atrás como al sentarse.
Continúa bajando hasta la máxima profundidad si eres capaz, e invierte rápidamente el movimiento hasta regresar a la posición inicial. Al hacer la sentadilla, mantén la cabeza y el pecho erguidos y empuja las rodillas hacia afuera.' WHERE name_en = 'Bodyweight Squat';
UPDATE public.exercises SET instructions_es = 'Comienza de pie con los pies separados al ancho de los hombros y las manos en la cadera.
Da un paso hacia adelante con una pierna, flexionando las rodillas para bajar las caderas. Desciende hasta que la rodilla trasera casi toque el suelo. Tu postura debe mantenerse erguida y la rodilla delantera debe permanecer alineada sobre el pie delantero.
Empuja con el talón del pie delantero y extiende ambas rodillas para volver a levantarte.
Da un paso hacia adelante con el pie trasero, repitiendo la zancada con la pierna opuesta.' WHERE name_en = 'Bodyweight Walking Lunge';
UPDATE public.exercises SET instructions_es = 'Conecta un agarre estándar a cada brazo de una máquina de poleas y colócalos en la posición más baja.
Toma un Bosu y colócalo frente al centro de la máquina de poleas.
Acuéstate sobre el Bosu con la zona lumbar arqueada alrededor de él. Los glúteos deben quedar cerca del suelo sin tocarlo.
Con ambas manos, estírate hacia atrás y sujeta el agarre de cada polea.
Con los pies colocados en una postura ancha, extiende los brazos hacia adelante, entre las rodillas. Las manos deben quedar a la altura de las rodillas.
Mantén los brazos rectos y alineados con el ángulo ascendente de la polea. Eleva el torso en un movimiento de encogimiento (crunch) sin bajar ni doblar los brazos.
Mantén la posición rígida de los brazos. Desciende lentamente a la posición inicial con la espalda arqueada sobre el Bosu y los abdominales estirados.
Repite la misma serie de movimientos hasta llegar al fallo muscular.
Una vez que alcances el fallo, mantén los abdominales contraídos y eleva el torso a una posición de plancha de modo que la espalda quede despegada del Bosu.
Baja los brazos a los lados manteniéndolos rectos. ¡Comienza a hacer flexiones laterales de tronco alternas intentando alcanzar los talones! Este movimiento final se centrará en los oblicuos.' WHERE name_en = 'Bosu Ball Cable Crunch With Side Bends';
UPDATE public.exercises SET instructions_es = 'Inicia el ejercicio de pie, con el cuerpo erguido y una pesa rusa en una mano.
Balancea la pesa rusa hacia atrás con fuerza y luego invierte el movimiento con fuerza. Aprieta el asa de la pesa rusa lo más fuerte posible y elévala hasta el hombro.' WHERE name_en = 'Bottoms-Up Clean From The Hang Position';
UPDATE public.exercises SET instructions_es = 'Comienza acostándote boca arriba en el suelo. Las piernas deben estar rectas y los brazos a los lados del cuerpo. Esta será tu posición inicial.
Para realizar el movimiento, lleva las rodillas hacia el pecho flexionando las caderas y las rodillas. A continuación, extiende las piernas directamente hacia arriba de modo que queden perpendiculares al suelo. Rota y eleva la pelvis para levantar los glúteos del suelo.
Tras una breve pausa, regresa a la posición inicial.' WHERE name_en = 'Bottoms Up';
UPDATE public.exercises SET instructions_es = 'Adopta una postura relajada frente a la caja o plataforma, a una distancia aproximada de un brazo. Los brazos deben estar abajo a los lados y las piernas ligeramente dobladas.
Usando los brazos para ayudarte en el impulso inicial, salta hacia arriba y hacia adelante, aterrizando con ambos pies al mismo tiempo sobre la caja o plataforma.
Inmediatamente déjate caer o salta de regreso al lugar de inicio original; luego repite la secuencia.' WHERE name_en = 'Box Jump (Multiple Response)';
UPDATE public.exercises SET instructions_es = 'Necesitarás varias cajas alineadas a unos 8 pies de distancia entre sí.
Comienza de frente a la primera caja con una pierna ligeramente detrás de la otra.
Impúlsate con la pierna trasera, intentando ganar la mayor altura posible con las caderas.
Inmediatamente al aterrizar en la caja, impulsa la otra pierna hacia adelante y hacia arriba para ganar altura y distancia, saltando de la caja. Aterriza entre las dos primeras cajas con la misma pierna que aterrizó en la primera caja.
Luego, avanza a la siguiente caja y repite.' WHERE name_en = 'Box Skip';
UPDATE public.exercises SET instructions_es = 'La sentadilla sobre caja te permite hacer sentadillas a la profundidad deseada y desarrollar fuerza explosiva en el movimiento de sentadilla. Comienza en un rack de potencia con una caja a la altura adecuada detrás de ti. Normalmente, se busca una altura de caja que te lleve a una sentadilla paralela, pero puedes entrenar más alto o más bajo si lo deseas.
Comienza colocándote debajo de la barra y posicionándola a lo largo de la parte posterior de los hombros. Junta las escápulas y gira los codos hacia adelante, intentando doblar la barra sobre tus hombros. Saca la barra del rack, creando un arco firme en la zona lumbar, y da un paso atrás para posicionarte. Coloca los pies más separados para dar más énfasis a la espalda, los glúteos, los aductores y los isquiotibiales, o más juntos para un mayor desarrollo de los cuadriceps. Mantén la cabeza mirando hacia adelante.
Con la espalda, los hombros y el torso tensos, empuja las rodillas y los glúteos hacia afuera al comenzar el descenso. Siéntate hacia atrás con las caderas hasta quedar sentado en la caja. Lo ideal es que las espinillas estén perpendiculares al suelo. Haz una pausa cuando llegues a la caja y relaja los flexores de la cadera. Nunca rebotes sobre la caja.
Manteniendo el peso en los talones y empujando los pies y las rodillas hacia afuera, impúlsate hacia arriba desde la caja guiando el movimiento con la cabeza. Continúa hacia arriba, manteniendo la firmeza de la cabeza a los pies.' WHERE name_en = 'Box Squat';
UPDATE public.exercises SET instructions_es = 'Comienza en un rack de potencia con una caja a la altura adecuada detrás de ti. Coloca las bandas en las mangas de la barra, sujetas a soportes para bandas, al rack o a mancuernas para que haya la tensión adecuada. Si usas mancuernas, asegúralas para que no se muevan. Además, asegúrate de que las mancuernas que utilices sean lo suficientemente pesadas para las bandas que estás usando. Se pueden usar discos adicionales para sujetar las mancuernas. Si se necesita más tensión, puedes ensanchar la base en el suelo o estrangular las bandas. Normalmente, se busca una altura de caja que te lleve a una sentadilla paralela, pero puedes entrenar más alto o más bajo si lo deseas.
Comienza colocándote debajo de la barra y posicionándola a lo largo de la parte posterior de los hombros. Junta las escápulas y gira los codos hacia adelante, intentando doblar la barra sobre tus hombros. Saca la barra del rack, creando un arco firme en la zona lumbar, y da un paso atrás para posicionarte. Coloca los pies más separados para dar más énfasis a la espalda, los glúteos, los aductores y los isquiotibiales, o más juntos para un mayor desarrollo de los cuadriceps. Mantén la cabeza mirando hacia adelante.
Con la espalda, los hombros y el torso tensos, empuja las rodillas y los glúteos hacia afuera al comenzar el descenso. Siéntate hacia atrás con las caderas hasta quedar sentado en la caja. Lo ideal es que las espinillas estén perpendiculares al suelo. Haz una pausa cuando llegues a la caja y relaja los flexores de la cadera. Nunca rebotes sobre la caja.
Manteniendo el peso en los talones y empujando los pies y las rodillas hacia afuera, impúlsate hacia arriba desde la caja guiando el movimiento con la cabeza. Continúa hacia arriba, manteniendo la firmeza de la cabeza a los pies. Ten cuidado al volver a colocar la barra en el rack.' WHERE name_en = 'Box Squat with Bands';
UPDATE public.exercises SET instructions_es = 'Comienza en un rack de potencia con una caja a la altura adecuada detrás de ti. Normalmente, se busca una altura de caja que te lleve a una sentadilla paralela, pero puedes entrenar más alto o más bajo si lo deseas.
Para colocar las cadenas, comienza pasando la cadena guía sobre las mangas de la barra. La cadena pesada debe engancharse con un mosquetón. Ajusta la longitud de la cadena guía para que queden algunos eslabones en el suelo en la parte superior del movimiento.
Comienza colocándote debajo de la barra y posicionándola a lo largo de la parte posterior de los hombros. Junta las escápulas y gira los codos hacia adelante, intentando doblar la barra sobre tus hombros. Saca la barra del rack, creando un arco firme en la zona lumbar, y da un paso atrás para posicionarte. Coloca los pies más separados para dar más énfasis a la espalda, los glúteos, los aductores y los isquiotibiales, o más juntos para un mayor desarrollo de los cuadriceps. Mantén la cabeza mirando hacia adelante.
Con la espalda, los hombros y el torso tensos, empuja las rodillas y los glúteos hacia afuera al comenzar el descenso. Siéntate hacia atrás con las caderas hasta quedar sentado en la caja. Lo ideal es que las espinillas estén perpendiculares al suelo. Haz una pausa cuando llegues a la caja y relaja los flexores de la cadera. Nunca rebotes sobre la caja.
Manteniendo el peso en los talones y empujando los pies y las rodillas hacia afuera, impúlsate hacia arriba desde la caja guiando el movimiento con la cabeza. Continúa hacia arriba, manteniendo la firmeza de la cabeza a los pies.' WHERE name_en = 'Box Squat with Chains';
UPDATE public.exercises SET instructions_es = 'Acuéstate de lado, con la parte superior del brazo apoyada contra el rodillo de espuma. La parte superior del brazo debe estar más o menos alineada con tu cuerpo, con la parte exterior del bíceps presionada contra el rodillo.
Levanta las caderas del suelo, apoyando tu peso en el brazo y en los pies. Mantén la posición durante 10-30 segundos y luego cambia de lado.' WHERE name_en = 'Brachialis-SMR';
UPDATE public.exercises SET instructions_es = 'Siéntate en un banco de press militar con una barra a la altura de los hombros y un agarre en pronación (palmas mirando hacia adelante). Consejo: Tu agarre debe ser más ancho que el ancho de los hombros y debe formar un ángulo de 90 grados entre el antebrazo y la parte superior del brazo a medida que la barra baja. Esta será tu posición inicial.
Una vez que tomes la barra con el agarre correcto, levántala por encima de tu cabeza extendiendo por completo los brazos.
Ahora baja la barra lentamente hacia la parte posterior de la cabeza mientras inhalas.
Vuelve a levantar la barra a la posición inicial mientras exhalas.
Baja la barra lentamente a la posición inicial mientras inhalas. Esto cuenta como una repetición.
Alterna de esta manera hasta completar la cantidad recomendada de repeticiones.' WHERE name_en = 'Bradford/Rocky Presses';
UPDATE public.exercises SET instructions_es = 'Comienza en posición de flexión de brazos pero con los codos en el suelo y apoyándote en los antebrazos. Tus brazos deben estar doblados en un ángulo de 90 grados.
Arquea ligeramente la espalda hacia afuera en lugar de mantenerla completamente recta.
Eleva los glúteos hacia el techo, contrayendo fuertemente los abdominales para reducir la distancia entre las costillas y las caderas. El resultado final será una posición de puente alto. Exhala mientras realizas esta parte del movimiento.
Vuelve a bajar lentamente a la posición inicial mientras inhalas. Consejo: No dejes que la espalda se hunda hacia abajo.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Butt-Ups';
UPDATE public.exercises SET instructions_es = 'Acuéstate boca arriba en el suelo con las manos a los lados y las rodillas dobladas. Los pies deben estar colocados a la anchura de los hombros. Esta será tu posición inicial.
Empujando principalmente con los talones, levanta las caderas del suelo manteniendo la espalda recta. Exhala mientras realizas esta parte del movimiento y mantén la posición en la parte superior durante un segundo.
Vuelve lentamente a la posición inicial mientras inhalas.' WHERE name_en = 'Butt Lift (Bridge)';
UPDATE public.exercises SET instructions_es = 'Siéntate en la máquina con la espalda plana contra el respaldo.
Toma las asas. Consejo: La parte superior de tus brazos debe estar en posición paralela al suelo; ajusta la máquina según sea necesario. Esta será tu posición inicial.
Junta las asas lentamente mientras contraes el pecho en el centro. Exhala durante esta parte del movimiento y mantén la contracción durante un segundo.
Vuelve a la posición inicial lentamente mientras inhalas hasta que los músculos del pecho estén completamente estirados.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Butterfly';
UPDATE public.exercises SET instructions_es = 'Ajusta el peso a una cantidad adecuada y siéntate, sujetando las asas. La parte superior de tus brazos debe estar a unos 45 grados con respecto al cuerpo, con la cabeza y el pecho erguidos. Los codos deben estar doblados a unos 90 grados. Esta será tu posición inicial.
Comienza extendiendo los codos, presionando las asas hacia adelante, juntándolas frente a ti. Mantén las escápulas retraídas mientras ejecutas el movimiento.
Tras hacer una pausa en la extensión completa, vuelve a la posición inicial, manteniendo la tensión en los cables.
También puedes ejecutar este movimiento con la espalda despegada del respaldo, en inclinación o declinación, o alternando las manos.' WHERE name_en = 'Cable Chest Press';
UPDATE public.exercises SET instructions_es = 'Para colocarte en la posición inicial, pon las poleas en una posición alta (por encima de tu cabeza), selecciona la resistencia que vas a utilizar y sujeta un agarre en cada mano.
Da un paso hacia adelante cruzando una línea recta imaginaria entre ambas poleas mientras juntas los brazos frente a ti. El torso debe estar ligeramente inclinado hacia adelante desde la cintura. Esta será tu posición inicial.
Con una ligera flexión en los codos para evitar sobrecargar el tendón del bíceps, abre los brazos hacia los lados en un arco amplio hasta que sientas un estiramiento en el pecho. Inhala mientras realizas esta parte del movimiento. Consejo: Ten en cuenta que durante todo el movimiento, los brazos y el torso deben permanecer fijos; el movimiento solo debe ocurrir en la articulación del hombro.
Vuelve a llevar los brazos a la posición inicial mientras exhalas. Asegúrate de realizar el mismo arco de movimiento que usaste para bajar los pesos.
Mantén la posición durante un segundo en la posición inicial y repite el movimiento durante la cantidad prescrita de repeticiones.' WHERE name_en = 'Cable Crossover';
UPDATE public.exercises SET instructions_es = 'Ponte de rodillas debajo de una polea alta que contenga un accesorio de cuerda.
Toma el accesorio de cuerda y bájalo hasta que tus manos queden situadas al lado de tu cara.
Flexiona ligeramente las caderas y permite que el peso hiperextienda la zona lumbar. Esta será tu posición inicial.
Con las caderas fijas, flexiona la cintura mientras contraes los abdominales de modo que los codos se dirijan hacia la mitad de los muslos. Exhala mientras realizas esta parte del movimiento y mantén la contracción durante un segundo.
Vuelve lentamente a la posición inicial mientras inhalas. Consejo: Asegúrate de mantener una tensión constante en los abdominales durante todo el movimiento. Además, no elijas un peso tan pesado que la zona lumbar realice la mayor parte del trabajo.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Cable Crunch';
UPDATE public.exercises SET instructions_es = 'Mueve los cables hacia la parte inferior de las torres y selecciona un peso adecuado. Colócate directamente entre los postes verticales.
Para comenzar, haz una sentadilla flexionando las caderas y las rodillas hasta que puedas alcanzar las asas.
Tras sujetarlas, comienza el ascenso. Empujando a través de los talones, extiende las caderas y las rodillas manteniendo las manos colgando a los lados. Mantén la cabeza y el pecho erguidos durante todo el movimiento.
Una vez alcanzada la posición de pie completa, vuelve a la posición inicial y repite.' WHERE name_en = 'Cable Deadlifts';
UPDATE public.exercises SET instructions_es = 'Engancha una cuerda a una polea baja y colócate de frente a la máquina a unas 12 pulgadas de distancia.
Toma la cuerda con un agarre neutro (las palmas mirándose entre sí) y mantente erguido, conservando el arco natural de la espalda y el torso fijo.
Pega los codos a los costados y mantenlos fijos durante todo el movimiento. Consejo: Solo deben moverse los antebrazos, no la parte superior de los brazos. Esta será tu posición inicial.
Usando los bíceps, tira de los brazos hacia arriba mientras exhalas hasta que los bíceps toquen los antebrazos. Consejo: Recuerda mantener los codos pegados al cuerpo y la parte superior de los brazos inmóvil.
Tras una contracción de 1 segundo en la que aprietes los bíceps, comienza a regresar lentamente el peso a la posición original.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Cable Hammer Curls - Rope Attachment';
UPDATE public.exercises SET instructions_es = 'Colócate de pie frente a una polea baja mirando hacia adelante, con una pierna al lado de la polea y la otra más alejada.
Sujeta la tobillera al cable y también al tobillo de la pierna que está al lado de la polea.
Ahora da un paso hacia afuera y aléjate del bloque de pesas con una postura ancha y sujétate a la barra de la estructura de la polea.
Apóyate sobre el pie que no tiene la tobillera (el pie más lejano) y deja que la pierna con la tobillera sea atraída hacia la polea baja. Esta será tu posición inicial.
Ahora realiza el movimiento llevando la pierna con la tobillera por delante de la pierna lejana, utilizando la cara interna de los muslos para aducir la cadera. Exhala durante esta parte del movimiento.
Vuelve lentamente a la posición inicial mientras inhalas.
Repite durante la cantidad recomendada de repeticiones y luego repite el mismo movimiento con la pierna opuesta.' WHERE name_en = 'Cable Hip Adduction';
UPDATE public.exercises SET instructions_es = 'Acuéstate en un banco inclinado de espaldas a una máquina de polea alta que tenga enganchada una barra recta.
Toma la barra recta por encima de la cabeza con un agarre en pronación (palmas hacia abajo) al ancho de los hombros y extiende los brazos frente a ti. La barra debe estar a unas 2 pulgadas de la parte superior de tus muslos. Esta será tu posición inicial.
Manteniendo la parte superior de los brazos fija, lleva los brazos hacia atrás en semicírculo hasta que la barra quede directamente sobre tu cabeza. Inhala durante esta parte del movimiento.
Vuelve lentamente a la posición inicial utilizando los dorsales y mantén la contracción una vez que llegues a la posición inicial. Exhala durante la ejecución de este movimiento.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Cable Incline Pushdown';
UPDATE public.exercises SET instructions_es = 'Acuéstate en un banco inclinado de espaldas a una máquina de polea alta que tenga enganchada una barra recta.
Toma la barra recta por encima de la cabeza con un agarre estrecho en pronación (palmas hacia abajo, más estrecho que el ancho de los hombros) y mantén los codos pegados a los costados. La parte superior de tus brazos debe formar un ángulo de unos 25 grados respecto al suelo.
Manteniendo la parte superior de los brazos fija, extiende los brazos mientras contraes los tríceps. Exhala durante esta parte del movimiento y mantén la contracción durante un segundo.
Vuelve lentamente a la posición inicial.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Cable Incline Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Siéntate de lado junto a una polea baja (con las piernas estiradas frente a ti o cruzadas) y toma el agarre individual para cable con el brazo más cercano al cable. Consejo: Si puedes ajustar la altura de la polea, puedes usar un banco plano para sentarte.
Coloca el codo contra el costado con el codo doblado a 90° y el brazo apuntando hacia la polea. Esta será tu posición inicial.
Tira del agarre individual hacia tu cuerpo rotando internamente el hombro hasta que el antebrazo quede cruzado sobre tus abdominales. Estarás creando un semicírculo imaginario. Consejo: El antebrazo debe estar perpendicular a tu torso en todo momento.
Vuelve lentamente a la posición inicial.
Repite durante la cantidad recomendada de repeticiones y luego repite el movimiento con el otro brazo.' WHERE name_en = 'Cable Internal Rotation';
UPDATE public.exercises SET instructions_es = 'Comienza moviendo las poleas a la posición alta, selecciona la resistencia que vas a utilizar y toma un agarre en cada mano.
Colócate directamente entre ambas poleas con los brazos extendidos hacia los lados. La cabeza y el pecho deben estar erguidos mientras tus brazos forman una "T". Esta será tu posición inicial.
Manteniendo los codos extendidos, lleva los brazos rectos hacia tus costados.
Vuelve a llevar los brazos a la posición inicial tras una pausa en el punto de máxima contracción.
Continúa el movimiento durante el número prescrito de repeticiones.' WHERE name_en = 'Cable Iron Cross';
UPDATE public.exercises SET instructions_es = 'Conecta un accesorio de cuerda a una torre y mueve el cable a la posición de polea más baja. Colócate de lado al cable con una postura ancha y toma la cuerda con ambas manos.
Gira el cuerpo alejándote de la polea mientras llevas la cuerda sobre tu hombro como si estuvieras haciendo una proyección de judo.
Cambia el peso entre tus pies mientras giras y flexionas el torso hacia adelante, tirando del cable hacia abajo.
Vuelve a la posición inicial y repite hasta el fallo.
Luego, vuelve a posicionarte y repite la misma serie de movimientos en el lado opuesto.' WHERE name_en = 'Cable Judo Flip';
UPDATE public.exercises SET instructions_es = 'Acuéstate en un banco plano y toma el accesorio de barra recta de una polea baja con un agarre estrecho en pronación. Consejo: La forma más fácil de hacerlo es que alguien te entregue la barra mientras te acuestas.
Con los brazos extendidos, coloca la barra sobre el torso. Tus brazos y tu torso deben formar un ángulo de 90 grados. Esta será tu posición inicial.
Baja la barra doblando los codos mientras mantienes inmóvil la parte superior de los brazos y los codos hacia adentro. Baja hasta que la barra toque ligeramente tu frente. Inhala mientras realizas esta parte del movimiento.
Extiende los tríceps mientras vuelves a levantar la barra a su posición inicial. Exhala mientras realizas esta parte del movimiento.
Mantén la posición durante un segundo en la posición contraída y repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Cable Lying Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Con la mano derecha, toma un agarre individual conectado a la polea alta usando un agarre en supinación (palmas hacia arriba). Debes estar de pie directamente frente a la torre de pesas.
Ahora tira del agarre hacia abajo de modo que la parte superior de tu brazo y el codo queden pegados al costado de tu cuerpo. La parte superior del brazo y el antebrazo deben formar un ángulo agudo (menos de 90 grados). Puedes mantener el otro brazo en la cintura y colocar una pierna hacia adelante y la otra hacia atrás para un mejor equilibrio. Esta será tu posición inicial.
A medida que contraes los tríceps, mueve el agarre hacia abajo al costado de tu cuerpo hasta que tu brazo esté recto. Exhala mientras realizas este movimiento. Consejo: Solo deben moverse los antebrazos. La parte superior de tus brazos debe permanecer inmóvil en todo momento.
Aprieta los tríceps y mantén la posición durante un segundo en esta posición contraída.
Vuelve lentamente el agarre a la posición inicial.
Repite durante la cantidad recomendada de repeticiones y luego realiza el mismo movimiento con el otro brazo.' WHERE name_en = 'Cable One Arm Tricep Extension';
UPDATE public.exercises SET instructions_es = 'Coloca un banco predicador a unos 2 pies delante de una máquina de poleas.
Engancha una barra recta a la polea baja.
Siéntate en el banco predicador con los codos y la parte superior de los brazos firmemente apoyados sobre la almohadilla del banco y pide a alguien que te entregue la barra de la polea baja.
Toma la barra y extiende completamente los brazos sobre la almohadilla del banco predicador. Esta será tu posición inicial.
Ahora comienza a tirar del peso hacia tus hombros y aprieta con fuerza los bíceps en la parte superior del movimiento. Exhala mientras realizas este movimiento. Además, mantén la posición durante un segundo en la parte superior.
Ahora baja lentamente el peso a la posición inicial.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Cable Preacher Curl';
UPDATE public.exercises SET instructions_es = 'Ajusta las poleas a la altura adecuada y ajusta el peso. Las poleas deben estar por encima de tu cabeza.
Toma la polea izquierda con la mano derecha y la polea derecha con la mano izquierda, cruzándolas frente a ti. Esta será tu posición inicial.
Inicia el movimiento llevando los brazos hacia atrás y hacia afuera, manteniéndolos rectos mientras ejecutas el movimiento.
Haz una pausa al final del movimiento antes de regresar los agarres a la posición inicial.' WHERE name_en = 'Cable Rear Delt Fly';
UPDATE public.exercises SET instructions_es = 'Conecta un accesorio de correa para tobillo al cable de una polea baja y coloca una colchoneta en el suelo frente a ella.
Siéntate con los pies hacia la polea y engancha el cable a tus tobillos.
Acuéstate, eleva las piernas y dobla las rodillas en un ángulo de 90 grados. Tus piernas y el cable deben estar alineados. Si no lo están, ajusta la polea hacia arriba o hacia abajo hasta que lo estén.
Con las manos detrás de la cabeza, lleva las rodillas hacia el torso y eleva las caderas del suelo.
Haz una pausa por un momento y, de manera lenta y controlada, baja las caderas y vuelve a llevar las piernas al ángulo inicial de 90 grados. Aún debes sentir tensión en los abdominales en la posición de descanso.
Repite el mismo movimiento hasta llegar al fallo.' WHERE name_en = 'Cable Reverse Crunch';
UPDATE public.exercises SET instructions_es = 'Engancha una cuerda a la polea baja de la máquina de poleas.
Agarrando la cuerda con ambas manos, extiende los brazos con las manos directamente por encima de la cabeza usando un agarre neutro (las palmas mirándose entre sí). Los codos deben estar cerca de la cabeza y los brazos deben quedar perpendiculares al suelo con los nudillos apuntando al techo. Esta será tu posición inicial.
Baja lentamente la cuerda por detrás de la cabeza mientras mantienes la parte superior de los brazos inmóvil. Inhala mientras realizas este movimiento y haz una pausa cuando los tríceps estén completamente estirados.
Vuelve a la posición inicial contrayendo los tríceps mientras exhalas.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Cable Rope Overhead Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Siéntate en la máquina de remo con polea baja en la misma posición que adoptarías para hacer remo sentado con cable para espalda.
Engancha una cuerda a la polea y sujétala con un agarre prono. Los brazos deben estar extendidos y paralelos al suelo con los codos apuntando hacia afuera.
Mantén la zona lumbar erguida y desliza las caderas hacia atrás de modo que las rodillas queden ligeramente flexionadas. Esta será tu posición inicial.
Tira del accesorio del cable hacia la parte superior del pecho, justo por debajo del cuello, mientras mantienes los codos elevados y hacia los lados. Continúa este movimiento mientras exhalas hasta que los codos queden ligeramente por detrás de la espalda. Consejo: Mantén la parte superior de los brazos en posición horizontal, perpendicular al torso y paralela al suelo durante todo el movimiento.
Vuelve a la posición inicial donde los brazos están extendidos y los hombros estirados hacia adelante. Inhala mientras realizas esta parte del movimiento.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Cable Rope Rear-Delt Rows';
UPDATE public.exercises SET instructions_es = 'Conecta un agarre individual estándar y coloca el cable en una posición de polea media.
Acuéstate sobre un balón de estabilidad de forma perpendicular al cable y agarra la manija con una mano. Debes estar aproximadamente a la distancia de un brazo de la polea, sintiendo la tensión del peso en el cable.
Toma el agarre con ambas manos y extiende completamente los brazos por encima del pecho. Tus manos deben estar directamente alineadas con la polea. Si no es así, ajusta la polea hacia arriba o hacia abajo hasta que lo estén.
Mantén las caderas elevadas y los abdominales contraídos. Gira el torso alejándote de la polea realizando un cuarto de giro completo. Tu cuerpo debe estar alineado desde la cabeza hasta las rodillas.
Haz una pausa por un momento y, de manera lenta y controlada, vuelve a la posición inicial. Aún debes mantener tensión lateral en el cable en la posición de descanso.
Repite el mismo movimiento hasta el fallo muscular.
Luego, vuelve a posicionarte y repite la misma serie de movimientos en el lado opuesto.' WHERE name_en = 'Cable Russian Twists';
UPDATE public.exercises SET instructions_es = 'Siéntate en un banco plano dando la espalda a una polea alta.
Toma la cuerda del cable con ambas manos (con las palmas enfrentadas) y coloca las manos firmemente sobre ambos hombros. Consejo: Deja que el peso hiperextienda ligeramente la zona lumbar. Esta será tu posición inicial.
Con las caderas inmóviles, flexiona la cintura para que los codos se dirijan hacia las caderas. Exhala mientras realizas este paso.
A medida que inhalas, vuelve a la posición inicial lentamente.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Cable Seated Crunch';
UPDATE public.exercises SET instructions_es = 'Colócate en medio de dos poleas bajas opuestas entre sí y coloca un banco plano justo detrás de ti (de forma perpendicular a ti; el borde estrecho del banco debe ser el que quede detrás de ti). Selecciona el peso que vas a utilizar en cada polea.
Ahora siéntate en el borde del banco plano con los pies colocados delante de las rodillas.
Inclínate hacia adelante manteniendo la espalda recta y apoya el torso sobre los muslos.
Pide a alguien que te entregue los agarres individuales sujetos a las poleas. Agarra la polea izquierda con la mano derecha y la polea derecha con la izquierda tras seleccionar el peso. Los cables deben pasar por debajo de tus rodillas y tus brazos estarán extendidos con las palmas enfrentadas y una ligera flexión en los codos. Esta será la posición inicial.
Manteniendo los brazos en esa postura, eleva la parte superior de los brazos hacia los lados hasta que queden paralelos al suelo y a la altura de los hombros. Exhala durante la ejecución de este movimiento y mantén la contracción durante un segundo.
Baja lentamente los brazos a la posición inicial mientras inhalas.
Repite durante la cantidad de repeticiones recomendada. Consejo: Mantén la parte superior de los brazos perpendicular al torso y la posición de los codos fija (un ángulo de 10 a 30 grados) durante todo el ejercicio.' WHERE name_en = 'Cable Seated Lateral Raise';
UPDATE public.exercises SET instructions_es = 'Coloca los cables en la parte inferior de las torres y selecciona el peso adecuado.
Colócate justo en medio de los soportes verticales. Agarra los cables y mantenlos a la altura de los hombros, con las palmas mirando hacia adelante. Esta será tu posición inicial.
Manteniendo la cabeza y el pecho erguidos, extiende los codos para empujar los agarres directamente por encima de la cabeza.
Tras hacer una pausa en la parte superior, vuelve a la posición inicial y repite.' WHERE name_en = 'Cable Shoulder Press';
UPDATE public.exercises SET instructions_es = 'Agarra una barra conectada a una polea baja con un agarre prono (palmas mirando hacia abajo) a la anchura de los hombros o ligeramente más ancho.
Mantente erguido cerca de la polea con los brazos extendidos frente a ti sujetando la barra. Esta será tu posición inicial.
Eleva la barra levantando los hombros lo más alto posible mientras exhala. Mantén la contracción en la parte superior durante un segundo. Consejo: Los brazos deben permanecer extendidos en todo momento. Evita usar los bíceps para ayudar a levantar la barra. Solo los hombros deben moverse hacia arriba y hacia abajo.
Vuelve a bajar la barra a la posición original.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Cable Shrugs';
UPDATE public.exercises SET instructions_es = 'Comienza colocando un banco plano frente a un cable de polea baja que tenga acoplada una barra recta.
Usa los brazos para agarrar la barra de la polea con un agarre supino (palmas hacia arriba) estrecho o al ancho de los hombros y elévala de modo que tus antebrazos queden apoyados sobre la parte superior de tus muslos. Tus muñecas deben quedar colgando justo más allá de tus rodillas.
Comienza flexionando la muñeca hacia arriba mientras exhalas. Mantén la contracción durante un segundo.
Baja lentamente las muñecas de nuevo a la posición inicial mientras inhalas.
Tus antebrazos deben permanecer inmóviles, ya que la muñeca es el único movimiento necesario para realizar este ejercicio.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Cable Wrist Curl';
UPDATE public.exercises SET instructions_es = 'Colócate en la máquina de gemelos de manera que las almohadillas para los hombros queden sobre tus hombros. Tu torso debe estar recto con los brazos extendidos normalmente a los lados. Esta será tu posición inicial.
Eleva los hombros hacia las orejas mientras exhalas y mantén la contracción durante un segundo completo.
Vuelve lentamente a la posición inicial mientras inhalas.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Calf-Machine Shoulder Shrug';
UPDATE public.exercises SET instructions_es = 'Ajusta el asiento de modo que tus piernas queden solo ligeramente flexionadas en la posición inicial. Los metatarsos de tus pies deben estar firmemente apoyados en la plataforma.
Selecciona el peso adecuado y agarra las manijas. Esta será tu posición inicial.
Estira las piernas extendiendo las rodillas, levantando apenas el peso de la pila. Tu tobillo debe estar completamente flexionado con los dedos de los pies apuntando hacia arriba. Ejecuta el movimiento presionando hacia abajo con los metatarsos de los pies lo más lejos posible.
Tras una breve pausa, invierte el movimiento y repite.' WHERE name_en = 'Calf Press';
UPDATE public.exercises SET instructions_es = 'Usando una máquina de prensa de piernas, siéntate en la máquina y coloca las piernas en la plataforma directamente frente a ti con una apertura media de los pies (a la anchura de los hombros).
Baja las barras de seguridad que sostienen la plataforma con peso y empuja la plataforma del todo hacia arriba hasta que tus piernas estén completamente extendidas frente a ti sin bloquear las rodillas. (Nota: En algunas máquinas de prensa puedes dejar puestas las barras de seguridad para mayor seguridad. Si tu máquina lo permite, este es el método preferido para realizar el ejercicio). Tu torso y tus piernas deben formar un ángulo perfecto de 90 grados. Ahora coloca con cuidado los dedos y los metatarsos de los pies en la parte inferior de la plataforma, dejando los talones fuera. Los dedos de los pies deben apuntar hacia adelante, hacia afuera o hacia adentro según se describa al principio del capítulo. Esta será tu posición inicial.
Empuja la plataforma levantando los talones mientras exhalas, extendiendo los tobillos lo más alto posible y contrayendo los gemelos. Asegúrate de mantener la rodilla inmóvil en todo momento; no debe haber flexión en ningún momento. Mantén la posición contraída durante un segundo antes de comenzar a bajar.
Vuelve lentamente a la posición inicial mientras inhalas, bajando los talones a medida que doblas los tobillos hasta que los gemelos estén estirados.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Calf Press On The Leg Press Machine';
UPDATE public.exercises SET instructions_es = 'Sujétate a un objeto firme para mantener el equilibrio y párate sobre el agarre de una mancuerna, preferiblemente una con discos redondos para que ruede, ya que de esta manera tendrás que esforzarte más para estabilizarte, aumentando así la efectividad del ejercicio.
Ahora rueda el pie ligeramente hacia adelante para lograr un buen estiramiento del gemelo. Esta será tu posición inicial.
Eleva el gemelo mientras ruedas el pie sobre la parte superior del agarre para lograr una extensión completa. Exhala durante la ejecución de este movimiento. Contrae fuertemente el gemelo en la parte superior y mantén la posición durante un segundo. Consejo: A medida que subes, rueda la mancuerna ligeramente hacia atrás.
Ahora inhala mientras ruedas la mancuerna ligeramente hacia adelante a medida que bajas para lograr un mejor estiramiento.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Calf Raise On A Dumbbell';
UPDATE public.exercises SET instructions_es = 'Agarra una banda de resistencia y párate sobre ella con las puntas de los pies, asegurándote de que la longitud de la banda entre el pie y los brazos sea la misma en ambos lados.
Mientras sujetas los agarres de la banda, eleva los brazos al lado de la cabeza como si te prepararas para realizar un press de hombros. Las palmas deben mirar hacia adelante con los codos doblados y hacia los lados. Este movimiento creará tensión en la banda. Esta será tu posición inicial.
Manteniendo las manos cerca de los hombros, ponte de puntillas mientras exhalas y contrae fuertemente los gemelos en la parte superior del movimiento.
Tras una contracción de un segundo, vuelve lentamente a la posición inicial.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Calf Raises - With Bands';
UPDATE public.exercises SET instructions_es = 'Ponte de pie frente a una pared a un par de pies de distancia.
Apóyate contra la pared, descargando tu peso sobre los antebrazos.
Intenta mantener los talones en el suelo. Mantén la posición durante 10-20 segundos. Puedes alejarte o acercarte a la pared, haciéndolo más o menos difícil, respectivamente.' WHERE name_en = 'Calf Stretch Elbows Against Wall';
UPDATE public.exercises SET instructions_es = 'Ponte de pie frente a una pared a varios pies de distancia. Da un paso alternado, colocando un pie hacia adelante.
Inclínate hacia adelante y apoya las manos en la pared, manteniendo el talón, la cadera y la cabeza en línea recta.
Intenta mantener el talón en el suelo. Mantén la posición durante 10-20 segundos y luego cambia de lado.' WHERE name_en = 'Calf Stretch Hands Against Wall';
UPDATE public.exercises SET instructions_es = 'Comienza sentado en el suelo. Coloca un rodillo de espuma (foam roller) debajo de la parte inferior de la pierna. La otra pierna se puede cruzar sobre la opuesta o colocarse en el suelo, sosteniendo parte de tu peso. Esta será tu posición inicial.
Coloca tus manos a los lados o justo detrás de ti y presiona hacia abajo para levantar las caderas del suelo, apoyando gran parte de tu peso contra el músculo de la pantorrilla. Rueda desde debajo de la rodilla hasta por encima del tobillo, haciendo pausas en los puntos de tensión durante 10-30 segundos. Repite para la otra pierna.' WHERE name_en = 'Calves-SMR';
UPDATE public.exercises SET instructions_es = 'Este aparato para eventos suele tener manijas de agarre neutro; sin embargo, algunos tienen una barra recta a la que puedes aproximarte como en un peso muerto normal. El aparato se puede cargar con un vehículo u otros objetos pesados como neumáticos de tractor o barriles.
Centra tu cuerpo entre los agarres si eres fuerte en sentadillas, o retrocede un par de pulgadas si eres fuerte en peso muerto. Tus pies deben estar separados aproximadamente a la anchura de las caderas. Inclínate por la cadera para agarrar las manijas. Con los pies y el agarre en su lugar, toma una inhalación profunda y luego baja las caderas y flexiona las rodillas.
Mira hacia adelante, mantén el pecho erguido y la espalda arqueada, y comienza a empujar con los talones para mover el peso hacia arriba. A medida que sube el peso, junta las escápulas mientras llevas la cadera hacia adelante.
Baja el peso flexionando las caderas y guiándolo hacia el suelo.' WHERE name_en = 'Car Deadlift';
UPDATE public.exercises SET instructions_es = 'Mientras permaneces de pie en posición erguida, sostén un disco de barra con ambas manos en las posiciones de las 3 y las 9 en punto. Las palmas de tus manos deben estar enfrentadas y tus brazos deben estar extendidos directamente frente a ti. Esta será tu posición inicial.
Inicia el movimiento girando el disco lo más lejos posible hacia un lado. Utiliza el mismo tipo de movimiento que harías para girar un volante hacia un lado.
Invierte el movimiento, girándolo por completo hacia el lado opuesto.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Car Drivers';
UPDATE public.exercises SET instructions_es = 'Comienza con los pies separados unos pocos centímetros y el brazo izquierdo arriba en una posición atlética y relajada.
Con el pie derecho, da un paso rápido hacia atrás y eleva la rodilla.
Sube los brazos rápidamente cuando levantes la rodilla derecha, asegurándote de que la rodilla suba y baje en línea recta. Evita girar los pies a medida que te mueves y continúa mirando hacia adelante mientras te desplazas lateralmente.' WHERE name_en = 'Carioca Quick Step';
UPDATE public.exercises SET instructions_es = 'Colócate en el suelo sobre tus manos y rodillas.
Mete el abdomen y redondea la columna vertebral, la zona lumbar, los hombros y el cuello, dejando caer la cabeza.
Mantén la posición durante 15 segundos.' WHERE name_en = 'Cat Stretch';
UPDATE public.exercises SET instructions_es = 'Comienza de pie mirando hacia una pared o hacia un compañero.
Con ambas manos, coloca el balón detrás de tu cabeza, estirándote lo más posible, y lanza con fuerza el balón hacia adelante.
Asegúrate de acompañar el movimiento del lanzamiento, preparándote para recibir el rebote de tu tiro. Si lanzas contra la pared, asegúrate de estar lo suficientemente cerca de ella para recibir el rebote y apunta un poco más alto de lo que lo harías con un compañero.' WHERE name_en = 'Catch and Overhead Throw';
UPDATE public.exercises SET instructions_es = 'Necesitarás dos agarres de cable y un banco plano, además de cadenas, para este ejercicio. Engancha el centro de las cadenas a los agarres y colócate en el banco plano. Tus codos deben estar apuntando directamente hacia arriba.
Comienza extendiendo el codo, manteniendo inmóvil la parte superior del brazo y con las muñecas en pronación.
Haz una pausa en el bloqueo e invierte el movimiento para volver a la posición inicial.' WHERE name_en = 'Chain Handle Extension';
UPDATE public.exercises SET instructions_es = 'Comienza conectando las cadenas a los agarres del cable. Colócate en el banco plano en la misma posición que para un press con mancuernas. Tus muñecas deben estar en pronación y los brazos perpendiculares al suelo. Esta será tu posición inicial.
Baja las cadenas flexionando los codos, descargando parte de la cadena sobre el suelo.
Continúa hasta que tu codo forme un ángulo de 90 grados y luego invierte el movimiento extendiendo el codo hasta el bloqueo.' WHERE name_en = 'Chain Press';
UPDATE public.exercises SET instructions_es = 'Siéntate erguido en una silla y agarra el asiento por los lados.
Eleva una pierna extendiendo la rodilla y flexionando el tobillo mientras lo haces.
Mueve lentamente esa pierna hacia afuera lo más lejos que puedas, y luego regresa al centro y baja.
Repite con la otra pierna.' WHERE name_en = 'Chair Leg Extended Stretch';
UPDATE public.exercises SET instructions_es = 'Siéntate erguido en una silla.
Inclínate hacia un lado con el brazo por encima de la cabeza. Puedes sujetarte a la silla con la mano libre.
Mantén la posición durante 10 segundos y repite con el otro lado.' WHERE name_en = 'Chair Lower Back Stretch';
UPDATE public.exercises SET instructions_es = 'Para comenzar, primero ajuste la barra a una posición que se adapte mejor a su altura. Una vez cargada la barra, colóquese debajo de ella y ubíquela a lo largo de la parte posterior de sus hombros.
Tome la barra con las manos mirando hacia adelante, desanclélela y levántela del soporte extendiendo las piernas.
Mueva los pies hacia adelante unos 45 cm (18 pulgadas) por delante de la barra. Posicione sus piernas a la anchura de los hombros con las puntas de los pies ligeramente hacia afuera. Mire hacia adelante en todo momento y mantenga la columna neutra o ligeramente arqueada. Esta será su posición inicial.
Baje lentamente la barra doblando las rodillas mientras mantiene una postura erguida con la cabeza erguida. Continúe bajando hasta que el ángulo entre el muslo y la pantorrilla sea menor a 90 grados.
Comience a levantar la barra mientras exhala empujando el suelo con los talones de los pies, extendiendo las rodillas y regresando a la posición inicial.
Repita para la cantidad recomendada de repeticiones.' WHERE name_en = 'Chair Squat';
UPDATE public.exercises SET instructions_es = 'Siéntese en el borde de una silla, sujetando el respaldo.
Enderece los brazos, manteniendo la espalda recta, y tire del torso hacia adelante para sentir un estiramiento. Mantenga la posición durante 20-30 segundos.' WHERE name_en = 'Chair Upper Body Stretch';
UPDATE public.exercises SET instructions_es = 'Comience de pie con las piernas juntas, sosteniendo una barra o un palo de escoba.
Tome el palo con un agarre ligeramente más ancho que el ancho de los hombros y sosténgalo frente a usted con las palmas mirando hacia abajo.
Con cuidado, levante el palo hacia arriba y por detrás de su cabeza.' WHERE name_en = 'Chest And Front Of Shoulder Stretch';
UPDATE public.exercises SET instructions_es = 'Comience en una posición de tres puntos, en cuclillas con la espalda plana y una mano en el suelo. Coloque el balón medicinal directamente frente a usted.
Para comenzar, dé su primer paso mientras lleva el balón hacia su pecho, posicionando ambas manos para prepararse para el lanzamiento.
Al dar el segundo paso, suelte explosivamente el balón hacia adelante con la mayor fuerza posible.' WHERE name_en = 'Chest Push from 3 point stance';
UPDATE public.exercises SET instructions_es = 'Comience arrodillado frente a una pared o use un compañero. Sostenga el balón con ambas manos pegado al pecho.
Ejecute el pase impulsándose con fuerza hacia adelante y hacia afuera con las caderas mientras empuja el balón con la mayor fuerza posible.
Complete el movimiento dejándose caer hacia adelante y amortiguando la caída con las manos.
Regrese inmediatamente a la posición erguida. Repita el número deseado de repeticiones.' WHERE name_en = 'Chest Push (multiple response)';
UPDATE public.exercises SET instructions_es = 'Comience arrodillado sosteniendo el balón medicinal con ambas manos firmemente pegadas al pecho.
Ejecute el pase impulsándose con fuerza hacia adelante y hacia afuera con las caderas mientras empuja el balón lo más lejos posible.
Complete el movimiento dejándose caer hacia adelante y amortiguando la caída con las manos.' WHERE name_en = 'Chest Push (single response)';
UPDATE public.exercises SET instructions_es = 'Comience en una postura atlética con las rodillas dobladas, las caderas hacia atrás y la espalda plana. Sostenga el balón medicinal cerca de sus piernas. Esta será su posición inicial.
Mientras da su primer paso, lleve el balón medicinal hacia su pecho.
Al dar el segundo paso, empuje explosivamente el balón hacia adelante e inmediatamente corra a máxima velocidad durante 10 yardas después del lanzamiento. ¡Si es realmente rápido, podrá atrapar su propio pase!' WHERE name_en = 'Chest Push with Run Release';
UPDATE public.exercises SET instructions_es = 'Póngase a gatas (manos y rodillas) al lado de una pelota de ejercicio.
Coloque los codos sobre la pelota, manteniendo el brazo extendido hacia el costado. Esta será su posición inicial.
Baje el torso hacia el suelo, manteniendo el codo sobre la pelota. Mantenga el estiramiento durante 20-30 segundos y repita con el otro brazo.' WHERE name_en = 'Chest Stretch on Stability Ball';
UPDATE public.exercises SET instructions_es = 'Póngase a gatas y avance las manos hacia adelante.
Baje los glúteos hasta sentarse sobre los talones. Deje que los brazos se deslicen por el suelo mientras se sienta hacia atrás para estirar toda la columna vertebral.
Una vez que se acomode sobre sus talones, lleve las manos al lado de los pies y relájese. "Respire" hacia su espalda. Apoye la frente en el suelo. Evite esta posición si tiene problemas en las rodillas.' WHERE name_en = 'Child''s Pose';
UPDATE public.exercises SET instructions_es = 'Sujete la barra de dominadas con las palmas mirando hacia su torso y un agarre más estrecho que el ancho de los hombros.
Con ambos brazos extendidos frente a usted sosteniendo la barra al ancho de agarre elegido, mantenga el torso lo más recto posible mientras crea una curvatura en la parte inferior de la espalda y saca el pecho. Esta es su posición inicial. Consejo: Mantener el torso lo más recto posible maximiza la estimulación de los bíceps mientras minimiza la participación de la espalda.
Mientras exhala, tire del torso hacia arriba hasta que su cabeza esté aproximadamente al nivel de la barra. Concéntrese en usar los músculos de los bíceps para realizar el movimiento. Mantenga los codos cerca de su cuerpo. Consejo: El torso superior debe permanecer estacionario a medida que se mueve en el espacio y solo deben moverse los brazos. Los antebrazos no deben hacer otro trabajo más que sostener la barra.
Después de un segundo de apretar los bíceps en la posición contraída, baje lentamente el torso de regreso a la posición inicial, hasta que los brazos estén completamente extendidos. Inhale mientras realiza esta parte del movimiento.
Repita este movimiento durante la cantidad prescrita de repeticiones.' WHERE name_en = 'Chin-Up';
UPDATE public.exercises SET instructions_es = 'Siéntese en el suelo.
Coloque ambas manos en la parte posterior de la cabeza con los dedos entrelazados, los pulgares apuntando hacia abajo y los codos apuntando hacia adelante. Tire lentamente de la cabeza hacia abajo, acercándola al pecho. Mantenga la posición durante 20-30 segundos.' WHERE name_en = 'Chin To Chest Stretch';
UPDATE public.exercises SET instructions_es = 'La mancuerna de circo es una mancuerna gigante con un agarre grueso. Comience con la mancuerna entre sus pies y sujete el agarre con ambas manos.
Haga una cargada (clean) extendiendo sus caderas y rodillas para llevar la mancuerna hacia el hombro deseado, soltando la mano secundaria.
Asegúrese de colocar una de las cabezas de la mancuerna detrás del hombro para evitar perder el equilibrio. Para levantarla por encima de la cabeza, haga una ligera flexión de rodillas e impúlsese hacia arriba mientras extiende la mancuerna por encima de la cabeza, inclinándose ligeramente en dirección opuesta a ella a medida que lo hace.
Guíe con cuidado la mancuerna de regreso al suelo, manteniéndola bajo control en todo momento. Es mejor realizar este ejercicio sobre una colchoneta de goma gruesa para evitar dañar el suelo.' WHERE name_en = 'Circus Bell';
UPDATE public.exercises SET instructions_es = 'Con una barra en el suelo cerca de las espinillas, tome un agarre prono (o de gancho) justo por fuera de las piernas. Baje las caderas manteniendo el peso centrado en los talones, la espalda recta, la cabeza mirando hacia adelante, el pecho erguido y los hombros ligeramente por delante de la barra. Esta será su posición inicial.

Comience el primer tirón empujando con los talones y extendiendo las rodillas. El ángulo de la espalda debe mantenerse constante y los brazos deben permanecer rectos. Mueva el peso con control a medida que sube por encima de las rodillas.
A continuación viene el segundo tirón, la fuente principal de aceleración para la cargada (clean). A medida que la barra se acerca a la mitad del muslo, comience a extender las caderas. Con un movimiento similar a un salto, acelere extendiendo caderas, rodillas y tobillos, usando la velocidad para mover la barra hacia arriba. No debería haber necesidad de tirar activamente con los brazos para acelerar el peso; al final del segundo tirón, el cuerpo debe estar completamente extendido, inclinado ligeramente hacia atrás y con los brazos aún extendidos.
Cuando se alcance la extensión completa, pase al tercer tirón encogiéndose de hombros y flexionando los brazos agresivamente con los codos hacia arriba y hacia afuera. En el punto máximo de extensión, tire de su cuerpo agresivamente hacia abajo, girando los codos debajo de la barra mientras lo hace. Reciba la barra en una posición de sentadilla frontal, cuya profundidad dependerá de la altura de la barra al final del tercer tirón. La barra debe descansar sobre los hombros adelantados, tocando ligeramente la garganta con las manos relajadas. Continúe bajando hasta la posición más profunda de la sentadilla, lo que ayudará en la recuperación.
Recupérese de inmediato empujando con los talones, manteniendo el torso erguido y los codos elevados. Continúe hasta quedar completamente de pie.' WHERE name_en = 'Clean';
UPDATE public.exercises SET instructions_es = 'Comience de pie con una barra cerca de sus espinillas. Sus pies deben estar directamente debajo de sus caderas con las puntas ligeramente hacia afuera. Agarre la barra con un agarre prono doble o agarre de gancho, aproximadamente al ancho de los hombros. Póngase en cuclillas hacia la barra. Su columna debe estar en extensión completa, con un ángulo de espalda que coloque sus hombros por delante de la barra y su espalda lo más vertical posible.
Comience empujando el suelo a través de la parte delantera de sus talones. A medida que la barra ascienda, mantenga un ángulo de espalda constante. Abra las rodillas hacia los lados para evitar que se interpongan en el trayecto de la barra.
Una vez que la barra supere las rodillas, complete el levantamiento empujando las caderas hacia la barra hasta que las caderas y las rodillas estén completamente extendidas.' WHERE name_en = 'Clean Deadlift';
UPDATE public.exercises SET instructions_es = 'Con una barra en el suelo cerca de las espinillas, tome un agarre prono o de gancho justo por fuera de las piernas. Baje las caderas manteniendo el peso centrado en los talones, la espalda recta, la cabeza mirando hacia adelante, el pecho erguido y los hombros ligeramente por delante de la barra. Esta será su posición inicial.
Comience el primer tirón empujando con los talones y extendiendo las rodillas. El ángulo de la espalda debe mantenerse constante, los brazos deben permanecer rectos y los codos apuntando hacia afuera. Mueva el peso con control a medida que sube por encima de las rodillas.
A continuación viene el segundo tirón, la fuente principal de aceleración para la cargada (clean). A medida que la barra se acerca a la mitad del muslo, comience a extender las caderas. Con un movimiento similar a un salto, acelere extendiendo caderas, rodillas y tobillos, usando la velocidad para mover la barra hacia arriba. No debería haber necesidad de tirar activamente con los brazos para acelerar el peso; al final del segundo tirón, el cuerpo debe estar completamente extendido, inclinado ligeramente hacia atrás y con los brazos aún extendidos. La extensión completa debe ser violenta y abrupta, asegurándose de no prolongarla más de lo necesario.' WHERE name_en = 'Clean Pull';
UPDATE public.exercises SET instructions_es = 'Comience con un agarre al ancho de los hombros, prono doble o de gancho, con la barra colgando a la altura de la mitad del muslo. Su espalda debe estar recta e inclinada ligeramente hacia adelante.
Encoja los hombros hacia las orejas. Aunque este ejercicio generalmente se puede cargar con más peso que una cargada (clean), evite sobrecargarlo al punto de ralentizar la ejecución.' WHERE name_en = 'Clean Shrug';
UPDATE public.exercises SET instructions_es = 'Con una barra en el suelo cerca de las espinillas, tome un agarre prono o de gancho justo por fuera de las piernas. Baje las caderas manteniendo el peso centrado en los talones, la espalda recta, la cabeza mirando hacia adelante, el pecho erguido y los hombros ligeramente por delante de la barra. Esta será su posición inicial.
Comience el primer tirón empujando con los talones y extendiendo las rodillas. El ángulo de la espalda debe mantenerse constante y los brazos deben permanecer rectos. Mueva el peso con control a medida que sube por encima de las rodillas.
A continuación viene el segundo tirón, la fuente principal de aceleración para la cargada (clean). A medida que la barra se acerca a la mitad del muslo, comience a extender las caderas. Con un movimiento similar a un salto, acelere extendiendo caderas, rodillas y tobillos, usando la velocidad para mover la barra hacia arriba. No debería haber necesidad de tirar activamente con los brazos para acelerar el peso; al final del segundo tirón, el cuerpo debe estar completamente extendido, inclinado ligeramente hacia atrás y con los brazos aún extendidos.
Cuando se alcance la extensión completa, pase al tercer tirón encogiéndose de hombros y flexionando los brazos agresivamente con los codos hacia arriba y hacia afuera. En el punto máximo de extensión, tire de su cuerpo agresivamente hacia abajo, girando los codos debajo de la barra mientras lo hace. Reciba la barra en una posición de sentadilla frontal, cuya profundidad dependerá de la altura de la barra al final del tercer tirón. La barra debe descansar sobre los hombros adelantados, tocando ligeramente la garganta con las manos relajadas. Continúe bajando hasta la posición más profunda de la sentadilla, lo que ayudará en la recuperación.
Recupérese de inmediato empujando con los talones, manteniendo el torso erguido y los codos elevados. Continúe hasta quedar completamente de pie.
La segunda fase es el envión (jerk), que eleva el peso por encima de la cabeza. De pie con el peso apoyado en la parte delantera de los hombros, comience con la flexión (dip). Con los pies directamente debajo de sus caderas, flexione las rodillas sin mover las caderas hacia atrás. Baje solo un poco y cambie de dirección de la manera más potente posible.
Empuje a través de los talones para generar la mayor velocidad y fuerza posible, y asegúrese de apartar la cabeza del camino a medida que la barra sale de los hombros.
En este momento, cuando los pies despeguen del suelo, deben colocarse en la posición de recepción lo más rápido posible. En el breve momento en que los pies no estén empujando activamente contra la plataforma, el esfuerzo del atleta por empujar la barra hacia arriba lo empujará hacia abajo. Los pies deben separarse en tijera, con un pie hacia adelante y un pie hacia atrás. Reciba la barra con los brazos bloqueados por encima de la cabeza. Regrese a la posición de pie.' WHERE name_en = 'Clean and Jerk';
UPDATE public.exercises SET instructions_es = 'Adopte una postura al ancho de los hombros, con las rodillas por dentro de los brazos. Ahora, manteniendo la espalda plana, dóblese por las rodillas y las caderas para poder agarrar la barra con los brazos completamente extendidos y un agarre en pronación ligeramente más ancho que el ancho de los hombros. Apunte los codos hacia los lados. La barra debe estar cerca de las espinillas. Posicione los hombros sobre la barra o ligeramente por delante de ella. Establezca una postura de espalda plana. Esta será su posición inicial.
Comience a tirar de la barra extendiendo las rodillas. Mueva las caderas hacia adelante y eleve los hombros al mismo ritmo mientras mantiene constante el ángulo de la espalda; continúe levantando la barra hacia arriba manteniéndola cerca de su cuerpo.
A medida que la barra supere la rodilla, extienda los tobillos, las rodillas y las caderas con fuerza, similar a un movimiento de salto. Mientras lo hace, continúe guiando la barra con las manos, encogiendo los hombros y usando el impulso de su movimiento para tirar de la barra lo más alto posible. La barra debe desplazarse cerca de su cuerpo y debe mantener los codos hacia afuera.
En la elevación máxima, sus pies deben despegarse del suelo y debe comenzar a meterse debajo de la barra. La mecánica de esto podría cambiar ligeramente según el peso utilizado. Debe descender a una posición de sentadilla a medida que se mete debajo de la barra.
Cuando la barra alcance su altura máxima, gire los codos alrededor y por debajo de la barra. Apoye la barra sobre la parte delantera de los hombros mientras mantiene el torso erguido y flexiona las caderas y rodillas para absorber el peso de la barra.
Póngase completamente de pie, sosteniendo la barra en la posición de cargada (clean).
Sin mover los pies, presione la barra por encima de la cabeza mientras exhala. Baje la barra de manera controlada.' WHERE name_en = 'Clean and Press';
UPDATE public.exercises SET instructions_es = 'Con una barra sobre cajones o soportes a la altura deseada, tome un agarre prono o de gancho justo por fuera de las piernas. Baje las caderas manteniendo el peso centrado en los talones, la espalda recta, la cabeza mirando hacia adelante, el pecho erguido y los hombros ligeramente por delante de la barra. Esta será su posición inicial.
Comience el primer tirón empujando con los talones y extendiendo las rodillas. El ángulo de la espalda debe mantenerse constante y los brazos deben permanecer rectos con los codos apuntando hacia afuera.
Cuando se alcance la extensión completa, pase a la posición de recepción encogiéndose de hombros y flexionando los brazos agresivamente con los codos hacia arriba y hacia afuera. Tire de su cuerpo agresivamente hacia abajo, girando los codos debajo de la barra mientras lo hace. Reciba la barra en una posición de sentadilla frontal, cuya profundidad dependerá de la altura de la barra al final del tercer tirón. La barra debe descansar sobre los hombros adelantados, tocando ligeramente la garganta con las manos relajadas. Continúe bajando hasta la posición más profunda de la sentadilla, lo que ayudará en la recuperación.
Recupérese de inmediato empujando con los talones, manteniendo el torso erguido y los codos elevados. Continúe hasta quedar completamente de pie. Devuelva el peso a los cajones para la siguiente repetición.' WHERE name_en = 'Clean from Blocks';
UPDATE public.exercises SET instructions_es = 'Colóquese en posición boca abajo (prono) en el suelo, sosteniendo su peso sobre sus manos y las puntas de los pies.
Sus brazos deben estar completamente extendidos con las manos a una anchura aproximada a la de los hombros. Mantenga su cuerpo recto durante todo el movimiento. Esta será su posición inicial.
Descienda flexionando los codos, bajando el pecho hacia el suelo.
En el fondo, invierta el movimiento empujándose hacia arriba mediante la extensión de los codos lo más rápido posible hasta quedar en el aire. Intente "saltar" de 30 a 45 cm (12-18 pulgadas) hacia un lado.
A medida que acelera hacia arriba, mueva el pie exterior en dirección contraria a su desplazamiento. Al despegar del suelo, gire su cuerpo unos 30 grados para la siguiente repetición.
Regrese a la posición inicial y repita el ejercicio, avanzando en círculo hasta regresar al punto de partida.' WHERE name_en = 'Clock Push-Up';
UPDATE public.exercises SET instructions_es = 'Acuéstese en un banco plano. Utilizando un agarre estrecho (aproximadamente del ancho de los hombros), levante la barra del soporte y sosténgala directamente sobre usted con los brazos bloqueados. Esta será su posición inicial.
Mientras inhala, baje lentamente hasta sentir la barra en el centro de su pecho. Consejo: Asegúrese de que, a diferencia del press de banca regular, mantenga los codos cerca del torso en todo momento para maximizar la participación de los tríceps.
Tras una pausa de un segundo, lleve la barra de regreso a la posición inicial mientras exhala y empuja la barra usando los músculos de sus tríceps. Bloquee los brazos en la posición contraída, mantenga la posición durante un segundo y luego comience a bajar lentamente de nuevo. Consejo: Debería tomar al menos el doble de tiempo bajar que subir.
Repita el movimiento durante la cantidad prescrita de repeticiones.
Cuando termine, vuelva a colocar la barra en el soporte.' WHERE name_en = 'Close-Grip Barbell Bench Press';
UPDATE public.exercises SET instructions_es = 'Coloque una mancuerna verticalmente sobre un banco plano.
Asegurándose de que la mancuerna se mantenga firme en la parte superior del banco, acuéstese de forma perpendicular al banco apoyando solo los hombros sobre la superficie. Las caderas deben estar por debajo del banco y las piernas dobladas con los pies firmemente apoyados en el suelo.
Sujete la mancuerna con ambas manos y sosténgala directamente sobre su pecho a la distancia de los brazos extendidos. Ambas palmas deben presionar contra la parte inferior de los discos superiores de la mancuerna. Esta será su posición inicial.
Inicie el movimiento bajando la mancuerna hacia su pecho.
Regrese a la posición inicial extendiendo los codos.' WHERE name_en = 'Close-Grip Dumbbell Press';
UPDATE public.exercises SET instructions_es = 'Sujete una banda elástica a cada extremo de la barra. Tome la barra colocando un pie en el medio de la banda. Póngase erguido con un agarre estrecho en supinación en la barra EZ. Los codos deben estar cerca del torso. Esta será su posición inicial.
Mientras mantiene la parte superior de los brazos inmóvil, flexione los codos para ejecutar el curl. Exhale a medida que levanta el peso.
Continúe el movimiento hasta que sus bíceps estén completamente contraídos y la barra esté al nivel de los hombros. Mantenga la posición contraída durante un segundo y apriete los bíceps con fuerza.
Comience a llevar lentamente la barra de regreso a la posición inicial mientras inhala.
Repita para la cantidad recomendada de repeticiones.' WHERE name_en = 'Close-Grip EZ-Bar Curl with Band';
UPDATE public.exercises SET instructions_es = 'Acuéstese en un banco plano con una barra EZ cargada con el peso adecuado.
Con un agarre estrecho, levante la barra y sosténgala directamente sobre su torso con los codos hacia adentro. Los brazos deben estar perpendiculares al suelo. Esta será su posición inicial.
Ahora baje la barra hacia la parte inferior del pecho mientras inhala. Mantenga los codos hacia adentro mientras realiza este movimiento.
Utilizando los tríceps para empujar la barra hacia arriba, presiónela de regreso a la posición inicial extendiendo los codos mientras exhala.
Repita.' WHERE name_en = 'Close-Grip EZ-Bar Press';
UPDATE public.exercises SET instructions_es = 'Póngase de pie con el torso erguido mientras sostiene una barra Z (E-Z Curl) en los agarres internos más cercanos. Las palmas de sus manos deben mirar hacia adelante y estar ligeramente inclinadas hacia adentro debido a la forma de la barra. Los codos deben estar cerca del torso. Esta será su posición inicial.
Mientras mantiene inmóvil la parte superior de los brazos, flexione las pesas hacia adelante mientras contrae los bíceps al exhalar. Consejo: Solo deben moverse los antebrazos.
Continúe el movimiento hasta que sus bíceps estén completamente contraídos y la barra esté al nivel de los hombros. Mantenga la posición contraída durante un segundo y apriete los bíceps con fuerza.
Comience a llevar lentamente la barra de regreso a la posición inicial mientras inhala.
Repita para la cantidad recomendada de repeticiones.' WHERE name_en = 'Close-Grip EZ Bar Curl';
UPDATE public.exercises SET instructions_es = 'Siéntate en una máquina de jalón al pecho con una barra ancha enganchada en la polea superior. Asegúrate de ajustar los cojines para las rodillas de la máquina a tu altura. Estos cojines evitarán que la resistencia acoplada a la barra levante tu cuerpo.
Toma la barra con las palmas mirando hacia adelante usando el agarre indicado. Nota sobre los agarres: Para un agarre ancho, tus manos deben estar separadas a una distancia mayor que el ancho de tus hombros. Para un agarre medio, tus manos deben estar separadas a una distancia igual al ancho de tus hombros y para un agarre estrecho a una distancia menor que el ancho de tus hombros.
Mientras tienes ambos brazos extendidos frente a ti —sosteniendo la barra con el ancho de agarre elegido—, echa el torso hacia atrás unos 30 grados aproximadamente mientras creas una curvatura en la zona lumbar y sacas el pecho. Esta es tu posición inicial.
Mientras exhalas, baja la barra hasta que toque la parte superior del pecho tirando de los hombros y los brazos hacia abajo y hacia atrás. Consejo: Concéntrate en contraer los músculos de la espalda una vez que alcances la posición de máxima contracción. El torso debe permanecer inmóvil (solo deben moverse los brazos). Los antebrazos no deben hacer ningún otro trabajo excepto sostener la barra; por lo tanto, no intentes tirar de la barra hacia abajo usando los antebrazos.
Tras un segundo en la posición contraída, mientras juntas las escápulas, sube lentamente la barra de regreso a la posición inicial hasta que tus brazos estén completamente extendidos y los dorsales totalmente estirados. Inhala durante esta fase del movimiento.
6. Repite este movimiento durante el número de repeticiones indicado.' WHERE name_en = 'Close-Grip Front Lat Pulldown';
UPDATE public.exercises SET instructions_es = 'Acuéstate en el suelo y coloca tus manos sobre una mancuerna vertical. Apoyando tu peso sobre las puntas de los pies y las manos, mantén el torso rígido y los codos pegados al cuerpo con los brazos extendidos. Esta será tu posición inicial.
Baja el cuerpo permitiendo que los codos se doblen mientras inhalas. Mantén el cuerpo recto, sin permitir que la cadera se eleve o se hunda.
Empuja el cuerpo de regreso a la posición inicial extendiendo los codos. Exhala mientras realizas este paso.
Tras una pausa en la posición contraída, repite el movimiento durante la cantidad de repeticiones indicada.' WHERE name_en = 'Close-Grip Push-Up off of a Dumbbell';
UPDATE public.exercises SET instructions_es = 'Sostén una barra con ambas manos, con las palmas hacia arriba y separadas unos pocos centímetros.
Párate con el torso recto y la cabeza erguida. Tus pies deben estar aproximadamente al ancho de los hombros y los codos pegados al torso. Esta será tu posición inicial. Consejo: Mantendrás la parte superior de los brazos y los codos inmóviles durante todo el movimiento.
Curva la barra hacia arriba en un movimiento semicircular hasta que los antebrazos toquen tus bíceps. Exhala mientras realizas esta parte del movimiento y contrae fuertemente los bíceps durante un segundo en la parte superior. Consejo: Evita doblar la espalda o hacer movimientos de balanceo al levantar el peso. Solo deben moverse los antebrazos.
Baja lentamente de regreso a la posición inicial mientras inhalas.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Close-Grip Standing Barbell Curl';
UPDATE public.exercises SET instructions_es = 'Comienza acostándote boca arriba en el suelo. Tus piernas deben estar rectas y tus brazos extendidos detrás de la cabeza. Esta será tu posición inicial.
Para realizar el movimiento, lleva las rodillas hacia el pecho, rotando la pelvis para levantar los glúteos del suelo. Al hacerlo, flexiona la columna, llevando los brazos hacia adelante sobre la cabeza para realizar un movimiento de encogimiento (crunch) simultáneo.
Tras una breve pausa, regresa a la posición inicial.' WHERE name_en = 'Cocoons';
UPDATE public.exercises SET instructions_es = 'Con el peso cargado, realiza un agarre Zercher en el extremo del implemento. Coloca la barra en el pliegue del codo y sujétate la muñeca. Intenta mantener el peso alejado de los antebrazos.
Comienza levantando el peso del suelo. Mantén una postura firme y erguida a medida que empiezas a caminar, dando pasos cortos y rápidos. Mira hacia arriba y al frente mientras giras en círculo. No contengas la respiración durante la prueba. Continúa caminando hasta completar una o más vueltas completas.' WHERE name_en = 'Conan''s Wheel';
UPDATE public.exercises SET instructions_es = 'Siéntate en un banco plano con una mancuerna frente a ti entre las piernas. Las piernas deben estar abiertas con las rodillas dobladas y los pies apoyados en el suelo.
Usa el brazo derecho para levantar la mancuerna. Coloca la parte posterior del brazo derecho en la parte superior de la cara interna del muslo derecho. Rota la palma de la mano hasta que mire hacia adelante, alejándose del muslo. Consejo: El brazo debe estar extendido y la mancuerna debe quedar por encima del suelo. Esta será tu posición inicial.
Mientras mantienes quieta la parte superior del brazo, curva el peso hacia adelante mientras contraes el bíceps y exhala. Solo deben moverse los antebrazos. Continúa el movimiento hasta que tus bíceps estén completamente contraídos y la mancuerna esté a la altura del hombro. Consejo: En la parte superior del movimiento, asegúrate de que el dedo meñique esté más alto que el pulgar. Esto garantiza una buena contracción. Mantén la posición contraída durante un segundo mientras aprietas el bíceps.
Comienza a bajar lentamente la mancuerna a la posición inicial mientras inhalas. Precaución: Evita los movimientos de balanceo en todo momento.
Repite durante la cantidad recomendada de repeticiones. Luego repite el movimiento con el brazo izquierdo.' WHERE name_en = 'Concentration Curls';
UPDATE public.exercises SET instructions_es = 'Acuéstate boca arriba y dobla las rodillas unos 60 grados.
Mantén los pies apoyados en el suelo y coloca las manos suavemente detrás de la cabeza. Esta será tu posición inicial.
Ahora elévate e inclina el codo y el hombro derechos a través del cuerpo mientras llevas la rodilla izquierda hacia el hombro izquierdo al mismo tiempo. Intenta alcanzar tu rodilla con el codo. Exhala mientras realizas este movimiento. Consejo: Intenta llevar el hombro hacia la rodilla en lugar de solo el codo y recuerda que la clave es contraer los abdominales al realizar el movimiento, no solo mover el codo.
Ahora vuelve a bajar a la posición inicial mientras inhalas y repite con el codo izquierdo y la rodilla derecha.
Continúa alternando de esta manera hasta completar todas las repeticiones indicadas.' WHERE name_en = 'Cross-Body Crunch';
UPDATE public.exercises SET instructions_es = 'Párate derecho con una mancuerna en cada mano. Tus manos deben estar a los lados con las palmas mirando hacia adentro.
Mientras mantienes las palmas mirando hacia adentro y sin girar el brazo, eleva la mancuerna del brazo derecho hacia el hombro izquierdo mientras exhalas. Toca la parte superior de la mancuerna con el hombro y mantén la contracción durante un segundo.
Baja lentamente la mancuerna siguiendo la misma trayectoria mientras inhalas y luego repite el mismo movimiento con el brazo izquierdo.
Continúa alternando de esta manera hasta realizar la cantidad recomendada de repeticiones para cada brazo.' WHERE name_en = 'Cross Body Hammer Curl';
UPDATE public.exercises SET instructions_es = 'Fija una banda de ejercicio alrededor de un poste fijo.
Mientras miras hacia el lado opuesto al poste, agarra los agarres en ambos extremos de la banda y da un paso hacia adelante lo suficiente para crear tensión en la banda.
Eleva los brazos hacia los lados, paralelos al suelo, perpendiculares al torso (tu torso y los brazos deben formar la letra "T") y con las palmas mirando hacia adelante. Mantenlos extendidos con una ligera flexión en los codos. Esta será tu posición inicial.
Mientras mantienes los brazos rectos, llévalos a través del pecho en un movimiento semicircular hacia el frente mientras exhalas y contraes los pectorales. Mantén la contracción durante un segundo.
Regresa lentamente a la posición inicial mientras inhalas.
Realiza el ejercicio durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Cross Over - With Bands';
UPDATE public.exercises SET instructions_es = 'Párate con los pies separados al ancho de los hombros. Esta será tu posición inicial.
Realiza una zancada trasera dando un paso hacia atrás con un pie y flexionando la cadera y la rodilla delantera. Al hacerlo, rota el torso hacia el lado de la pierna delantera.
Tras una breve pausa, regresa a la posición inicial y repite en el otro lado, continuando de forma alternada.' WHERE name_en = 'Crossover Reverse Lunge';
UPDATE public.exercises SET instructions_es = 'En el crucifijo, mantienes pesos estáticos hacia los lados durante un tiempo determinado. Aunque la prueba se puede practicar con mancuernas, es mejor entrenar con uno de los diversos implementos utilizados, como hachas o martillos, ya que la sensación es diferente.
Comienza de pie y eleva los brazos hacia los lados sosteniendo los implementos. Tus brazos deben estar paralelos al suelo. En competición, se utilizan jueces o sensores para indicarte cuándo dejas de estar en paralelo. Mantén la posición todo el tiempo que puedas. Por lo general, los pesos deben ser lo suficientemente pesados como para llegar al fallo entre 30 y 60 segundos.' WHERE name_en = 'Crucifix';
UPDATE public.exercises SET instructions_es = 'Acuéstate en el suelo con la espalda plana y las rodillas dobladas formando un ángulo de unos 60 grados entre los isquiotibiales y las pantorrillas.
Mantén los pies apoyados en el suelo y estira los brazos por encima de la cabeza con las palmas cruzadas. Esta será tu posición inicial.
Eleva la parte superior del cuerpo hacia adelante y despega las escápulas del suelo. En todo momento, mantén los brazos alineados con la cabeza, el cuello y los hombros. No los muevas hacia adelante desde esa posición. Exhala mientras realizas esta parte del movimiento y mantén la contracción durante un segundo.
Baja lentamente a la posición inicial mientras inhalas.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Crunch - Hands Overhead';
UPDATE public.exercises SET instructions_es = 'Acuéstate boca arriba con los pies apoyados en una pelota de ejercicio y las rodillas dobladas en un ángulo de 90 grados.
Coloca los pies separados de 7 a 10 centímetros y apunta con los dedos de los pies hacia adentro para que se toquen.
Coloca las manos suavemente a ambos lados de la cabeza manteniendo los codos hacia adentro. Consejo: No entrelaces los dedos detrás de la cabeza.
Empuja la zona lumbar contra el suelo para aislar mejor los músculos abdominales. Esta será tu posición inicial.
Comienza a despegar los hombros del suelo y continúa empujando con la zona lumbar tan fuerte como puedas. Los hombros solo deben elevarse unos 10 centímetros del suelo, y la zona lumbar debe permanecer en el suelo. Exhala mientras ejecutas esta parte del movimiento. Aprieta con fuerza los abdominales en la parte superior de la contracción y mantén la posición durante un segundo. Consejo: Concéntrate en un movimiento lento y controlled. Evita usar el impulso en cualquier momento.
Baja lentamente de regreso a la posición inicial mientras inhalas.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Crunch - Legs On Exercise Ball';
UPDATE public.exercises SET instructions_es = 'Acuéstate boca arriba con los pies apoyados en el suelo o apoyados en un banco con las rodillas dobladas en un ángulo de 90 grados. Si apoyas los pies en un banco, colócalos separados de 7 a 10 centímetros y apunta los dedos hacia adentro de modo que se toquen.
Ahora coloca las manos suavemente a ambos lados de la cabeza manteniendo los codos hacia adentro. Consejo: No entrelaces los dedos detrás de la cabeza.
Mientras empujas la zona lumbar contra el suelo para aislar mejor los músculos abdominales, comienza a despegar los hombros del suelo.
Continúa empujando tan fuerte como puedas con la zona lumbar mientras contraes los abdominales y exhalas. Los hombros solo deben elevarse unos 10 centímetros del suelo, y la zona lumbar debe permanecer en el suelo. En la parte superior del movimiento, contrae con fuerza los abdominales y mantén la contracción durante un segundo. Consejo: Concéntrate en un movimiento lento y controlado; no hagas trampa usando el impulso.
Tras la contracción de un segundo, comienza a bajar lentamente de nuevo a la posición inicial mientras inhalas.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Crunches';
UPDATE public.exercises SET instructions_es = 'Toma una mancuerna en cada mano con un agarre en pronación de pie. Eleva la parte superior de los brazos para que queden paralelos al suelo, dejando que los antebrazos cuelguen en la posición de "espantapájaros". Esta será tu posición inicial.
Para iniciar el movimiento, rota externamente los hombros para mover la parte superior del brazo 180 grados. Mantén fija la parte superior de los brazos, rotándolos hasta que las muñecas queden directamente sobre los codos y los antebrazos perpendiculares al suelo.
Ahora empuja las mancuernas extendiendo los codos, estirando los brazos por encima de la cabeza.
Regresa a la posición inicial mientras inhalas invirtiendo los pasos.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Cuban Press';
UPDATE public.exercises SET instructions_es = 'Siéntate erguido en el suelo.
Cruza la pierna derecha sobre la izquierda, manteniendo la rodilla doblada. La pierna izquierda debe estar recta y apoyada en el suelo.
Coloca el brazo izquierdo sobre la pierna derecha y la mano derecha en el suelo.
Rota la parte superior del cuerpo hacia la derecha y mantén la posición durante 10-20 segundos. Cambia de lado.' WHERE name_en = 'Dancer''s Stretch';
UPDATE public.exercises SET instructions_es = 'Comienza acostándote boca arriba con las manos extendidas hacia el techo.
Eleva los pies, las rodillas y las caderas a 90 grados.
Exhala con fuerza para bajar la caja torácica y aplanar la espalda contra el suelo, rotando la pelvis hacia arriba y apretando los glúteos. Mantén esta posición durante todo el movimiento. Esta será tu posición inicial.
Inicia el ejercicio extendiendo una pierna, estirando la rodilla y la cadera para colocar la pierna justo por encima del suelo.
Mantén la posición de la zona lumbar y de la pelvis a medida que realizas el movimiento, ya que la espalda tenderá a arquearse.
Mantente firme y regresa la pierna de trabajo a la posición inicial.
Repite en el lado opuesto, alternando hasta completar la serie.' WHERE name_en = 'Dead Bug';
UPDATE public.exercises SET instructions_es = 'Para hacer peso muerto con bandas cortas, simplemente pásalas por la barra antes de empezar y colócate sobre ellas. En el caso de bandas largas, deberán anclarse a una base segura, como mancuernas pesadas o una jaula/rack.
Con los pies y el agarre en posición, toma una respiración profunda y luego baja las caderas y dobla las rodillas hasta que tus espinillas entren en contacto con la barra. Mira hacia adelante con la cabeza, mantén el pecho erguido y la espalda arqueada, y comienza a empujar con los talones para mover el peso hacia arriba. Una vez que la barra supere las rodillas, tira con fuerza de la barra hacia atrás, juntando las escápulas mientras empujas las caderas hacia adelante contra la barra.
Baja la barra doblando las caderas y guiándola hasta el suelo.' WHERE name_en = 'Deadlift with Bands';
UPDATE public.exercises SET instructions_es = 'Puedes enganchar las cadenas a los extremos de la barra o simplemente colocar la parte media sobre la barra para que haya un mayor incremento de peso a medida que levantas.
Acércate a la barra de modo que quede centrada sobre tus pies. Tus pies deben estar separados aproximadamente al ancho de las caderas. Doblándote por la cadera, agarra la barra al ancho de los hombros, permitiendo que tus escápulas se protraigan. Por lo general, usarías un agarre prono o mixto en las series más pesadas. Con los pies y el agarre listos, toma una respiración profunda y luego baja las caderas y dobla las rodillas hasta que las espinillas toquen la barra.
Mira hacia adelante con la cabeza, mantén el pecho erguido y la espalda arqueada, y comienza a empujar con los talones para mover el peso hacia arriba. Una vez que la barra supere las rodillas, tira con fuerza de la barra hacia atrás, juntando las escápulas mientras empujas las caderas hacia adelante contra la barra.
Baja la barra doblando las caderas y guiándola hasta el suelo.' WHERE name_en = 'Deadlift with Chains';
UPDATE public.exercises SET instructions_es = 'Asegura tus piernas al final del banco declinado y acuéstate lentamente sobre el banco.
Usando un agarre de ancho medio (un agarre que cree un ángulo de 90 grados en medio del movimiento entre los antebrazos y la parte superior de los brazos), levanta la barra del soporte y sosténla directamente sobre ti con los brazos bloqueados. Los brazos deben estar perpendiculares al suelo. Esta será tu posición inicial. Consejo: Para proteger el manguito rotador, es recomendable contar con la ayuda de un asistente para sacar la barra del soporte.
Mientras inhalas, baja lentamente hasta que sientas la barra en la parte inferior del pecho.
Tras una pausa de un segundo, regresa la barra a la posición inicial mientras exhalas y empujas la barra usando los músculos del pecho. Bloquea los brazos y contrae el pecho en la posición contraída, mantén durante un segundo y luego comienza a bajar lentamente de nuevo. Consejo: Deberías tardar al menos el doble de tiempo en bajar que en subir.
Repite el movimiento durante la cantidad de repeticiones indicada.
Cuando termines, vuelve a colocar la barra en el soporte.' WHERE name_en = 'Decline Barbell Bench Press';
UPDATE public.exercises SET instructions_es = 'Asegura tus piernas al final del banco declinado y acuéstate lentamente en el banco.
Usando un agarre estrecho (un agarre ligeramente menor que el ancho de los hombros), levanta la barra del soporte y sostenla directamente sobre ti con los brazos bloqueados y los codos hacia adentro. Los brazos deben estar perpendiculares al suelo. Esta será tu posición inicial. Consejo: Para proteger el manguito rotador, es mejor si cuentas con la ayuda de un asistente para sacar la barra del soporte.
Ahora baja la barra hacia la parte inferior del pecho mientras inhalas. Mantén los codos hacia adentro mientras realizas este movimiento.
Usando los tríceps para volver a empujar la barra hacia arriba, presiónala de regreso a la posición inicial mientras exhalas.
Mientras inhalas y mantienes quieta la parte superior de los brazos, baja la barra lentamente moviendo los antebrazos en un movimiento semicircular hacia ti hasta que sientas que la barra toca ligeramente tu frente. Inhala mientras realizas esta parte del movimiento.
Levanta la barra de regreso a la posición inicial contrayendo los tríceps y exhalando.
Repite los pasos 3-6 hasta realizar la cantidad recomendada de repeticiones.' WHERE name_en = 'Decline Close-Grip Bench To Skull Crusher';
UPDATE public.exercises SET instructions_es = 'Asegura tus piernas al final del banco declinado y acuéstate.
Ahora coloca las manos suavemente a ambos lados de la cabeza manteniendo los codos hacia adentro. Consejo: No entrelaces los dedos detrás de la cabeza.
Mientras empujas la zona lumbar contra el banco para aislar mejor los músculos abdominales, comienza a despegar los hombros del banco.
Continúa empujando tan fuerte como puedas con la zona lumbar mientras contraes los abdominales y exhalas. Los hombros solo deben elevarse unos 10 centímetros del banco, y la zona lumbar debe permanecer en él. En la parte superior del movimiento, contrae con fuerza los abdominales y mantén la contracción durante un segundo. Consejo: Concéntrate en un movimiento lento y controlado; no hagas trampa usando el impulso.
Tras la contracción de un segundo, comienza a bajar lentamente de nuevo a la posición inicial mientras inhalas.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Decline Crunch';
UPDATE public.exercises SET instructions_es = 'Asegura tus piernas al final del banco declinado y acuéstate con una mancuerna en cada mano sobre tus muslos. Las palmas de las manos deben quedar mirándose entre sí.
Una vez acostado, mueve las mancuernas frente a ti al ancho de los hombros.
Una vez al ancho de los hombros, rota las muñecas hacia adelante para que las palmas de tus manos queden mirando hacia afuera. Esta será tu posición inicial.
Baja las pesas lentamente a tus lados mientras exhalas. Mantén el control total de las mancuernas en todo momento. Consejo: A lo largo de todo el movimiento, los antebrazos deben permanecer siempre perpendiculares al suelo.
Mientras exhalas, empuja las mancuernas hacia arriba usando los músculos pectorales. Bloquea los brazos en la posición contraída, aprieta el pecho, mantén durante un segundo y luego comienza a bajar lentamente. Consejo: Deberías tardar al menos el doble de tiempo en bajar que en subir.
Repite el movimiento durante la cantidad de repeticiones indicada en tu programa de entrenamiento.' WHERE name_en = 'Decline Dumbbell Bench Press';
UPDATE public.exercises SET instructions_es = 'Asegura tus piernas al final del banco declinado y acuéstate con una mancuerna en cada mano sobre tus muslos. Las palmas de las manos deben quedar mirándose entre sí.
Una vez acostado, mueve las mancuernas frente a ti al ancho de los hombros. Las palmas de las manos deben mirarse entre sí y los brazos deben estar perpendiculares al suelo y totalmente extendidos. Esta será tu posición inicial.
Con una ligera flexión en los codos para evitar la tensión en el tendón del bíceps, baja los brazos hacia ambos lados en un arco amplio hasta que sientas un estiramiento en el pecho. Inhala mientras realizas esta parte del movimiento. Consejo: Ten en cuenta que durante todo el movimiento los brazos deben permanecer fijos; el movimiento solo debe ocurrir en la articulación del hombro.
Regresa los brazos a la posición inicial mientras contraes los músculos del pecho y exhalas. Consejo: Asegúrate de usar la misma trayectoria en arco utilizada para bajar los pesos.
Mantén durante un segundo la posición contraída y repite el movimiento durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Decline Dumbbell Flyes';
UPDATE public.exercises SET instructions_es = 'Asegura tus piernas al final del banco declinado y acuéstate con una mancuerna en cada mano sobre tus muslos. Las palmas de tus manos deben quedar mirándose entre sí.
Una vez acostado, mueve las mancuernas frente a ti al ancho de los hombros. Las palmas de las manos deben mirarse entre sí y los brazos deben estar perpendiculares al suelo y totalmente extendidos. Esta será tu posición inicial.
Mientras inhalas y mantienes la parte superior de los brazos quieta (y los codos hacia adentro), baja las mancuernas lentamente moviendo los antebrazos en un movimiento semicircular hacia ti hasta que los pulgares queden al lado de tus orejas. Inhala mientras realizas esta parte del movimiento.
Vuelve a levantar las mancuernas a la posición inicial contrayendo los tríceps y exhalando.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Decline Dumbbell Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Asegura tus piernas al final del banco declinado y acuéstate lentamente sobre el banco.
Usando un agarre estrecho (un agarre ligeramente menor que el ancho de los hombros), levanta la barra EZ del soporte y sostenla directamente sobre ti con los brazos bloqueados y los codos hacia adentro. Los brazos deben estar perpendiculares al suelo. Esta será tu posición inicial. Consejo: Para proteger el manguito rotador, es mejor que un asistente te ayude a levantar la barra del soporte.
Mientras inhalas y mantienes la parte superior de los brazos inmóvil, baja la barra lentamente moviendo los antebrazos en un movimiento semicircular hacia ti hasta que sientas que la barra toca ligeramente tu frente. Inhala mientras realizas esta parte del movimiento.
Vuelve a levantar la barra a la posición inicial contrayendo los tríceps y exhalando.
Repite hasta realizar la cantidad recomendada de repeticiones.' WHERE name_en = 'Decline EZ Bar Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Asegura tus piernas al final del banco declinado y acuéstate lentamente sobre el banco.
Levanta la parte superior del cuerpo del banco hasta que el torso esté a unos 35-45 grados si se mide desde el suelo.
Pon una mano al lado de tu cabeza y la otra sobre tu muslo. Esta será tu posición inicial.
Levanta la parte superior del cuerpo lentamente desde la posición inicial mientras giras el torso hacia la izquierda. Continúa elevándote mientras exhalas hasta que tu codo derecho toque tu rodilla izquierda. Mantén esta posición contraída durante un segundo. Consejo: Concéntrate en mantener los abdominales contraídos y en que el movimiento sea lento y controlado.
Baja el cuerpo lentamente de nuevo a la posición inicial mientras inhalas.
Después de completar una serie en el lado derecho con la cantidad recomendada de repeticiones, cambia al lado izquierdo. Consejo: Concéntrate en girar bien el torso y sentir la contracción cuando estés en la posición elevada.' WHERE name_en = 'Decline Oblique Crunch';
UPDATE public.exercises SET instructions_es = 'Acuéstate boca abajo en el suelo y coloca las manos separadas a unos 90 cm mientras mantienes el torso erguido con los brazos extendidos. Eleva los pies colocándolos sobre una caja o banco. Esta será tu posición inicial.
A continuación, baja el cuerpo hacia abajo hasta que el pecho casi toque el suelo mientras inhalas.
Ahora exhala y empuja la parte superior del cuerpo de regreso a la posición inicial mientras contraes el pecho.
Tras una breve pausa en la posición de máxima contracción, puedes volver a bajarte para hacer tantas repeticiones como sean necesarias.' WHERE name_en = 'Decline Push-Up';
UPDATE public.exercises SET instructions_es = 'Acuéstate de espaldas en un banco declinado y sujétate a la parte superior del banco con ambas manos. No dejes que tu cuerpo se resbale hacia abajo desde esta posición.
Mantén las piernas paralelas al suelo usando tus abdominales para sostenerlas allí, manteniendo las rodillas y los pies juntos. Consejo: Tus piernas deben estar completamente extendidas con una ligera flexión en la rodilla. Esta será tu posición inicial.
Mientras exhalas, mueve las piernas hacia el torso mientras giras la pelvis hacia atrás y levantas las caderas del banco. Al final de este movimiento, tus rodillas estarán tocando tu pecho.
Mantén la contracción durante un segundo y vuelve a llevar las piernas a la posición inicial mientras inhalas.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Decline Reverse Crunch';
UPDATE public.exercises SET instructions_es = 'Coloca un banco declinado debajo de la máquina Smith. Ahora coloca la barra a una altura que puedas alcanzar cuando estés acostado y tus brazos estén casi completamente extendidos. Usando un agarre prono que sea más ancho que el ancho de los hombros, desbloquea la barra del soporte y sostenla directamente sobre ti con los brazos extendidos. Esta será tu posición inicial.
Mientras inhalas, baja la barra de manera controlada permitiendo que los codos se doblen, haciendo un ligero contacto con el torso.
Tras una breve pausa, vuelve a llevar la barra a la posición inicial extendiendo los codos y exhalando al hacerlo.
Repite el movimiento durante la cantidad prescrita de repeticiones.
Cuando se complete la serie, vuelve a bloquear la barra en el soporte.' WHERE name_en = 'Decline Smith Press';
UPDATE public.exercises SET instructions_es = 'Comienza teniendo una plataforma o discos de peso sobre los que puedas pararte, generalmente de 2.5 a 7.5 cm (1 a 3 pulgadas) de altura. Acércate a la barra de modo que quede centrada sobre tus pies. Tus pies deben estar separados aproximadamente al ancho de las caderas. Dóblate por la cadera para agarrar la barra al ancho de los hombros, permitiendo que tus escápulas se protraigan. Normalmente, usarías un agarre prono o un agarre mixto en series más pesadas.
Con los pies y el agarre colocados, toma una respiración profunda, baja las caderas y dobla las rodillas hasta que tus espinillas toquen la barra. Mira hacia adelante con la cabeza, mantén el pecho erguido y la espalda arqueada, y comienza a empujar con los talones para mover el peso hacia arriba. Después de que la barra pase las rodillas, tira agresivamente de la barra hacia atrás, juntando las escápulas mientras empujas las caderas hacia adelante contra la barra.
Baja la barra doblándote por las caderas y guiándola hacia el suelo.' WHERE name_en = 'Deficit Deadlift';
UPDATE public.exercises SET instructions_es = 'Para este ejercicio necesitarás dos cajas o bancos, uno de 30 a 40 cm (12 a 16 pulgadas) de alto y el otro de 55 a 65 cm (22 a 26 pulgadas) de alto.
Párate en una de las dos cajas con los brazos a los lados; los pies deben estar juntos y ligeramente fuera del borde como en el salto de profundidad. Coloca la otra caja aproximadamente a dos o tres pies (60-90 cm) enfrente tuyo.
Comienza dejándote caer de la caja inicial, aterrizando e impulsándote simultáneamente con ambos pies.
Rebota empujando hacia arriba y hacia adelante con la mayor intensidad posible, utilizando los brazos y la extensión completa del cuerpo para saltar a la caja más alta. Nuevamente, permite que las piernas absorban el impacto.' WHERE name_en = 'Depth Jump Leap';
UPDATE public.exercises SET instructions_es = 'Siéntate de forma segura en una máquina de fondos, selecciona el peso y sujeta firmemente los agarres.
Ahora mantén los codos pegados a los costados para poner énfasis en los tríceps. Los codos deben estar doblados en un ángulo de 90 grados.
Mientras contraes los tríceps, extiende los brazos hacia abajo mientras exhalas. Consejo: En la parte inferior del movimiento, concéntrate en mantener una ligera flexión en los brazos para mantener la tensión en el músculo tríceps.
Ahora deja lentamente que tus brazos vuelvan a subir a la posición inicial mientras inhalas.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Dip Machine';
UPDATE public.exercises SET instructions_es = 'Para este ejercicio necesitarás acceso a barras paralelas. Para colocarte en la posición inicial, sostén tu cuerpo con los brazos extendidos (brazos bloqueados) sobre las barras.
Mientras inhalas, bájate lentamente inclinando el torso hacia adelante unos 30 grados aproximadamente y con los codos ligeramente abiertos hacia afuera hasta que sientas un ligero estiramiento en el pecho.
Una vez que sientas el estiramiento, usa el pecho para llevar el cuerpo de regreso a la posición inicial mientras exhalas. Consejo: Recuerda contraer el pecho en la parte superior del movimiento durante un segundo.
Repite el movimiento durante la cantidad prescrita de repeticiones.' WHERE name_en = 'Dips - Chest Version';
UPDATE public.exercises SET instructions_es = 'Para colocarte en la posición inicial, sostén tu cuerpo con los brazos extendidos y casi bloqueados sobre las barras.
Ahora, inhala y bájate lentamente hacia abajo. El torso debe permanecer erguido y los codos deben mantenerse cerca del cuerpo. Esto ayuda a enfocar mejor el trabajo en los tríceps. Bájate hasta que se forme un ángulo de 90 grados entre la parte superior del brazo y el antebrazo.
Luego, exhala y empuja el torso de regreso hacia arriba usando los tríceps para llevar el cuerpo a la posición inicial.
Repite el movimiento durante la cantidad prescrita de repeticiones.' WHERE name_en = 'Dips - Triceps Version';
UPDATE public.exercises SET instructions_es = 'Para este ejercicio necesitarás acceso a una máquina de gemelos burro (donkey calf raise). Comienza colocando la parte inferior de la espalda y las caderas debajo de la palanca acolchada provista. La zona del cóccix debe ser la que haga contacto con el cojín.
Coloca ambos brazos en los agarres laterales y apoya las plantas de los pies sobre el bloque de gemelos con los talones sobresaliendo. Alinea los dedos de los pies hacia adelante, hacia adentro o hacia afuera, según la zona que desees trabajar, y extiende las rodillas sin bloquearlas. Esta será tu posición inicial.
Eleva los talones mientras exhalas extendiendo los tobillos lo más alto posible y contrayendo los gemelos. Asegúrate de mantener la rodilla inmóvil en todo momento. No debe haber ninguna flexión en ningún momento. Mantén la posición contraída durante un segundo antes de comenzar a bajar de nuevo.
Vuelve lentamente a la posición inicial mientras inhalas bajando los talones y doblando los tobillos hasta que los gemelos estén estirados.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Donkey Calf Raises';
UPDATE public.exercises SET instructions_es = 'Coloca dos pesas rusas (kettlebells) entre tus pies. Para ponerte en la posición inicial, empuja la cadera hacia atrás y mira hacia el frente.
Lleva una pesa rusa al hombro mediante una cargada (clean) y mantén sujeta la otra pesa rusa.
Con un movimiento fluido, baja la pesa rusa superior mientras impulsas la pesa rusa inferior hacia arriba.' WHERE name_en = 'Double Kettlebell Alternating Hang Clean';
UPDATE public.exercises SET instructions_es = 'Sujeta una pesa rusa por el asa en cada mano.
Lleva las pesas rusas a los hombros (clean) extendiendo las piernas y las caderas mientras tiras de ellas hacia tus hombros. Gira las muñecas al hacerlo, de modo que las palmas queden mirando hacia adelante. Esta será tu posición inicial.
Realiza un pequeño impulso doblando las rodillas, manteniendo el torso erguido.
Revierte la dirección inmediatamente empujando a través de los talones, esencialmente saltando para crear impulso.
Mientras lo haces, presiona las pesas rusas por encima de la cabeza hasta bloquear extendiendo los brazos, utilizando el impulso de tu cuerpo para mover los pesos.
Vuelve a apoyar los pies en el suelo en posición de zancada (split), con un pie adelante y otro atrás.
Manteniendo los pesos por encima de la cabeza, vuelve a la posición de pie juntando los pies. Baja los pesos para realizar la siguiente repetición.' WHERE name_en = 'Double Kettlebell Jerk';
UPDATE public.exercises SET instructions_es = 'Lleva dos pesas rusas a tus hombros (clean).
Haz una pequeña sentadilla de unos pocos centímetros y revierte el movimiento rápidamente. Usa el impulso de las piernas para empujar las pesas rusas por encima de la cabeza.
Una vez que las pesas rusas estén bloqueadas arriba, bájalas de nuevo a los hombros y repite.' WHERE name_en = 'Double Kettlebell Push Press';
UPDATE public.exercises SET instructions_es = 'Coloca dos pesas rusas detrás de tus pies. Dobla las rodillas y echa la cadera hacia atrás para tomar las pesas rusas.
Balancea las pesas rusas entre tus piernas con fuerza y revierte la dirección.
Empuja con fuerza con las caderas y bloquea las pesas rusas por encima de la cabeza en un solo movimiento ininterrumpido.' WHERE name_en = 'Double Kettlebell Snatch';
UPDATE public.exercises SET instructions_es = 'Coloca una pesa rusa frente a tu pie delantero y realiza una cargada y press (clean and press) por encima de la cabeza con el brazo opuesto. Lleva la pesa rusa al hombro extendiendo las piernas y las caderas mientras la tiras hacia tus hombros. Gira la muñeca al hacerlo, de modo que la palma mire hacia adelante.
Manteniendo la pesa rusa bloqueada arriba en todo momento, empuja el glúteo hacia afuera en la dirección de la pesa rusa bloqueada. Gira los pies hacia afuera en un ángulo de cuarenta y cinco grados con respecto al brazo que sostiene la pesa rusa arriba.
Doblaste por la cadera hacia un lado, sacando el glúteo, e inclínate lentamente hasta que puedas recoger la pesa rusa del suelo. Mantén la mirada fija en la pesa rusa que sostienes sobre tu cabeza en todo momento.
Haz una pausa de un segundo después de recoger la pesa rusa del suelo y revierte el movimiento para regresar a la posición inicial.' WHERE name_en = 'Double Kettlebell Windmill';
UPDATE public.exercises SET instructions_es = 'Comienza de pie con las rodillas ligeramente dobladas.
Haz una sentadilla rápida de corta distancia, flexionando las caderas y las rodillas, e inmediatamente extiéndete para saltar buscando la máxima altura vertical.
Mientras subes, recoge los talones flexionando las rodillas, intentando tocar los glúteos.
Finaliza el movimiento aterrizando con las rodillas solo parcialmente dobladas, usando las piernas para absorber el impacto.' WHERE name_en = 'Double Leg Butt Kick';
UPDATE public.exercises SET instructions_es = 'Acuéstate boca abajo sobre una pelota de ejercicio (fitball).
Mientras apoyas el estómago en la pelota, camina con las manos hacia adelante a lo largo del suelo y levanta las piernas, extendiendo los codos y las rodillas.' WHERE name_en = 'Downward Facing Balance';
UPDATE public.exercises SET instructions_es = 'Agarra una barra con un agarre supino (las palmas mirando hacia adelante) y coloca los codos cerca del torso y hacia atrás. Esta será tu posición inicial.
Mientras exhalas, flexiona la barra hacia arriba manteniendo los codos hacia atrás mientras "arrastras" la barra hacia arriba manteniéndola en contacto con el torso. Consejo: Como puedes ver, no mantendrás los codos pegados a los costados, sino que los llevarás hacia atrás. Tampoco levantes los hombros.
Vuelve lentamente a la posición inicial manteniendo la barra en contacto con el torso en todo momento.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Drag Curl';
UPDATE public.exercises SET instructions_es = 'Coloca cajas bajas u otras plataformas separadas a una distancia de 60 a 90 cm (2-3 pies).
Pónte en posición de flexión (lagartija) entre ellas, apoyándote colocando las manos sobre las cajas.
Con una buena postura, déjate caer de las plataformas empujando hacia arriba y moviendo las manos al ancho de los hombros, amortiguando el aterrizaje absorbiendo el impacto a través de los brazos.' WHERE name_en = 'Drop Push';
UPDATE public.exercises SET instructions_es = 'Párate (torso erguido) con una mancuerna en cada mano sostenida a la longitud de los brazos. Los codos deben estar cerca del torso y las palmas de las manos deben mirar hacia tus muslos.
Mientras mantienes inmóvil la parte superior del brazo, flexiona el peso derecho mientras giras la palma de la mano hasta que mire hacia adelante. En este punto, continúa contrayendo el bíceps mientras exhalas hasta que el bíceps esté completamente contraído y la mancuerna esté al nivel del hombro. Mantén la posición contraída durante un segundo mientras aprietas el bíceps. Consejo: Solo deben moverse los antebrazos.
Comienza a bajar lentamente la mancuerna de regreso a la posición inicial mientras inhalas. Consejo: Recuerda girar las palmas de regreso a la posición inicial (mirando a tus muslos) a medida que bajas.
Repite el movimiento con la mano izquierda. Esto equivale a una repetición.
Continúa alternando de esta manera durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Dumbbell Alternate Bicep Curl';
UPDATE public.exercises SET instructions_es = 'Acuéstate en un banco plano con una mancuerna en cada mano descansando sobre tus muslos. Las palmas de tus manos deben estar enfrentadas entre sí.
Luego, usando tus muslos para ayudar a subir las mancuernas, levanta las mancuernas una a la vez para sostenerlas frente a ti al ancho de los hombros.
Una vez al ancho de los hombros, gira las muñecas hacia adelante de modo que las palmas de tus manos queden mirando hacia afuera. Las mancuernas deben quedar justo a los lados del pecho, con el brazo y el antebrazo formando un ángulo de 90 grados. Asegúrate de mantener el control total de las mancuernas en todo momento. Esta será tu posición inicial.
Luego, mientras exhalas, usa el pecho para empujar las mancuernas hacia arriba. Bloquea los brazos en la parte superior del levantamiento y contrae el pecho, mantén la posición durante un segundo y luego comienza a bajar lentamente. Consejo: Lo ideal es que bajar el peso tome aproximadamente el doble de tiempo que subirlo.
Repite el movimiento durante la cantidad prescrita de repeticiones de tu programa de entrenamiento.' WHERE name_en = 'Dumbbell Bench Press';
UPDATE public.exercises SET instructions_es = 'Toma una mancuerna en cada mano y recuéstate en un banco plano. Tus pies deben estar apoyados completamente en el suelo y tus escápulas retraídas.
Manteniendo un agarre neutro, con las palmas enfrentadas entre sí, comienza con los brazos extendidos directamente sobre ti, perpendiculares al suelo. Esta será tu posición inicial.
Comienza el movimiento flexionando el codo, bajando los brazos hacia los costados. Desciende hasta que las mancuernas queden a la altura de tu torso.
Haz una pausa, luego extiende el codo y regresa a la posición inicial.' WHERE name_en = 'Dumbbell Bench Press with Neutral Grip';
UPDATE public.exercises SET instructions_es = 'Párate erguido con una mancuerna en cada mano a la longitud de los brazos. Mantén los codos cerca del torso y gira las palmas de tus manos hasta que miren hacia adelante. Esta será tu posición inicial.
Ahora, manteniendo inmóvil la parte superior de los brazos, exhala y flexiona los pesos mientras contraes los bíceps. Continúa levantando los pesos hasta que tus bíceps estén completamente contraídos y las mancuernas estén al nivel de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.
Luego, inhala y comienza a bajar lentamente las mancuernas de regreso a la posición inicial.
Repite durante la cantidad recomendada de repeticiones.' WHERE name_en = 'Dumbbell Bicep Curl';
UPDATE public.exercises SET instructions_es = 'Comienza de pie con una mancuerna en cada mano y los pies separados al ancho de los hombros.
Baja los pesos al suelo flexionando las caderas y las rodillas, empujando las caderas hacia atrás hasta que las mancuernas lleguen al suelo. Esta será tu posición inicial.
Para iniciar el movimiento, salta enérgicamente hacia arriba extendiendo las caderas, las rodillas y los tobillos para acelerar los pesos hacia arriba. Manteniendo un agarre neutro en las mancuernas, conserva los brazos rectos hasta alcanzar la extensión completa.
Tras la extensión completa, vuelve a doblar las caderas y las rodillas para recibir el peso en posición de sentadilla. Permite que los brazos se doblen, guiando las mancuernas hacia tus hombros.
Al recibir el peso en la posición de sentadilla, extiende las caderas y las rodillas para terminar en posición de pie con los pesos sobre tus hombros.' WHERE name_en = 'Dumbbell Clean';
UPDATE public.exercises SET instructions_es = 'Túmbate en el suelo sujetando una mancuerna en cada mano. Puedes doblar las rodillas. Comienza con los pesos totalmente extendidos por encima de ti.
Baja los pesos hasta que la parte superior del brazo entre en contacto con el suelo. Puedes recoger los codos para enfatizar el tamaño y la fuerza de los tríceps, o bien inclinar los brazos hacia los lados para concentrarte en el pecho.
Haz una pausa abajo y luego junta los pesos arriba extendiendo los codos.' WHERE name_en = 'Dumbbell Floor Press';
UPDATE public.exercises SET instructions_es = 'Acuéstate en un banco plano con una mancuerna en cada mano apoyada sobre tus muslos. Las palmas de las manos deben quedar mirándose entre sí.
Luego, usando los muslos para ayudarte a subir las mancuernas, levántalas de una en una para sostenerlas frente a ti al ancho de los hombros con las palmas mirándose entre sí. Eleva las mancuernas como si hicieras un press, pero detente justo antes de bloquear los codos. Esta será tu posición inicial.
Con una ligera flexión en los codos para evitar tensión en el tendón del bíceps, baja los brazos hacia ambos lados formando un arco amplio hasta sentir un estiramiento en el pecho. Inhala mientras realizas esta parte del movimiento. Consejo: Ten en cuenta que durante todo el movimiento los brazos deben permanecer fijos; el movimiento solo debe ocurrir en la articulación del hombro.
Regresa los brazos a la posición inicial mientras contraes los músculos pectorales y exhalas. Consejo: Asegúrate de usar el mismo arco de movimiento que usaste para bajar los pesos.
Mantén la posición contraída durante un segundo y repite el movimiento durante el número de repeticiones prescrito.' WHERE name_en = 'Dumbbell Flyes';
UPDATE public.exercises SET instructions_es = 'Usando un agarre neutro, apóyate en un banco inclinado.
Toma una mancuerna en cada mano con agarre neutro, comenzando con los brazos extendidos. Esta será tu posición inicial.
Retrae las escápulas y flexiona los codos para remar las mancuernas hacia tus costados.
Haz una pausa en la parte superior del movimiento y luego regresa a la posición inicial.' WHERE name_en = 'Dumbbell Incline Row';
UPDATE public.exercises SET instructions_es = 'Siéntate en un banco inclinado sosteniendo una mancuerna en cada mano sobre tus muslos.
Eleva las piernas para dar un impulso a las pesas hacia tus hombros y reclinándote hacia atrás. Coloca las mancuernas por encima de tus hombros con los brazos extendidos. Los brazos deben estar perpendiculares al suelo con las palmas mirando hacia adelante y los nudillos apuntando hacia el techo. Esta será tu posición inicial.
Mientras mantienes los brazos rectos y bloqueados, eleva las mancuernas levantando los hombros del banco mientras exhalas.
Regresa las mancuernas a la posición inicial mientras inhalas.
Repite el proceso durante el número recomendado de repeticiones.' WHERE name_en = 'Dumbbell Incline Shoulder Raise';
UPDATE public.exercises SET instructions_es = 'Ponte de pie con el torso erguido sosteniendo dos mancuernas con las manos a los lados. Esta será tu posición inicial.
Da un paso hacia adelante con la pierna derecha de aproximadamente 60 cm (2 pies) respecto al pie que queda fijo atrás y baja el torso, manteniendo el cuerpo erguido y el equilibrio. Inhala a medida que bajas. Nota: Al igual que en otros ejercicios, no permitas que la rodilla pase de la punta del pie al bajar, ya que esto sometería a la articulación de la rodilla a una tensión indebida. Asegúrate de mantener la espinilla delantera perpendicular al suelo.
Utilizando principalmente el talón del pie, empuja hacia arriba y regresa a la posición inicial mientras exhalas.
Repite el movimiento durante el número recomendado de repeticiones y luego hazlo con la pierna izquierda.' WHERE name_en = 'Dumbbell Lunges';
UPDATE public.exercises SET instructions_es = 'Mientras sostienes una mancuerna en una mano, túmbate boca abajo en un banco ajustable ligeramente inclinado (alrededor de 15 grados con respecto al suelo). La otra mano se puede usar para sujetar la pata del banco y mantener la estabilidad.
Coloca la palma de la mano que sostiene la mancuerna en posición neutra (con las palmas mirando hacia tu torso) mientras mantienes el brazo extendido con el codo ligeramente doblado. Esta será tu posición inicial.
Ahora eleva el brazo con la mancuerna hacia el lado hasta que el codo esté a la altura del hombro y el brazo quede aproximadamente paralelo al suelo mientras exhalas. Consejo: Mantén el brazo perpendicular al torso mientras lo mantienes extendido durante todo el movimiento. Además, mantén la contracción en la parte superior durante un segundo.
Baja lentamente la mancuerna a la posición inicial mientras inhalas.
Repite el proceso durante el número recomendado de repeticiones.' WHERE name_en = 'Dumbbell Lying One-Arm Rear Lateral Raise';
UPDATE public.exercises SET instructions_es = 'Acuéstate boca abajo en un banco plano sosteniendo una mancuerna con un brazo y con la otra mano apoyada y doblada sobre el banco para poder descansar la cabeza sobre ella.
Dobla el codo del brazo que sostiene la mancuerna formando un ángulo de 90 grados entre el brazo y el antebrazo.
Ahora eleva la parte superior del brazo de modo que el antebrazo quede perpendicular al suelo y la parte superior del brazo quede perpendicular a tu torso. Consejo: La parte superior del brazo debe quedar paralela al suelo y formando también un ángulo de 90 grados con el torso. Esta será tu posición inicial.
Mientras exhalas, rota externamente el antebrazo para que la mancuerna se eleve hacia adelante manteniendo la flexión en ángulo de 90 grados entre el brazo y el antebrazo. Continúa esta rotación externa hasta que el antebrazo quede paralelo al suelo. En este punto, mantén la contracción durante un segundo.
Mientras inhalas, regresa lentamente a la posición inicial.
Repite el proceso durante el número recomendado de repeticiones.' WHERE name_en = 'Dumbbell Lying Pronation';
UPDATE public.exercises SET instructions_es = 'Mientras sostienes una mancuerna en cada mano, túmbate boca abajo en un banco ajustable ligeramente inclinado (alrededor de 15 grados con respecto al suelo).
Coloca las palmas de las manos en posición neutra (con las palmas mirando hacia tu torso) mientras mantienes los brazos extendidos con los codos ligeramente doblados. Esta será tu posición inicial.
Ahora eleva los brazos hacia los lados hasta que tus codos estén a la altura de los hombros y los brazos queden aproximadamente paralelos al suelo mientras exhalas. Consejo: Mantén los brazos perpendiculares al torso mientras los mantienes extendidos durante todo el movimiento. Además, mantén la contracción en la parte superior durante un segundo.
Baja lentamente las mancuernas a la posición inicial mientras inhalas.
Repite el proceso durante el número recomendado de repeticiones y luego cambia al otro brazo.' WHERE name_en = 'Dumbbell Lying Rear Lateral Raise';
UPDATE public.exercises SET instructions_es = 'Acuéstate de lado en un banco plano sosteniendo una mancuerna con un brazo y con la otra mano apoyada y doblada sobre el banco para poder descansar la cabeza sobre ella.
Dobla el codo del brazo que sostiene la mancuerna de modo que forme un ángulo de 90 grados entre la parte superior del brazo y el antebrazo.
Ahora eleva el brazo para que el antebrazo quede paralelo al suelo y perpendicular a tu torso (Consejo: De modo que el antebrazo quede directamente frente a ti). El brazo permanecerá inmóvil junto a tu torso y debe estar paralelo al suelo (alineado con tu torso en todo momento). Esta será tu posición inicial.
Mientras exhalas, rota externamente el antebrazo para elevar la mancuerna en un movimiento semicircular mientras mantienes la flexión de 90 grados entre el brazo y el antebrazo. Continúa esta rotación externa hasta que el antebrazo esté perpendicular al suelo y el torso apunte hacia el techo. En este punto, mantén la contracción durante un segundo.
Mientras inhalas, regresa lentamente a la posición inicial.
Repite el proceso durante el número recomendado de repeticiones y luego cambia de brazo.' WHERE name_en = 'Dumbbell Lying Supination';
UPDATE public.exercises SET instructions_es = 'Toma una mancuerna y siéntate en un banco de press militar o en un banco auxiliar que tenga respaldo mientras colocas las mancuernas verticales sobre tus muslos, o bien ponte de pie totalmente erguido.
Lleva la mancuerna hasta la altura del hombro. La otra mano se puede mantener completamente extendida hacia el lado, en la cintura o sujetando una superficie fija.
Gira la muñeca para que la palma de la mano quede mirando hacia adelante. Esta es tu posición inicial.
Mientras exhalas, empuja la mancuerna hacia arriba hasta que el brazo esté completamente extendido.
Tras una pausa de un segundo, baja lentamente de nuevo a la posición inicial mientras inhalas.
Repite el proceso durante el número recomendado de repeticiones y luego cambia de brazo.' WHERE name_en = 'Dumbbell One-Arm Shoulder Press';
UPDATE public.exercises SET instructions_es = 'Toma una mancuerna y siéntate en un banco de press militar o en un banco auxiliar con respaldo apoyando las mancuernas verticales sobre los muslos, o ponte de pie totalmente erguido.
Sube la mancuerna hasta la altura de los hombros y luego extiende el brazo por encima de la cabeza para que todo el brazo quede perpendicular al suelo y junto a la cabeza. La mancuerna debe quedar por encima de ti. La otra mano se puede mantener totalmente extendida hacia un lado, en la cintura, sujetando el brazo de la mancuerna o agarrando una superficie fija.
Gira la muñeca para que la palma de la mano mire hacia adelante y el meñique apunte hacia el techo. Esta será tu posición inicial.
Baja lentamente la mancuerna por detrás de la cabeza manteniendo inmóvil el brazo. Inhala mientras realizas este movimiento y haz una pausa cuando los tríceps estén completamente estirados.
Regresa a la posición inicial contrayendo los tríceps mientras exhalas. Consejo: Es imprescindible que solo se mueva el antebrazo. El brazo debe permanecer en todo momento inmóvil junto a la cabeza.
Repite el proceso durante el número recomendado de repeticiones y cambia de brazo.' WHERE name_en = 'Dumbbell One-Arm Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Toma una mancuerna y ponte de pie con el brazo extendido frente a ti con una ligera flexión en el codo y la espalda recta. Esta será tu posición inicial. Consejo: La mancuerna debe descansar sobre tu muslo con la palma de la mano mirando hacia tus muslos.
La otra mano puede mantenerse completamente extendida al lado, en la cintura o sujetando una superficie fija. Esta será tu posición inicial.
Usa los hombros laterales para elevar la mancuerna mientras exhalas. La mancuerna debe permanecer cerca del cuerpo al subir. Continúa elevándola hasta que la mancuerna esté casi alineada con la barbilla. Consejo: Los codos deben guiar el movimiento. Al elevar la mancuerna, el codo siempre debe estar más alto que el antebrazo. Además, mantén el torso inmóvil y haz una pausa de un segundo en la parte superior del movimiento.
Baja la mancuerna lentamente de nuevo a la posición inicial. Inhala mientras realizas esta parte del movimiento.
Repite el proceso durante el número recomendado de repeticiones y cambia de brazo.' WHERE name_en = 'Dumbbell One-Arm Upright Row';
UPDATE public.exercises SET instructions_es = 'Toma una mancuerna en cada mano y túmbate boca abajo en un banco inclinado con los hombros cerca de la parte superior de la inclinación. Puedes apoyar las rodillas en el asiento o abrir las piernas a los lados (mi opción preferida).
Deja que los brazos se extiendan y cuelguen de forma natural frente a ti para que queden perpendiculares al suelo.
Ahora mantén los codos pegados a los costados y gira las palmas hacia adelante. Esta será tu posición inicial.
Eleva las mancuernas contrayendo los bíceps hasta que los brazos estén completamente flexionados. Exhala mientras realizas esta parte del movimiento y asegúrate de que solo se muevan los antebrazos. Los brazos deben permanecer inmóviles en todo momento.
Baja las mancuernas hasta que los brazos estén completamente extendidos.
Repite el número de veces recomendado.' WHERE name_en = 'Dumbbell Prone Incline Curl';
UPDATE public.exercises SET instructions_es = 'Toma una mancuerna en cada mano y ponte de pie con los brazos extendidos a los lados, con una ligera flexión en los codos y la espalda recta. Esta será tu posición inicial. Consejo: Las mancuernas deben estar junto a tus muslos con las palmas de las manos mirando hacia atrás.
Usa los hombros laterales para elevar las mancuernas mientras exhalas. Las mancuernas deben ir a los lados del cuerpo a medida que las subes. Continúa elevándolas hasta que estén casi alineadas con la barbilla. Consejo: Los codos deben guiar el movimiento. Al subir la mancuerna, el codo siempre debe estar más alto que el antebrazo. Mantén también el torso inmóvil y haz una pausa de un segundo en la parte superior del movimiento.
Baja las mancuernas lentamente a la posición inicial. Inhala mientras realizas esta parte del movimiento.
Repite el proceso durante el número recomendado de repeticiones.' WHERE name_en = 'Dumbbell Raise';
UPDATE public.exercises SET instructions_es = 'Ponte de pie con el torso erguido sosteniendo dos mancuernas con las manos a los lados. Esta será tu posición inicial.
Da un paso hacia atrás con la pierna derecha de unos 60 cm (2 pies) respecto al pie izquierdo y baja el torso, manteniendo el cuerpo erguido y el equilibrio. Inhala a medida que bajas. Consejo: Al igual que en otros ejercicios, no permitas que la rodilla pase de la punta del pie al bajar, ya que esto sometería a la articulación de la rodilla a una tensión indebida. Asegúrate de mantener la espinilla delantera perpendicular al suelo. Mantén el torso erguido durante la zancada; la flexibilidad de los flexores de la cadera es importante. Una zancada larga enfatiza el glúteo mayor; una zancada corta enfatiza los cuádriceps.
Empuja hacia arriba y regresa a la posición inicial mientras exhalas. Consejo: Usa el metatarso de los pies para empujar con el fin de acentuar el trabajo de los cuádriceps. Para concentrarte en los glúteos, presiona con los talones.
Ahora repite con la pierna opuesta.' WHERE name_en = 'Dumbbell Rear Lunge';
UPDATE public.exercises SET instructions_es = 'Este ejercicio correctivo fortalece los músculos que estabilizan la escápula. Sostén una pesa ligera en cada mano, dejándolas colgar a tus lados. Los pulgares deben apuntar hacia arriba.
Comienza el movimiento elevando los brazos al frente, a unos 30 grados del centro. Los brazos deben estar completamente extendidos mientras realizas el movimiento.
Continúa hasta que tus brazos queden paralelos al suelo y luego regresa a la posición inicial.' WHERE name_en = 'Dumbbell Scaption';
UPDATE public.exercises SET instructions_es = 'Coloca una caja a un par de pies (unos 60 cm) al lado de un banco. Sostén una mancuerna contra el pecho con ambas manos y siéntate en el banco mirando hacia la caja. Esta será tu posición inicial.
Planta los pies firmemente en el suelo mientras te inclinas hacia adelante, extendiendo las caderas y las rodillas para saltar hacia arriba y hacia adelante.
Aterriza en la caja con ambos pies, absorbiendo el impacto permitiendo que se doblen las caderas y las rodillas.
Baja de un paso y regresa a la posición inicial.' WHERE name_en = 'Dumbbell Seated Box Jump';
UPDATE public.exercises SET instructions_es = 'Coloca un bloque en el suelo a unos 30 cm (12 pulgadas) de un banco plano.
Siéntate en un banco plano y coloca una mancuerna sobre la parte superior del muslo izquierdo, a unos 7,5 cm (3 pulgadas) por encima de la rodilla.
Ahora coloca el metatarso del pie izquierdo sobre el bloque. Esta será tu posición inicial.
Eleva las puntas de los pies lo más alto posible mientras exhalas y contraes el músculo gemelo. Mantén la contracción durante un segundo.
Regresa lentamente a la posición inicial, estirando hacia abajo lo más posible.
Repite el número de repeticiones prescrito y luego repite con la pierna derecha.' WHERE name_en = 'Dumbbell Seated One-Leg Calf Raise';
UPDATE public.exercises SET instructions_es = 'Mientras sostienes una mancuerna en cada mano, siéntate en un banco de press militar o banco auxiliar que tenga respaldo. Coloca las mancuernas verticales sobre tus muslos.
Ahora sube las mancuernas a la altura de los hombros de una en una, usando los muslos para ayudarte a impulsarlas a su posición.
Asegúrate de girar las muñecas para que las palmas de las manos queden mirando hacia adelante. Esta es tu posición inicial.
Ahora, exhala y empuja las mancuernas hacia arriba hasta que se toquen en la parte superior.
Luego, tras una breve pausa en la posición contraída arriba, baja lentamente los pesos de nuevo a la posición inicial mientras inhalas.
Repite el proceso durante el número recomendado de repeticiones.' WHERE name_en = 'Dumbbell Shoulder Press';
UPDATE public.exercises SET instructions_es = 'Ponte erguido con una mancuerna en cada mano (las palmas mirando hacia el torso), los brazos extendidos a los lados.
Eleva las mancuernas subiendo los hombros lo más alto posible mientras exhalas. Mantén la contracción en la parte superior durante un segundo. Consejo: Los brazos deben permanecer extendidos en todo momento. Evita usar los bíceps para ayudar a elevar las mancuernas. Solo los hombros deben moverse hacia arriba y hacia abajo.
Baja las mancuernas de nuevo a la posición original.
Repite el proceso durante el número recomendado de repeticiones.' WHERE name_en = 'Dumbbell Shrug';
UPDATE public.exercises SET instructions_es = 'Ponte de pie erguido sosteniendo una mancuerna en la mano izquierda (palma mirando hacia el torso) mientras tienes la mano derecha en la cintura. Los pies deben estar colocados al ancho de los hombros. Esta será tu posición inicial.
Mientras mantienes la espalda recta y la cabeza erguida, dobla únicamente la cintura hacia la derecha lo más lejos posible. Inhala mientras te inclinas hacia el lado. Luego mantén la posición durante un segundo y regresa a la posición inicial mientras exhalas. Consejo: Mantén inmóvil el resto del cuerpo.
Ahora repite el movimiento pero inclinándote hacia la izquierda. Mantén la posición durante un segundo y regresa a la posición inicial.
Repite el proceso durante el número recomendado de repeticiones y luego cambia de mano.' WHERE name_en = 'Dumbbell Side Bend';
UPDATE public.exercises SET instructions_es = 'Ponte de pie erguido sosteniendo una mancuerna en cada mano (las palmas mirando al costado de las piernas).
Coloca las piernas usando una postura media a la anchura de los hombros con las puntas de los pies ligeramente hacia afuera. Mantén la cabeza erguida en todo momento, ya que mirar hacia abajo te desequilibrará, y mantén la espalda recta. Esta será tu posición inicial. Nota: Para los fines de esta explicación, utilizaremos la postura media descrita anteriormente que busca un desarrollo general; sin embargo, puedes elegir cualquiera de las tres posturas analizadas en la sección de posturas de los pies.
Comienza a bajar lentamente el torso doblando las rodillas mientras mantienes una postura erguida con la cabeza levantada. Continúa bajando hasta que los muslos queden paralelos al suelo. Consejo: Si realizaste el ejercicio correctamente, la parte delantera de las rodillas debe formar una línea recta imaginaria con las puntas de los pies que sea perpendicular al frente. Si tus rodillas sobrepasan esa línea imaginaria (si pasan las puntas de los pies), estás aplicando una tensión excesiva sobre la rodilla y el ejercicio se ha realizado de forma incorrecta.
Comienza a elevar el torso mientras exhalas empujando el suelo principalmente con el talón del pie mientras vuelves a extender las piernas y regresas a la posición inicial.
Repite el proceso durante el número recomendado de repeticiones.' WHERE name_en = 'Dumbbell Squat';
UPDATE public.exercises SET instructions_es = 'Ponte de pie erguido con un banco plano detrás de ti mientras sostienes una mancuerna en cada mano (las palmas mirando al costado de las piernas).
Coloca las piernas usando una postura media a la anchura de los hombros con las puntas de los pies ligeramente hacia afuera. Mantén la cabeza erguida en todo momento, ya que mirar hacia abajo te desequilibrará, y mantén la espalda recta. Esta será tu posición inicial. Nota: Para los fines de esta explicación, utilizaremos la postura media descrita anteriormente que busca un desarrollo general; sin embargo, puedes elegir cualquiera de las tres posturas analizadas en la sección de posturas de los pies.
Comienza a bajar lentamente el torso doblando las rodillas mientras mantienes una postura erguida con la cabeza levantada. Continúa bajando hasta tocar ligeramente el banco detrás de ti. Inhala mientras realizas esta parte del movimiento. Consejo: Si realizaste el ejercicio correctamente, la parte delantera de las rodillas debe formar una línea recta imaginaria con las puntas de los pies que sea perpendicular al frente. Si tus rodillas sobrepasan esa línea imaginaria (si pasan las puntas de los pies), estás aplicando una tensión excesiva sobre la rodilla y el ejercicio se ha realizado de forma incorrecta.
Comienza a elevar el torso mientras exhalas empujando el suelo principalmente con el talón del pie mientras vuelves a extender las piernas y regresas a la posición inicial.
Repite el proceso durante el número recomendado de repeticiones.' WHERE name_en = 'Dumbbell Squat To A Bench';
UPDATE public.exercises SET instructions_es = 'Ponte de pie erguido sosteniendo una mancuerna en cada mano (las palmas mirando al costado de las piernas).
Coloca el pie derecho sobre la plataforma elevada. Sube a la plataforma extendiendo la cadera y la rodilla de la pierna derecha. Usa principalmente el talón para elevar el resto del cuerpo y coloca también el pie de la pierna izquierda sobre la plataforma. Exhala mientras ejecutas la fuerza necesaria para subir.
Baja con la pierna izquierda flexionando la cadera y la rodilla de la pierna derecha mientras inhalas. Regresa a la posición inicial de pie colocando el pie derecho al lado del pie izquierdo en la posición inicial.
Repite con la pierna derecha durante el número recomendado de repeticiones y luego hazlo con la pierna izquierda.' WHERE name_en = 'Dumbbell Step Ups';
UPDATE public.exercises SET instructions_es = 'Acuéstate en un banco plano sosteniendo dos mancuernas directamente sobre tus hombros. Los brazos deben estar completamente extendidos y formar un ángulo de 90 grados con el torso y el suelo.
Las palmas de las manos deben mirar hacia adelante y los codos deben estar pegados al cuerpo. Esta será tu posición inicial.
Ahora, inhala y baja lentamente las mancuernas hasta que estén cerca de tus orejas. Asegúrate de mantener inmóviles los brazos y los codos pegados al cuerpo.
Luego, exhala y usa los tríceps para regresar el peso a la posición inicial.' WHERE name_en = 'Dumbbell Tricep Extension -Pronated Grip';
UPDATE public.exercises SET instructions_es = 'Ponte de pie con los pies separados al ancho de los hombros. Esta será tu posición inicial.
Manteniendo los brazos rectos, balancéalos hacia arriba frente a ti de 5 a 10 veces, aumentando el rango de movimiento cada vez hasta que tus brazos estén por encima de la cabeza.' WHERE name_en = 'Dynamic Back Stretch';
UPDATE public.exercises SET instructions_es = 'Ponte de pie con las manos juntas y los brazos extendidos directamente frente a ti. Esta será tu posición inicial.
Manteniendo los brazos rectos, mueve rápidamente los brazos hacia atrás lo más lejos posible y vuelve a juntarlos, de forma similar a un movimiento de aplauso exagerado. Repite de 5 a 10 veces, aumentando la velocidad a medida que lo haces.' WHERE name_en = 'Dynamic Chest Stretch';
UPDATE public.exercises SET instructions_es = 'Ponte de pie con la espalda recta mientras sujetas una barra EZ por el agarre exterior ancho. Las palmas de tus manos deben mirar hacia adelante y estar ligeramente inclinadas hacia adentro debido a la forma de la barra. Mantén los codos cerca del torso. Esta será tu posición inicial.
Ahora, mientras mantienes la parte superior de los brazos inmóvil, exhala y curva el peso hacia adelante mientras contraes los bíceps. Concéntrate en mover solo los antebrazos.
Continúa levantando el peso hasta que tus bíceps estén completamente contraídos y la barra esté al nivel de los hombros. Mantén la posición contraída en la parte superior durante un momento y aprieta los bíceps.
Luego inhala y baja lentamente la barra de nuevo a la posición inicial.
Repite según el número recomendado de repeticiones.' WHERE name_en = 'EZ-Bar Curl';
UPDATE public.exercises SET instructions_es = 'Con un agarre estrecho, levanta la barra EZ y sujétala con los codos hacia adentro mientras te acuestas en el banco. Tus brazos deben estar perpendiculares al suelo. Esta será tu posición inicial.
Manteniendo la parte superior de los brazos inmóvil, baja la barra flexionando los codos. Inhala mientras realizas esta parte del movimiento. Haz una pausa una vez que la barra esté directamente sobre la frente.
Levanta la barra de nuevo a la posición inicial extendiendo los codos y exhalando.
Repite.' WHERE name_en = 'EZ-Bar Skullcrusher';
UPDATE public.exercises SET instructions_es = 'Siéntate o ponte de pie con los pies ligeramente separados.
Coloca las manos sobre los hombros con los codos al nivel de los hombros y apuntando hacia afuera.
Haz un círculo lentamente con los codos. Exhala al comenzar el círculo e inhala al completarlo.' WHERE name_en = 'Elbow Circles';
UPDATE public.exercises SET instructions_es = 'Acuéstate en el suelo, cruzando la pierna derecha sobre la rodilla izquierda doblada. Entrelaza las manos detrás de la cabeza, comenzando con los escápulas en el suelo. Esta será tu posición inicial.
Realiza el movimiento flexionando la columna vertebral y girando el torso para llevar el codo izquierdo a la rodilla derecha.
Vuelve a la posición inicial y repite el movimiento durante el número deseado de repeticiones antes de cambiar de lado.' WHERE name_en = 'Elbow to Knee';
UPDATE public.exercises SET instructions_es = 'Ponte de pie con la espalda recta.
Coloca ambas manos en la parte baja de la espalda, con los dedos apuntando hacia abajo y los codos hacia afuera.
Luego, tira suavemente de los codos hacia atrás con el objetivo de tocarlos entre sí.' WHERE name_en = 'Elbows Back';
UPDATE public.exercises SET instructions_es = 'Coloca una barra en un soporte a la altura de los hombros cargada con el peso adecuado. Coloca una plataforma elevada y corta detrás de ti.
Apoya la barra en la parte superior de tu espalda, manteniendo la espalda arqueada y firme. Súbete a la plataforma elevada con ambos pies. Esta será tu posición inicial.
Comienza dando un paso hacia atrás con una pierna. Desciende flexionando las caderas y las rodillas hasta que la rodilla toque el suelo.
Haz una pausa y extiende las caderas y las rodillas para levantarte, regresando por completo a la posición inicial antes de alternar.' WHERE name_en = 'Elevated Back Lunge';
UPDATE public.exercises SET instructions_es = 'Consigue algún tipo de plataforma (puede ser una plataforma de aeróbicos o de elevación de talones) de entre 10 y 15 cm de altura.
Colócala en el asiento de la máquina de remo con polea.
Siéntate en la máquina y coloca los pies en la plataforma frontal o en la barra transversal proporcionada, asegurándote de que las rodillas estén ligeramente dobladas y no bloqueadas.
Inclínate hacia adelante manteniendo la alineación natural de tu espalda y agarra los agarres del manillar en V.
Con los brazos extendidos, tira hacia atrás hasta que tu torso esté en un ángulo de 90 grados con respecto a tus piernas. Tu espalda debe estar ligeramente arqueada y tu pecho erguido hacia afuera. Deberías sentir un buen estiramiento en los dorsales mientras mantienes la barra frente a ti. Esta es la posición inicial del ejercicio.
Manteniendo el torso inmóvil, tira de los agarres hacia tu torso manteniendo los brazos cerca de él hasta tocar los abdominales. Exhala mientras realizas este movimiento. En ese punto, deberías estar apretando fuertemente los músculos de la espalda. Mantén esa contracción durante un segundo y vuelve lentamente a la posición original mientras inhalas.
Repite según el número recomendado de repeticiones.' WHERE name_en = 'Elevated Cable Rows';
UPDATE public.exercises SET instructions_es = 'Para comenzar, súbete a la elíptica y selecciona la opción deseada del menú. La mayoría de las elípticas tienen un ajuste manual, o puedes seleccionar un programa para ejecutar. Por lo general, puedes ingresar tu edad y peso para estimar la cantidad de calorías quemadas durante el ejercicio. La elevación se puede ajustar para cambiar la intensidad del entrenamiento.
Los manillares se pueden usar para monitorear tu frecuencia cardíaca y ayudarte a mantener una intensidad adecuada.' WHERE name_en = 'Elliptical Trainer';
UPDATE public.exercises SET instructions_es = 'Acuéstate sobre una pelota de ejercicio con la curvatura de la parte baja de la espalda presionada contra la superficie esférica de la pelota. Tus pies deben estar doblados por la rodilla y presionados firmemente contra el suelo. La parte superior del torso debe colgar de la parte superior de la pelota. Los brazos deben mantenerse a los lados del cuerpo o cruzados sobre el pecho, ya que estas posiciones evitan tirones en el cuello (a diferencia de la posición de las manos detrás de la cabeza).
Baja el torso a una posición de estiramiento manteniendo el cuello inmóvil en todo momento. Esta será tu posición inicial.
Con las caderas inmóviles, flexiona la cintura contrayendo los abdominales y eleva los hombros y el tronco hacia arriba hasta que sientas una buena contracción en los abdominales. Los brazos simplemente deben deslizarse hacia arriba por el costado de tus piernas si los tienes a los lados, o quedarse sobre el pecho si los tienes cruzados. La parte baja de la espalda siempre debe permanecer en contacto con la pelota. Exhala mientras realizas este movimiento y mantén la contracción durante un segundo.
Mientras inhalas, vuelve a la posición inicial.
Repite según el número recomendado de repeticiones.' WHERE name_en = 'Exercise Ball Crunch';
UPDATE public.exercises SET instructions_es = 'Coloca una pelota de ejercicio cerca y acuéstate en el suelo frente a ella con las manos en el suelo a la anchura de los hombros en posición de flexión de brazos.
Ahora coloca la parte inferior de tus espinillas sobre la pelota de ejercicio. Consejo: En este punto, tus piernas deben estar completamente extendidas con las espinillas sobre la pelota y la parte superior del cuerpo debe estar en una posición tipo flexión, sostenida por tus dos brazos extendidos frente a ti. Esta será tu posición inicial.
Manteniendo la espalda completamente recta y la parte superior del cuerpo inmóvil, lleva las rodillas hacia el pecho mientras exhalas, dejando que la pelota ruede hacia adelante debajo de tus tobillos. Aprieta los abdominales y mantén esa posición durante un segundo.
Ahora extiende lentamente las piernas, haciendo rodar la pelota de regreso a la posición inicial mientras inhalas.
Repite según el número recomendado de repeticiones.' WHERE name_en = 'Exercise Ball Pull-In';
UPDATE public.exercises SET instructions_es = 'Acuéstate en el suelo y coloca una pesa rusa (kettlebell) lista para presionar con un brazo. La pesa rusa debe sostenerse por el asa. La pierna del mismo lado que estás presionando debe estar doblada, con la rodilla cruzando la línea media del cuerpo.
Presiona la pesa rusa extendiendo el codo y realizando una aducción del brazo, presionándola por encima de tu cuerpo. Regresa a la posición inicial.' WHERE name_en = 'Extended Range One-Arm Kettlebell Floor Press';
UPDATE public.exercises SET instructions_es = 'Acuéstate de lado en un banco plano con un brazo sosteniendo una mancuerna y la otra mano sobre el banco doblada para que puedas apoyar la cabeza en ella.
Dobla el codo del brazo que sostiene la mancuerna de modo que cree un ángulo de 90 grados entre el brazo y el antebrazo. Consejo: Mantén el brazo paralelo a tu torso.
Ahora dobla el codo mientras mantienes inmóvil la parte superior del brazo. De esta manera, el antebrazo estará paralelo al suelo y perpendicular a tu torso (Consejo: Para que el antebrazo esté directamente frente a ti). La parte superior del brazo estará inmóvil junto a tu torso y debe estar paralela al suelo (alineada con tu torso en todo momento). Esta será tu posición inicial.
Mientras exhalas, rota externamente el antebrazo para que la mancuerna se eleve en un movimiento semicircular mientras mantienes la flexión en ángulo de 90 grados entre la parte superior del brazo y el antebrazo. Continuarás esta rotación externa hasta que el antebrazo esté perpendicular al suelo y el torso apunte hacia el techo. En este punto, mantendrás la contracción durante un segundo.
Mientras inhalas, vuelve lentamente a la posición inicial.
Repite según el número recomendado de repeticiones y luego cambia al otro brazo.' WHERE name_en = 'External Rotation';
UPDATE public.exercises SET instructions_es = 'Engancha la banda elástica alrededor de un poste. La banda debe estar a la misma altura que tu codo. Ponte de pie con tu lado izquierdo hacia la banda a un par de pies (unos 60 cm) de distancia.
Sujeta el extremo de la banda con la mano derecha y mantén el codo firmemente presionado contra el costado. Recomendamos sostener una almohadilla o un rodillo de espuma en su lugar con el codo para mantenerlo firmemente en su posición.
Con la parte superior del brazo en posición, el codo debe estar flexionado a 90 grados con la mano cruzando la parte delantera de tu torso. Esta será tu posición inicial.
Ejecuta el movimiento girando el brazo con un movimiento de revés, manteniendo el codo en su lugar.
Continúa hasta donde te sea posible, haz una pausa y luego regresa a la posición inicial.' WHERE name_en = 'External Rotation with Band';
UPDATE public.exercises SET instructions_es = 'Ajusta el cable a la misma altura que tu codo. Ponte de pie con tu lado izquierdo hacia la banda a un par de pies (unos 60 cm) de distancia.
Sujeta el agarre con la mano derecha y mantén el codo firmemente presionado contra el costado. Recomendamos sostener una almohadilla o un rodillo de espuma en su lugar con el codo para mantenerlo firmemente en su posición.
Con la parte superior del brazo en posición, el codo debe estar flexionado a 90 grados con la mano cruzando la parte delantera de tu torso. Esta será tu posición inicial.
Ejecuta el movimiento girando el brazo con un movimiento de revés, manteniendo el codo en su lugar.' WHERE name_en = 'External Rotation with Cable';
UPDATE public.exercises SET instructions_es = 'Frente a una polea alta con una cuerda o dos agarres fijos, tira del peso directamente hacia tu cara, separando las manos a medida que lo haces. Mantén la parte superior de los brazos paralela al suelo.' WHERE name_en = 'Face Pull';
UPDATE public.exercises SET instructions_es = 'Existen varios implementos que se pueden usar para la caminata del granjero. Estos también se pueden realizar con mancuernas pesadas o barras cortas si estos implementos no están disponibles. Comienza poniéndote de pie entre los implementos.
Después de agarrar los manillares, levántalos empujando con los talones, manteniendo la espalda recta y la cabeza erguida.
Camina dando pasos cortos y rápidos, y no olvides respirar. Avanza una distancia determinada, normalmente de 15 a 30 metros (50-100 pies), lo más rápido posible.' WHERE name_en = 'Farmer''s Walk';
UPDATE public.exercises SET instructions_es = 'Comienza en una posición relajada con una pierna ligeramente hacia adelante. Esta será tu posición inicial.
Haz saltitos ejecutando un patrón de paso-salto de derecha-derecha-paso a izquierda-izquierda-paso, y así sucesivamente, alternando hacia adelante y hacia atrás.
Realiza saltos rápidos manteniendo un contacto cercano con el suelo y reduciendo el tiempo en el aire, moviéndote lo más rápido posible.' WHERE name_en = 'Fast Skipping';
UPDATE public.exercises SET instructions_es = 'Sostén una barra con ambas manos y las palmas mirando hacia arriba; las manos separadas aproximadamente al ancho de los hombros.
Coloca los pies apoyados sobre el suelo, a una distancia ligeramente superior al ancho de los hombros. Esta será tu posición inicial.
Baja la barra lo más lejos posible extendiendo los dedos. Dejando que la barra ruede hacia abajo por las manos, atrápala con la última falange de los dedos.
Ahora curva la barra hacia arriba lo más alto posible cerrando las manos mientras exhalas. Mantén la contracción en la parte superior.' WHERE name_en = 'Finger Curls';
UPDATE public.exercises SET instructions_es = 'Coloca un banco plano entre dos poleas bajas de modo que cuando te acuestes en él, tu pecho quede alineado con las poleas de los cables.
Acuéstate plano sobre el banco y mantén los pies en el suelo.
Pídele a alguien que te entregue los agarres en cada mano. Agarrarás cada agarre individual con las palmas mirando hacia arriba.
Extiende los brazos a los lados con una ligera flexión en los codos. Consejo: Mantendrás esta flexión constante durante todo el movimiento. Tus brazos deben estar paralelos al suelo. Esta es tu posición inicial.
Ahora comienza a levantar los brazos en un movimiento semicircular directamente frente a ti tirando de los cables hasta que ambas manos se junten en la parte superior del movimiento. Aprieta el pecho mientras realizas este movimiento y exhala durante él. Además, mantén la contracción durante un segundo en la parte superior. Consejo: Cuando se realiza correctamente, en la posición superior de este movimiento, tus brazos deben estar perpendiculares a tu torso y al suelo, tocándose por encima de tu pecho.
Vuelve lentamente a la posición inicial.
Repite según el número recomendado de repeticiones.' WHERE name_en = 'Flat Bench Cable Flyes';
UPDATE public.exercises SET instructions_es = 'Acuéstate sobre una colchoneta de ejercicio o un banco plano con las piernas sobresaliendo del extremo.
Coloca las manos debajo de los glúteos con las palmas hacia abajo o a los lados sujetándote al banco (o con las palmas hacia abajo a los lados en una colchoneta de ejercicio). Extiende también las piernas completamente rectas. Esta será tu posición inicial.
Dobla las rodillas y lleva la parte superior de los muslos hacia la parte media de tu cuerpo mientras exhalas. Continúa este movimiento hasta que tus rodillas estén cerca del pecho. Mantén la posición contraída durante un segundo.
Mientras inhalas, vuelve lentamente a la posición inicial.
Repite según el número recomendado de repeticiones.' WHERE name_en = 'Flat Bench Leg Pull-In';
UPDATE public.exercises SET instructions_es = 'Acuéstate con la espalda plana sobre un banco y las piernas extendidas frente a ti sobresaliendo del extremo.
Coloca las manos debajo de los glúteos con las palmas hacia abajo o a los lados sujetándote al banco. Esta será tu posición inicial.
Mientras mantienes las piernas extendidas, lo más rectas posible con las rodillas ligeramente flexionadas pero fijas, eleva las piernas hasta que formen un ángulo de 90 grados con el suelo. Exhala mientras realizas esta parte del movimiento y mantén la contracción en la parte superior durante un segundo.
Ahora, mientras inhalas, baja lentamente las piernas de regreso a la posición inicial.' WHERE name_en = 'Flat Bench Lying Leg Raise';
UPDATE public.exercises SET instructions_es = 'Sostén la mancuerna hacia el lado más alejado de ti para que tengas más peso en el lado más cercano a ti. (Esto se puede hacer para lograr un buen efecto en todos los ejercicios de bíceps con mancuernas). Ahora haz un curl con mancuernas inclinado normal, pero mantén las muñecas lo más atrás posible para neutralizar cualquier tensión ejercida sobre ellas.
Siéntate en un banco inclinado con un ángulo de 45 grados mientras sostienes una mancuerna en cada mano.
Deja caer los brazos a los lados, con los codos hacia adentro, y gira las palmas de las manos hacia adelante con los pulgares apuntando lejos del cuerpo. Consejo: Mantendrás esta posición de las manos durante todo el movimiento, ya que no debe haber ninguna torsión de las manos a medida que suben. Esta será tu posición inicial.
Eleva las dos mancuernas al mismo tiempo hasta que tus bíceps estén completamente contraídos y exhala. Consejo: No balances los brazos ni uses el impulso. Mantén un movimiento controlado en todo momento. Mantén la posición contraída durante un segundo en la parte superior.
Mientras inhalas, vuelve lentamente a la posición inicial.
Repite según el número recomendado de repeticiones.' WHERE name_en = 'Flexor Incline Dumbbell Curls';
UPDATE public.exercises SET instructions_es = 'Puedes contar con la ayuda de un compañero para este ejercicio o sujetar los pies debajo de algo estable.
Comienza de rodillas con la parte superior de las piernas y el torso en posición vertical. Si usas un compañero, este sujetará firmemente tus pies para mantenerte en posición. Esta será tu posición inicial.
Desciende extendiendo las rodillas, teniendo cuidado de NO flexionar las caderas a medida que avanzas hacia adelante.
Coloca las manos frente a ti al llegar al suelo. Este movimiento es muy difícil y es posible que no puedas hacerlo sin ayuda. Usa tus brazos para empujarte ligeramente desde el suelo para ayudarte a regresar a la posición inicial.' WHERE name_en = 'Floor Glute-Ham Raise';
UPDATE public.exercises SET instructions_es = 'Ajusta los soportes en J (j-hooks) para que queden a la altura adecuada para colocar la barra. Comienza acostado en el suelo con la cabeza cerca del final de una jaula de potencia. Manteniendo las escápulas retraídas, saca la barra de los soportes.
Baja la barra hacia la parte inferior del pecho o la parte superior del estómago, apretando la barra e intentando separarla mientras lo haces. Asegúrate de mantener los codos pegados al cuerpo durante todo el movimiento. Baja la barra hasta que la parte superior del brazo toque el suelo y haz una pausa, evitando cualquier golpe o rebote del peso.
Empuja la barra hacia arriba lo más rápido que puedas, manteniendo la barra, las muñecas y los codos alineados mientras lo haces.' WHERE name_en = 'Floor Press';
UPDATE public.exercises SET instructions_es = 'Ajusta los soportes en J para que queden a la altura adecuada para colocar la barra. Para este ejercicio, coloca las cadenas directamente sobre el extremo de la barra, tratando de mantener los extremos alejados de los discos.
Comienza acostado en el suelo con la cabeza cerca del final de una jaula de potencia. Manteniendo las escápulas retraídas, saca la barra de los soportes.
Baja la barra hacia la parte inferior del pecho o la parte superior del estómago, apretando la barra e intentando separarla mientras lo haces. Asegúrate de mantener los codos pegados al cuerpo durante todo el movimiento. Baja la barra hasta que la parte superior del brazo toque el suelo y haz una pausa, evitando cualquier golpe o rebote del peso.
Empuja la barra hacia arriba lo más rápido que puedas, manteniendo la barra, las muñecas y los codos alineados mientras lo haces.' WHERE name_en = 'Floor Press with Chains';
UPDATE public.exercises SET instructions_es = 'Acuéstate boca abajo en un banco plano con las caderas en el borde del banco, las piernas rectas con las puntas de los pies elevadas del suelo y los brazos sobre el banco sujetando el borde delantero.
Aprieta los glúteos e isquiotibiales y estira las piernas hasta que estén al nivel de las caderas. Esta será tu posición inicial.
Comienza el movimiento levantando la pierna izquierda más alto que la derecha.
Luego baja la pierna izquierda a la vez que levantas la derecha.
Continúa alternando de esta manera (como si estuvieras haciendo aleteo de patada en el agua) hasta completar la cantidad recomendada de repeticiones para cada pierna. Asegúrate de mantener un movimiento controlado en todo momento. Consejo: Respira con normalidad mientras realizas este movimiento.' WHERE name_en = 'Flutter Kicks';
UPDATE public.exercises SET instructions_es = 'Este ejercicio estira la fascia de los músculos de los pies. Comienza sentado y descalzo. Utilizando un rodillo para pies o un objeto similar, como un trozo pequeño de tubo de PVC, coloca el pie contra el rodillo a lo largo del arco del pie. Esta será tu posición inicial.
Presiona con firmeza rodando a lo largo del arco del pie. Mantén la presión durante 10-30 segundos y luego cambia de pie.' WHERE name_en = 'Foot-SMR';
UPDATE public.exercises SET instructions_es = 'Engancha un accesorio de doble agarre de cadena o cuerda al trineo. Debes estar de espaldas al trineo, sujetando un agarre en cada mano.
Comienza el movimiento dando un paso hacia adelante. Inclinándote hacia adelante, extiéndete a través de las piernas y las caderas para moverte, haciendo una pausa en cada paso para extender los codos, empujando tus manos hacia adelante. Da pasos hacia adelante hasta volver a la posición inicial preparado para empujar.' WHERE name_en = 'Forward Drag with Press';
UPDATE public.exercises SET instructions_es = 'Este ejercicio te enseña la posición adecuada tanto de la barra como de tu cuerpo durante la cargada (clean) y la sentadilla frontal.
Coloca la barra en la parte delantera de los hombros, soltando el agarre y extendiendo los brazos hacia adelante. Los hombros deben empujarse hacia adelante para crear un soporte, y la barra debe estar en contacto con la garganta. Asegúrate de mover solo las escápulas hacia adelante; no redondees la columna torácica.
Haz una sentadilla flexionando las rodillas y las caderas, sentándote entre las piernas. Mantén el torso erguido, los brazos arriba y los hombros hacia adelante, y la barra debería permanecer en su lugar. Baja hasta el fondo de la sentadilla, hasta que tus isquiotibiales toquen los gemelos.
Vuelve a la posición erguida empujando a través de la parte delantera del talón y extendiendo las rodillas y las caderas.' WHERE name_en = 'Frankenstein Squat';
UPDATE public.exercises SET instructions_es = 'Cruza los brazos sobre el pecho.
Con la cabeza erguida y la espalda recta, coloca los pies al ancho de los hombros.
Manteniendo la espalda recta y el pecho elevado, baja en sentadilla mientras inhalas hasta que la parte superior de los muslos quede paralela, o más abajo, con respecto al suelo.
Ahora, empujando principalmente con el metatarso de los pies, salta recto hacia arriba lo más alto posible, usando los muslos como resortes. Exhala durante esta parte del movimiento.
Cuando vuelvas a tocar el suelo, baja inmediatamente en sentadilla y salta de nuevo.
Repite la cantidad recomendada de repeticiones.' WHERE name_en = 'Freehand Jump Squat';
UPDATE public.exercises SET instructions_es = 'Ponte de pie con las manos detrás de la cabeza y baja en sentadilla manteniendo el torso erguido y la cabeza levantada. Esta será tu posición inicial.
Salta hacia adelante varios pies, evitando saltar innecesariamente alto. Cuando tus pies toquen el suelo, absorbe el impacto con las piernas y salta de nuevo. Repite esta acción de 5 a 10 veces.' WHERE name_en = 'Frog Hops';
UPDATE public.exercises SET instructions_es = 'Acuéstate con la espalda plana sobre el suelo (o una esterilla de ejercicio) y las piernas extendidas hacia adelante.
Ahora dobla las rodillas y coloca la parte exterior de los muslos cerca del suelo (o esterilla) mientras haces que las plantas de los pies se toquen entre sí.
Ahora intenta presionar ambas plantas y llevarlas lo más cerca posible de ti mientras mantienes la parte exterior de los muslos en el suelo (o al menos casi tocándolo). Consejo: En esta posición tus piernas deben formar un diamante.
Ahora, cruza los brazos frente a ti tocando los hombros opuestos. Esta será tu posición inicial.
Mientras exhalas, aplana la zona lumbar contra el suelo mientras flexionas el torso hacia arriba. Consejo: Esto será como realizar el primer 1/4 del movimiento de un abdominal (sit up). Mantén la posición elevada durante un segundo.
Mientras inhalas, baja lentamente de nuevo a la posición inicial.
Repite la cantidad recomendada de repeticiones.' WHERE name_en = 'Frog Sit-Ups';
UPDATE public.exercises SET instructions_es = 'Es mejor realizar este ejercicio dentro de una jaula de sentadillas por razones de seguridad. Para comenzar, primero ajusta la barra en el soporte a la altura que mejor se adapte a ti. Una vez elegida la altura correcta y cargada la barra, coloca los brazos por debajo de la barra manteniendo los codos altos y la parte superior del brazo ligeramente por encima del paralelo con el suelo. Apoya la barra sobre los deltoides y cruza los brazos mientras sujetas la barra para un control total.
Levanta la barra del soporte empujando primero con las piernas y, al mismo tiempo, enderezando el torso.
Aléjate del soporte y posiciona las piernas con una separación media a la anchura de los hombros y las puntas de los pies ligeramente apuntando hacia afuera. Mantén la cabeza erguida en todo momento, ya que mirar hacia abajo te desequilibrará, y mantén la espalda recta. Esta será tu posición inicial. (Nota: Para este propósito utilizaremos la posición media descrita anteriormente, que se enfoca en el desarrollo general; sin embargo, puedes elegir cualquiera de las tres posiciones descritas en la sección de colocación de los pies).
Comienza a bajar lentamente la barra doblando las rodillas mientras mantienes una postura erguida y la cabeza levantada. Continúa bajando hasta que el ángulo entre la parte superior de la pierna y los gemelos sea ligeramente inferior a 90 grados (el punto en el que la parte superior de las piernas está por debajo del paralelo con el suelo). Inhala mientras realizas esta parte del movimiento. Consejo: Si realizaste el ejercicio correctamente, la parte delantera de las rodillas debería formar una línea recta imaginaria con las puntas de los pies que sea perpendicular al frente. Si tus rodillas sobrepasan esa línea imaginaria (si pasan las puntas de los pies), estás ejerciendo una tensión indebida en la rodilla y el ejercicio se ha realizado de forma incorrecta.
Comienza a levantar la barra mientras exhalas empujando el suelo principalmente con la parte media del pie a medida que vuelves a estirar las piernas y regresas a la posición inicial.
Repite la cantidad recomendada de repeticiones.' WHERE name_en = 'Front Barbell Squat';
UPDATE public.exercises SET instructions_es = 'Es mejor realizar este ejercicio dentro de una jaula de sentadillas por razones de seguridad. Para comenzar, primero coloca un banco plano detrás de ti y ajusta la barra en el soporte a la altura que mejor se adapte a ti. Una vez elegida la altura correcta y cargada la barra, coloca los brazos por debajo de la barra manteniendo los codos altos y la parte superior del brazo ligeramente por encima del paralelo con el suelo. Apoya la barra sobre los deltoides y cruza los brazos mientras sujetas la barra para un control total.
Levanta la barra del soporte empujando primero con las piernas y, al mismo tiempo, enderezando el torso.
Aléjate del soporte y posiciona las piernas con una separación media a la anchura de los hombros y las puntas de los pies ligeramente apuntando hacia afuera. Mantén la cabeza erguida en todo momento, ya que mirar hacia abajo te desequilibrará, y mantén la espalda recta. Esta será tu posición inicial. (Nota: Para este propósito utilizaremos la posición media descrita anteriormente, que se enfoca en el desarrollo general; sin embargo, puedes elegir cualquiera de las tres posiciones descritas en la sección de colocación de los pies).
Comienza a bajar lentamente la barra doblando las rodillas mientras mantienes una postura erguida y la cabeza levantada. Continúa bajando hasta tocar el banco con los glúteos. Inhala mientras realizas esta parte del movimiento. Consejo: Si realizaste el ejercicio correctamente, la parte delantera de las rodillas debería formar una línea recta imaginaria con las puntas de los pies que sea perpendicular al frente. Si tus rodillas sobrepasan esa línea imaginaria (si pasan las puntas de los pies), estás ejerciendo una tensión indebida en la rodilla y el ejercicio se ha realizado de forma incorrecta.
Comienza a levantar la barra mientras exhalas empujando el suelo principalmente con el talón del pie a medida que vuelves a estirar las piernas y regresas a la posición inicial.
Repite la cantidad recomendada de repeticiones.' WHERE name_en = 'Front Barbell Squat To A Bench';
UPDATE public.exercises SET instructions_es = 'Comienza con un cajón de altura adecuada a 1-2 pies delante de ti. Ponte de pie con los pies a la anchura de los hombros. Esta será tu posición inicial.
Realiza una pequeña sentadilla como preparación para saltar, balanceando los brazos hacia atrás.
Impúlsate desde esta posición, extendiendo las caderas, las rodillas y los tobillos para saltar lo más alto posible. Balancea los brazos hacia adelante y hacia arriba.
Aterriza sobre el cajón con las rodillas flexionadas, absorbiendo el impacto con las piernas. Puedes saltar desde el cajón de vuelta al suelo o, preferiblemente, bajar una pierna a la vez.' WHERE name_en = 'Front Box Jump';
UPDATE public.exercises SET instructions_es = 'Selecciona el peso en una máquina de polea baja y sujeta con la mano izquierda el agarre individual enganchado a la polea baja.
Ponte de espaldas a la polea y coloca el brazo recto hacia abajo con el agarre frente a tus muslos a la longitud del brazo, con las palmas de las manos mirando hacia tus muslos. Esta será tu posición inicial.
Manteniendo el torso inmóvil (sin balanceos), levanta el brazo izquierdo hacia el frente con una ligera flexión en el codo y la palma de la mano siempre mirando hacia abajo. Continúa subiendo hasta que el brazo esté ligeramente por encima del paralelo con el suelo. Exhala mientras ejecutas esta parte del movimiento y haz una pausa de un segundo en la parte superior.
Ahora, mientras inhalas, baja el brazo lentamente de nuevo a la posición inicial.
Una vez completada la cantidad recomendada de repeticiones para este brazo, cambia de brazo y realiza el ejercicio con el derecho.' WHERE name_en = 'Front Cable Raise';
UPDATE public.exercises SET instructions_es = 'Coloca una fila de conos u otras pequeñas barreras, separándolos a unos pocos pies de distancia.
Ponte de pie frente al primer cono con los pies a la anchura de los hombros. Esta será tu posición inicial.
Comienza saltando con ambos pies sobre el primer cono, balanceando ambos brazos al saltar.
Absorbe el impacto del aterrizaje doblando las rodillas e impúlsate tras el primer salto para saltar sobre el siguiente cono.
Continúa hasta haber saltado sobre todos los conos.' WHERE name_en = 'Front Cone Hops (or hurdle hops)';
UPDATE public.exercises SET instructions_es = 'Coge un par de mancuernas y ponte de pie con el torso recto y las mancuernas frente a tus muslos a la longitud de los brazos, con las palmas de las manos mirando hacia tus muslos. Esta será tu posición inicial.
Manteniendo el torso inmóvil (sin balanceos), levanta la mancuerna izquierda hacia el frente con una ligera flexión en el codo y la palma de la mano siempre mirando hacia abajo. Continúa subiendo hasta que el brazo esté ligeramente por encima del paralelo con el suelo. Exhala mientras ejecutas esta parte del movimiento y haz una pausa de un segundo en la parte superior. Inhala después de la pausa de un segundo.
Ahora baja la mancuerna lentamente a la posición inicial mientras levantas simultáneamente la mancuerna derecha.
Continúa alternando de esta manera hasta completar la cantidad recomendada de repeticiones para cada brazo.' WHERE name_en = 'Front Dumbbell Raise';
UPDATE public.exercises SET instructions_es = 'Siéntate en un banco inclinado con la inclinación ajustada entre 30 y 60 grados mientras sostienes una mancuerna en cada mano. Consejo: Puedes cambiar el ángulo para trabajar el músculo de forma un poco diferente cada vez.
Extiende los brazos rectos hacia adelante con las palmas mirando hacia abajo y las mancuernas elevadas a aproximadamente 1 pulgada por encima de tus muslos. Esta será tu posición inicial.
Levanta lentamente las mancuernas hacia arriba hasta que estén ligeramente por encima de tus hombros, manteniendo los codos bloqueados. Aprieta en la parte superior durante un segundo y asegúrate de exhalar durante esta parte del movimiento. Consejo: Mantén la cabeza apoyada en el banco y las piernas en el suelo en todo momento.
Baja los brazos de nuevo a la posición inicial mientras inhalas.
Repite la cantidad recomendada de repeticiones.' WHERE name_en = 'Front Incline Dumbbell Raise';
UPDATE public.exercises SET instructions_es = 'Ponte de pie al lado de una silla u otro soporte, sujetándote con una mano.
Balancea la pierna hacia adelante, manteniéndola recta. Continúa con un balanceo hacia abajo, llevando la pierna tan atrás como te lo permita tu flexibilidad. Repite de 5 a 10 veces y luego cambia de pierna.' WHERE name_en = 'Front Leg Raises';
UPDATE public.exercises SET instructions_es = 'Mientras estás de pie erguido, sostiene un disco de barra con ambas manos en las posiciones de las 3 y las 9 en punto. Las palmas deben estar enfrentadas y los brazos deben estar extendidos y bloqueados con una ligera flexión en los codos, con el disco abajo cerca de la cintura frente a ti lo más abajo posible. Consejo: Los brazos permanecerán en esta posición durante todo el ejercicio. Esta será tu posición inicial.
Levanta lentamente el disco mientras exhalas hasta que esté un poco por encima del nivel de los hombros. Mantén la contracción durante un segundo. Consejo: Asegúrate de no balancear el peso ni doblar los codos. Tu torso también debe permanecer inmóvil durante todo el movimiento.
Mientras inhalas, baja lentamente el disco a la posición inicial.
Repite la cantidad recomendada de repeticiones.' WHERE name_en = 'Front Plate Raise';
UPDATE public.exercises SET instructions_es = 'Acuéstate en un banco plano mientras sostienes una barra con un agarre con las palmas hacia abajo a una distancia de unas 15 pulgadas entre sí.
Coloca la barra sobre la parte superior de los muslos, extiende los brazos y bloquéalos manteniendo una ligera flexión en los codos. Esta será tu posición inicial.
Ahora levanta el peso mediante un movimiento semicircular y manteniendo los brazos rectos mientras inhalas. Continúa el mismo movimiento hasta que la barra esté al otro lado, por encima de tu cabeza. (Consejo: la barra recorrerá aproximadamente 180 grados). En este punto, tus brazos deben estar paralelos al suelo con las palmas de las manos mirando al techo.
Ahora regresa la barra a la posición inicial invirtiendo el movimiento mientras exhalas.
Repite la cantidad recomendada de repeticiones.' WHERE name_en = 'Front Raise And Pullover';
UPDATE public.exercises SET instructions_es = 'Para comenzar, primero ajusta la barra en el soporte ligeramente por debajo del nivel de los hombros. Apoya la barra sobre los deltoides, presionando contra las clavículas y tocando ligeramente la garganta. Tus manos deben tener un agarre de cargada (clean), tocando la barra solo con los dedos para ayudar a mantenerla en posición.
Levanta la barra del soporte empujando primero con las piernas y, al mismo tiempo, enderezando el torso. Aléjate del soporte y posiciona las piernas con una separación media a la anchura de los hombros y las puntas de los pies ligeramente apuntando hacia afuera. Mantén la cabeza y los codos elevados en todo momento. Esta será tu posición inicial.
Dobla las rodillas, sentándote entre las piernas. Continúa bajando hasta que los isquiotibiales estén sobre los gemelos. Mantén las rodillas alineadas con los pies usando conscientemente tus abductores para empujar las rodillas hacia afuera a medida que haces la sentadilla.
Comienza a levantar la barra mientras exhalas empujando el suelo principalmente con el talón o la parte media del pie a medida que vuelves a estirar las piernas y regresas a la posición inicial.' WHERE name_en = 'Front Squat (Clean Grip)';
UPDATE public.exercises SET instructions_es = 'Lleva dos pesas rusas (kettlebells) a los hombros con una cargada (clean). Realiza la cargada extendiendo las piernas y las caderas mientras tiras de las pesas rusas hacia tus hombros. Gira las muñecas mientras lo haces.
Mirando directamente hacia adelante en todo momento, haz una sentadilla lo más profundo que puedas y haz una pausa abajo. A medida que bajas en sentadilla, empuja las rodillas hacia afuera. Debes hacer la sentadilla entre tus piernas, manteniendo el torso erguido, con la cabeza y el pecho elevados.
Vuelve a subir empujando a través de los talones y repite.' WHERE name_en = 'Front Squats With Two Kettlebells';
UPDATE public.exercises SET instructions_es = 'Coge un par de mancuernas y ponte de pie con el torso recto y las mancuernas frente a tus muslos a la longitud de los brazos, con las palmas de las manos mirando hacia tus muslos. Esta será tu posición inicial.
Manteniendo el torso inmóvil (sin balanceos), levanta las mancuernas hacia el frente con una ligera flexión en el codo y las palmas de las manos siempre mirando hacia abajo. Continúa subiendo hasta que los brazos estén ligeramente por encima del paralelo con el suelo. Exhala mientras ejecutas esta parte del movimiento y haz una pausa de un segundo en la parte superior.
Mientras inhalas, baja lentamente las mancuernas de nuevo a la posición inicial.
Repite la cantidad recomendada de repeticiones.' WHERE name_en = 'Front Two-Dumbbell Raise';
UPDATE public.exercises SET instructions_es = 'Ya sea de pie o sentado en un banco alto, sujeta dos agarres de estribo conectados a las poleas altas. Agárralos con la mano opuesta para que tus brazos queden cruzados frente a ti y tus palmas miren hacia adelante.
Manteniendo el pecho elevado y una ligera curvatura en la zona lumbar, tira de los agarres hacia abajo como si estuvieras haciendo un jalón al pecho normal. El rango de movimiento tendrá más forma de arco. Durante el movimiento, gira las manos para que en la posición inferior las palmas queden enfrentadas entre sí en lugar de mirar hacia adelante. Regresa lentamente a la posición inicial y repite.' WHERE name_en = 'Full Range-Of-Motion Lat Pulldown';
UPDATE public.exercises SET instructions_es = 'Sujeta la barra de dominadas con un agarre supino a la anchura de los hombros.
Ahora cuélgate con los brazos completamente extendidos, saca el pecho e inclínate hacia atrás. Consejo: Estarás inclinado hacia atrás durante todo el movimiento. Esta será tu posición inicial.
Comienza a elevarte hacia la barra con la columna arqueada durante todo el movimiento y la cabeza inclinada hacia atrás lo más alejada posible de la barra. Exhala mientras realizas esta parte del movimiento. Consejo: En la parte superior del movimiento, tus caderas y piernas estarán en un ángulo de unos 45 grados con respecto al suelo.
Sigue tirando hasta que la clavícula pase la barra y la parte inferior del pecho o la zona del esternón la toque. Mantén esa contracción durante un segundo. Consejo: Para cuando hayas completado esta parte del movimiento, tu cabeza estará paralela al suelo.
Comienza a bajar lentamente de nuevo a la posición inicial mientras inhalas.
Repite la cantidad recomendada de repeticiones.' WHERE name_en = 'Gironda Sternum Chins';
UPDATE public.exercises SET instructions_es = 'Comienza ajustando el equipo a tu cuerpo. Coloca los pies contra el reposapiés entre los rodillos mientras te acuestas boca abajo. Tus rodillas deben quedar justo detrás del cojín.
Empieza desde la parte inferior del movimiento. Mantén la espalda arqueada mientras inicias el movimiento flexionando las rodillas. Empuja con las puntas de los pies contra el reposapiés mientras lo haces. Mantén la parte superior del cuerpo recta y continúa hasta que tu cuerpo esté erguido.
Regresa a la posición inicial, manteniendo el descenso bajo control.' WHERE name_en = 'Glute Ham Raise';
UPDATE public.exercises SET instructions_es = 'Asegura un extremo de la banda a la parte inferior de un poste y sujeta el otro a un tobillo.
Ponte de espaldas al punto de sujeción de la banda.
Mantenimiento la cabeza y el pecho erguidos, eleva la rodilla hasta 90 grados y haz una pausa.
Regresa la pierna a la posición inicial.' WHERE name_en = 'Hip Flexion with Band';
UPDATE public.exercises SET instructions_es = 'Después de elegir una banda adecuada, recuéstate en el medio de la jaula o rack, tras asegurar la banda a ambos lados. Si tu rack no tiene clavijas, la banda se puede asegurar utilizando mancuernas pesadas u objetos similares, solo asegúrate de que no se muevan.
Ajusta tu posición de modo que la banda quede directamente sobre tus caderas. Dobla las rodillas y apoya los pies planos en el suelo. Puedes poner las manos en el suelo o sujetar la banda en su posición.
Mantenimiento los hombros en el suelo, empuja con los talones para elevar las caderas, presionando contra la banda lo más alto que puedas.
Haz una pausa en la parte superior del movimiento y regresa a la posición inicial.' WHERE name_en = 'Hip Lift with Band';
UPDATE public.exercises SET instructions_es = 'Siéntate en el suelo.
Ahorca un balón de ejercicio entre ambas piernas y baja las caderas hacia el suelo.
Abraza el balón con tus brazos para sostener tu cuerpo. Ajusta las piernas para que los pies queden planos en el suelo y las rodillas estén alineadas sobre los tobillos. Mantén un buen agarre en el balón para que no se te escape rodando y te haga caer de espaldas sobre tus glúteos.' WHERE name_en = 'Hug A Ball';
UPDATE public.exercises SET instructions_es = 'Recuéstate boca arriba y lleva ambas rodillas hacia el pecho.
Sostén tus brazos por debajo de las rodillas, no por encima (eso pondría demasiada presión en las articulaciones de tus rodillas).
Tira lentamente de las rodillas hacia tus hombros. Esto también estira los músculos de tus glúteos.' WHERE name_en = 'Hug Knees To Chest';
UPDATE public.exercises SET instructions_es = 'Coloca una fila de vallas u otras barreras pequeñas, separándolas a unos pocos pies de distancia.
Ponte de pie frente a la primera valla con los pies separados al ancho de los hombros. Esta será tu posición inicial.
Comienza saltando con ambos pies sobre la primera valla, balanceando ambos brazos al saltar.
Absorbe el impacto del aterrizaje doblando las rodillas y rebotando del primer salto para saltar la siguiente valla. Continúa hasta haber saltado todas las vallas.' WHERE name_en = 'Hurdle Hops';
UPDATE public.exercises SET instructions_es = 'Acuéstate boca abajo en un banco de hiperextensión, sujetando firmemente tus tobillos debajo de los cojines para los pies.
Ajusta el cojín superior si es posible para que la parte superior de tus muslos quede plana sobre el cojín ancho, dejando suficiente espacio para que te dobles por la cintura sin ninguna restricción.
Con el cuerpo recto, cruza los brazos por delante de ti (mi preferencia) o detrás de la cabeza. Esta será tu posición inicial. Consejo: También puedes sostener un disco de pesas por delante para obtener resistencia adicional debajo de tus brazos cruzados.
Comienza a doblarte hacia adelante lentamente por la cintura tanto como puedas manteniendo la espalda plana. Inhala mientras realizas este movimiento. Sigue avanzándote hacia adelante hasta que sientas un buen estiramiento en los isquiotibiales y ya no puedas continuar sin redondear la espalda. Consejo: Nunca redondees la espalda al realizar este ejercicio. Además, algunas personas pueden ir más lejos que otras. La clave es que llegues tan lejos como tu cuerpo te lo permita sin redondear la espalda.
Eleva lentamente el torso de regreso a la posición inicial mientras inhalas. Consejo: Evita la tentación de arquear la espalda más allá de una línea recta. Además, no balancees el torso en ningún momento para proteger la espalda de lesiones.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Hyperextensions (Back Extensions)';
UPDATE public.exercises SET instructions_es = 'Con alguien sujetando tus piernas, deslízate hacia el borde de un banco plano hasta que tus caderas queden fuera del extremo del banco. Consejo: Todo tu tren superior debe quedar colgando hacia el suelo. Además, estarás en la misma posición que si estuvieras en un banco de hiperextensión, pero el rango de movimiento será más corto debido a la altura del banco plano en comparación con la del banco de hiperextensión.
Con el cuerpo recto, cruza los brazos por delante de ti (mi preferencia) o detrás de la cabeza. Esta será tu posición inicial. Consejo: También puedes sostener un disco de pesas por delante para obtener resistencia adicional debajo de tus brazos cruzados.
Comienza a doblarte hacia adelante lentamente por la cintura tanto como puedas manteniendo la espalda plana. Inhala mientras realizas este movimiento. Sigue avanzándote hacia adelante hasta que casi toques el suelo o sientas un buen estiramiento en los isquiotibiales (lo que ocurra primero). Consejo: Nunca redondees la espalda al realizar este ejercicio.
Eleva lentamente el torso de regreso a la posición inicial mientras exhalas. Consejo: Evita la tentación de arquear la espalda más allá de una línea recta. Además, no balancees el torso en ningún momento para proteger la espalda de lesiones.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Hyperextensions With No Hyperextension Bench';
UPDATE public.exercises SET instructions_es = 'Pasa un cinturón, cuerda o banda alrededor de uno de tus pies y cruza esa pierna por encima de tu cuerpo hacia el lado opuesto, manteniendo la pierna extendida mientras estás acostado en el suelo. Esta será tu posición inicial.
Manteniendo el pie despegado del suelo, tira del cinturón utilizando la tensión para llevar los dedos del pie hacia arriba. Mantén la posición durante 10-20 segundos y repite en el otro lado.' WHERE name_en = 'IT Band and Glute Stretch';
UPDATE public.exercises SET instructions_es = 'Acuéstate de lado, con la pierna de abajo colocada sobre un rodillo de espuma (foam roller) entre la cadera y la rodilla. La otra pierna se puede cruzar por delante de ti.
Aplica tanto peso como sea tolerable sobre la pierna inferior; no es necesario mantener la pierna inferior en contacto con el suelo. Asegúrate de relajar los músculos de la pierna que estás estirando.
Haz rodar la pierna sobre la espuma desde la cadera hasta la rodilla, haciendo una pausa de 10 a 30 segundos en los puntos de tensión. Repite con la pierna opuesta.' WHERE name_en = 'Iliotibial Tract-SMR';
UPDATE public.exercises SET instructions_es = 'Ponte de pie con los pies juntos. Manteniendo las piernas rectas, estírate hacia abajo y pon las manos en el suelo directamente frente a ti. Esta será tu posición inicial.
Comienza caminando con las manos hacia adelante lentamente, alternando la izquierda y la derecha. Al hacerlo, dóblate solo por la cadera, manteniendo las piernas rectas.
Continúa hasta que tu cuerpo esté paralelo al suelo en posición de flexión de brazos.
Ahora, mantén las manos en su lugar y da pequeños pasos lentamente con los pies, moviéndote solo unos pocos centímetros a la vez.
Continúa caminando hasta que tus pies estén al lado de tus manos, manteniendo las piernas rectas mientras lo haces.' WHERE name_en = 'Inchworm';
UPDATE public.exercises SET instructions_es = 'Sostén una barra con un agarre prono (palmas hacia abajo) que esté un poco más cerrado que el ancho de los hombros.
Recuéstate en un banco inclinado ajustado a cualquier ángulo entre 45 y 75 grados.
Lleva la barra por encima de la cabeza con los brazos extendidos y los codos hacia adentro. Los brazos deben estar alineados con el torso por encima de la cabeza. Esta será tu posición inicial.
Ahora baja la barra con un movimiento semicircular detrás de tu cabeza hasta que tus antebrazos toquen tus bíceps. Inhala mientras realizas este movimiento. Consejo: Mantén la parte superior de los brazos inmóvil y cerca de la cabeza en todo momento. Solo deben moverse los antebrazos.
Regresa a la posición inicial mientras exhalas y contraes los tríceps. Mantén la contracción durante un segundo.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Incline Barbell Triceps Extension';
UPDATE public.exercises SET instructions_es = 'Toma una mancuerna en cada mano y acuéstate boca abajo en un banco inclinado con una inclinación de aproximadamente 30 grados.
Deja que los brazos cuelguen a tus lados totalmente extendidos mientras apuntan al suelo.
Gira las muñecas hasta que tus manos tengan un agarre prono (palmas hacia abajo).
Ahora abre los codos hacia afuera. Esta será tu posición inicial.
Mientras exhalas, comienza a tirar de las mancuernas hacia arriba como si estuvieras haciendo un press de banco invertido. Harás esto doblando los codos y elevando la parte superior de los brazos mientras dejas colgar los antebrazos. Continúa este movimiento hasta que la parte superior de los brazos esté al mismo nivel que tu espalda. Consejo: Los codos saldrán hacia los lados y la parte superior de tus brazos y el torso deben formar la letra "T" en la parte superior del movimiento. Mantén la contracción en la parte superior durante un segundo.
Baja lentamente de regreso a la posición inicial mientras inhalas.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Incline Bench Pull';
UPDATE public.exercises SET instructions_es = 'Ajusta el peso a una cantidad adecuada y siéntate, agarrando los agarres. La parte superior de tus brazos debe estar a unos 45 grados con respecto al cuerpo, con la cabeza y el pecho erguidos. Los codos deben estar doblados a unos 90 grados. Esta será tu posición inicial.
Comienza extendiendo los codos, presionando los agarres hacia adelante juntos directamente frente a ti. Mantén las escápulas retraídas mientras ejecutas el movimiento.
Después de hacer una pausa en la extensión completa, regresa a la posición inicial, manteniendo la tensión en los cables.' WHERE name_en = 'Incline Cable Chest Press';
UPDATE public.exercises SET instructions_es = 'Para colocarte en la posición inicial, ajusta las poleas al nivel del suelo (el nivel más bajo posible en la máquina que esté por debajo de tu torso).
Coloca un banco inclinado (ajustado a 45 grados) entre las poleas, selecciona un peso en cada una y toma una polea con cada mano.
Con un agarre en cada mano, recuéstate en el banco inclinado y junta las manos a la longitud de los brazos frente a tu cara. Esta será tu posición inicial.
Con una ligera flexión de los codos (para evitar el estrés en el tendón del bíceps), baja los brazos hacia ambos lados en un arco amplio hasta que sientas un estiramiento en el pecho. Inhala mientras realizas esta parte del movimiento. Consejo: Ten en cuenta que durante todo el movimiento los brazos deben permanecer inmóviles. El movimiento solo debe ocurrir en la articulación del hombro.
Regresa tus brazos a la posición inicial mientras aprietas los músculos del pecho y exhalas. Mantén la posición contraída durante un segundo. Consejo: Asegúrate de utilizar el mismo arco de movimiento utilizado para bajar los pesos.
Repite el movimiento durante la cantidad de repeticiones prescrita.' WHERE name_en = 'Incline Cable Flye';
UPDATE public.exercises SET instructions_es = 'Recuéstate en un banco inclinado con una mancuerna en cada mano sobre tus muslos. Las palmas de tus manos estarán enfrentadas entre sí.
Utilizando tus muslos para ayudarte a subir las mancuernas, lleva las mancuernas una por una a la altura de los hombros.
Una vez a la altura de los hombros, mantén las palmas de tus manos con un agarre neutro (las palmas mirándose entre sí). Mantén los codos abiertos hacia afuera con la parte superior de los brazos alineada con los hombros (perpendicular al torso) y los codos doblados creando un ángulo de 90 grados entre la parte superior del brazo y el antebrazo. Esta será tu posición inicial.
Ahora baja los pesos lentamente hacia tus lados mientras inhalas. Mantén el control total de las mancuernas en todo momento.
Mientras exhalas, empuja las mancuernas hacia arriba utilizando tus músculos pectorales. Bloquea los brazos en la posición contraída, mantén durante un segundo y luego comienza a bajar lentamente. Consejo: Debería tomar al menos el doble de tiempo bajar que subir.
Repite el movimiento durante la cantidad de repeticiones prescrita.
Cuando hayas terminado, vuelve a colocar las mancuernas sobre tus muslos y luego en el suelo. Esta es la forma más segura de soltar las mancuernas.' WHERE name_en = 'Incline Dumbbell Bench With Palms Facing In';
UPDATE public.exercises SET instructions_es = 'Siéntate en un banco inclinado con una mancuerna en cada mano a la longitud de los brazos. Mantén los codos cerca de tu torso y gira las palmas de tus manos hasta que miren hacia adelante. Esta será tu posición inicial.
Mientras mantienes inmóvil la parte superior del brazo, realiza un curl con los pesos hacia adelante mientras contraes los bíceps al exhalar. Solo deben moverse los antebrazos. Continúa el movimiento hasta que tus bíceps estén completamente contraídos y las mancuernas estén al nivel de los hombros. Mantén la posición contraída durante un segundo.
Comienza a regresar lentamente las mancuernas a la posición inicial mientras inhalas.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Incline Dumbbell Curl';
UPDATE public.exercises SET instructions_es = 'Sostén una mancuerna en cada mano y acuéstate en un banco inclinado que esté ajustado a un ángulo de inclinación de no más de 30 grados.
Extiende tus brazos por encima de ti con una ligera flexión en los codos.
Ahora gira las muñecas para que las palmas de tus manos queden mirando hacia ti. Consejo: Los dedos meñiques deben quedar uno al lado del otro. Esta será tu posición inicial.
Mientras inhalas, comienza a bajar lentamente los brazos hacia los lados manteniendo los brazos extendidos y girando las muñecas hasta que las palmas de las manos estén enfrentadas. Consejo: Al final del movimiento, los brazos estarán a tus lados con las palmas mirando hacia el techo.
Mientras exhalas, comienza a llevar las mancuernas de regreso a la posición inicial invirtiendo el movimiento y girando las manos para que los dedos meñiques queden nuevamente uno al lado del otro. Consejo: Ten en cuenta que el movimiento solo ocurrirá en la articulación del hombro y en la muñeca. No hay movimiento en la articulación del codo.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Incline Dumbbell Flyes';
UPDATE public.exercises SET instructions_es = 'Sostén una mancuerna en cada mano y acuéstate en un banco inclinado que esté ajustado a un ángulo de inclinación de no más de 30 grados.
Extiende tus brazos por encima de ti con una ligera flexión en los codos.
Ahora gira las muñecas para que las palmas de tus manos queden mirando hacia ti. Consejo: Los dedos meñiques deben quedar uno al lado del otro. Esta será tu posición inicial.
Mientras inhalas, comienza a bajar lentamente los brazos hacia los lados manteniendo los brazos extendidos y girando las muñecas hasta que las palmas de las manos estén enfrentadas. Consejo: Al final del movimiento, los brazos estarán a tus lados con las palmas mirando hacia el techo.
Mientras exhalas, comienza a llevar las mancuernas de regreso a la posición inicial invirtiendo el movimiento y girando las manos para que los dedos meñiques queden nuevamente uno al lado del otro. Consejo: Ten en cuenta que el movimiento solo ocurrirá en la articulación del hombro y en la muñeca. No hay movimiento en la articulación del codo.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Incline Dumbbell Flyes - With A Twist';
UPDATE public.exercises SET instructions_es = 'Recuéstate en un banco inclinado con una mancuerna en cada mano sobre tus muslos. Las palmas de tus manos estarán enfrentadas entre sí.
Luego, utilizando tus muslos para ayudarte a empujar las mancuernas hacia arriba, levanta las mancuernas una a la vez para que puedas sostenerlas al ancho de los hombros.
Una vez que hayas elevado las mancuernas al ancho de los hombros, gira tus muñecas hacia adelante para que las palmas de tus manos estén mirando en dirección opuesta a ti. Esta será tu posición inicial.
Asegúrate de mantener el control total de las mancuernas en todo momento. Luego exhala y empuja las mancuernas hacia arriba con el pecho.
Bloquea los brazos en la parte superior, mantén durante un segundo y luego comienza a bajar el peso lentamente. Consejo: Idealmente, bajar los pesos debería tomar aproximadamente el doble de tiempo que elevarlos.
Repite el movimiento durante la cantidad de repeticiones prescrita.
Cuando hayas terminado, vuelve a colocar las mancuernas sobre tus muslos y luego en el suelo. Esta es la forma más segura de soltar las mancuernas.' WHERE name_en = 'Incline Dumbbell Press';
UPDATE public.exercises SET instructions_es = 'Siéntate en un banco inclinado con una mancuerna en cada mano. Debes estar presionado firmemente contra el respaldo con los pies juntos. Deja que las mancuernas cuelguen completamente rectas a tus lados, sosteniéndolas con un agarre neutro. Esta será tu posición inicial.
Inicia el movimiento flexionando el codo, intentando mantener la parte superior del brazo inmóvil.
Continúa hasta la parte superior del movimiento y haz una pausa, luego regresa lentamente a la posición inicial.' WHERE name_en = 'Incline Hammer Curls';
UPDATE public.exercises SET instructions_es = 'Sostén una mancuerna en cada mano y recuéstate en un banco inclinado.
Las mancuernas deben estar a la longitud de los brazos colgando a tus lados y tus palmas deben mirar hacia afuera. Esta será tu posición inicial.
Ahora, mientras exhalas, realiza un curl con el peso hacia afuera y hacia arriba mientras mantienes tus antebrazos alineados con tus deltoides laterales. Continúa el curl hasta que las mancuernas estén a la altura de los hombros y a los lados de tus deltoides. Consejo: El final del movimiento debe verse similar a una pose de doble bíceps.
Después de una segunda contracción en la parte superior del movimiento, comienza a inhalar y baja lentamente las pesas de regreso a la posición inicial siguiendo el mismo recorrido utilizado para subirlas.
Repite durante la cantidad de repeticiones recomendada.' WHERE name_en = 'Incline Inner Biceps Curl';
UPDATE public.exercises SET instructions_es = 'Ponte de pie frente a un banco o una plataforma elevada resistente. Coloca las manos en el borde del banco o plataforma, un poco más separadas que el ancho de los hombros.
Posiciona la parte delantera de los pies hacia atrás desde el banco o plataforma con los brazos y el cuerpo rectos. Los brazos deben estar perpendiculares al cuerpo. Manteniendo el cuerpo recto, baja el pecho hasta el borde de la caja o plataforma doblando los brazos.
Empuja el cuerpo hacia arriba hasta que los brazos estén extendidos. Repite.' WHERE name_en = 'Incline Push-Up';
UPDATE public.exercises SET instructions_es = 'Ponte de pie frente a la barra de una máquina Smith o una plataforma elevada resistente a una altura adecuada.
Coloca tus manos una al lado de la otra en la barra.
Posiciona tus pies hacia atrás desde la barra con los brazos y el cuerpo rectos. Esta será tu posición inicial.
Manteniendo el cuerpo recto, baja el pecho hacia la barra doblando los brazos.
Regresa a la posición inicial extendiendo los codos, empujándote de nuevo hacia arriba.' WHERE name_en = 'Incline Push-Up Close-Grip';
UPDATE public.exercises SET instructions_es = 'Para este ejercicio necesitarás un cajón de unas 12 pulgadas de alto y dos colchonetas gruesas o escalones de aeróbicos (steps).
Coloca los escalones justo por fuera de tus hombros y coloca los pies encima de la caja para quedar en posición de flexión inclinada, con las manos justo por dentro de los escalones. Esta será tu posición inicial.
Comienza doblando los codos para bajar el cuerpo, invirtiendo rápidamente la posición para impulsar tu cuerpo fuera del suelo. Al despegarte del suelo, mueve las manos hacia los escalones, doblando los codos para absorber el impacto.
Repite el movimiento para regresar a la posición inicial.' WHERE name_en = 'Incline Push-Up Depth Jump';
UPDATE public.exercises SET instructions_es = 'Ponte de pie frente a la barra de una máquina Smith o una plataforma elevada resistente a una altura adecuada.
Coloca tus manos en la barra, separadas aproximadamente al ancho de los hombros.
Posiciona tus pies hacia atrás desde la barra con los brazos y el cuerpo rectos. Esta será tu posición inicial.
Manteniendo el cuerpo recto, baja el pecho hacia la barra doblando los brazos.
Regresa a la posición inicial extendiendo los codos, empujándote de nuevo hacia arriba.' WHERE name_en = 'Incline Push-Up Medium';
